import type { Ctx, View } from '../app';
import type { Business } from '../../sim/types';
import { playerBusinesses } from '../../sim/state';
import { district } from '../../data/districts';
import { money } from '../../sim/format';
import { createFloor, floorRates, reportOn, type Agent, type FloorWorld } from '../../sim/floor';
import {
  RESALE,
  autoAssign,
  conditionOf,
  layoutFor,
  layoutOf,
  place,
  remove,
  repair,
  repairCost,
  statusOf,
} from '../../sim/layout';
import { ITEMS } from '../../data/buildingItems';
import { businessTypeOrThrow } from '../../data/businessTypes';
import { TRADE_NAMES, openingKit, readinessOf, tradeOf } from '../../sim/needs';
import { onDuty } from '../../sim/rota';
import { performanceOf, titleOf } from '../../sim/skills';
import { item } from '../../data/buildingItems';
import { FloorCanvas, type Pick } from '../floorCanvas';
import { bar, button, empty, h, pills, stat, tag, toast } from '../dom';
import { icon } from '../icons';

/**
 * Inside the business.
 *
 * The screen this whole overhaul exists for. Everything the player has bought,
 * built, hired and scheduled is standing in one room, working, and they can
 * watch it: the shelves they paid for with the stock they ordered on them, the
 * tills they installed with the cashiers they rostered behind them, and the
 * customers their marketing brought in walking between the two.
 *
 * It is a window, not a second game. The room is the layout from the building
 * designer, the staff are the people the rota has on, the rate people come
 * through the door is the demand the business is really seeing, and the rate
 * they get served is the throughput it really has. So when the queue backs up
 * and somebody walks out, that is not a story the animation is telling — it is
 * the "turned away" line in the day's figures, happening.
 */

/** Kept between visits so coming back does not reset the camera or the tab. */
let lastBusinessId: string | null = null;
/** Whether the build tray is open, and what is on the end of the pointer. */
let building = false;
let holding: { defId: string; rot: 0 | 90 | 180 | 270 } | null = null;

export function floorView(ctx: Ctx): View {
  const el = h('div', { class: 'view floor-view' });
  let canvas: FloorCanvas | null = null;
  let world: FloorWorld | null = null;
  let inspector: HTMLElement = h('div', { class: 'floor-inspect' });
  let hud: HTMLElement = h('div', { class: 'floor-hud' });
  let timer: number | null = null;

  const businesses = playerBusinesses(ctx.state).filter((b) => b.status !== 'closed');
  const wanted = ctx.params.business ?? lastBusinessId;
  const business = businesses.find((b) => b.id === wanted) ?? businesses[0] ?? null;

  const render = (): void => {
    el.replaceChildren();

    if (!business) {
      el.appendChild(
        h(
          'div',
          { class: 'view-head' },
          h('h1', { text: 'The floor' }),
          h('p', { text: 'Walk into one of your businesses and watch it work.' }),
        ),
      );
      el.appendChild(
        empty('You have nowhere to walk into yet.', {
          title: 'No business open',
          action: button('Find a unit', () => ctx.go('map'), 'btn primary'),
        }),
      );
      return;
    }
    lastBusinessId = business.id;

    // A layout is created on demand with the kit this trade opens with, which
    // is the same function the designer uses — so walking in never produces an
    // empty shell that the designer would have furnished.
    const existing = layoutOf(ctx.state, business.buildingId);
    const layout = existing ?? layoutFor(ctx.state, business.buildingId, openingKit(ctx.state, business));
    // A floor that has just been laid out has stations and nobody standing at
    // them. Seating the team is the same call the designer makes, and doing it
    // here means walking in for the first time shows a working business rather
    // than six people stood by the door with nothing to do.
    if (!existing && layout) autoAssign(ctx.state, layout);

    el.appendChild(head(ctx, business, businesses, render));

    if (!layout) {
      el.appendChild(empty('This building has no floor plan yet.', { title: 'Nothing built' }));
      return;
    }

    const stage = h('div', { class: 'floor-stage' });
    el.appendChild(stage);

    hud = h('div', { class: 'floor-hud' });
    inspector = h('div', { class: 'floor-inspect' });
    stage.appendChild(hud);
    stage.appendChild(inspector);
    stage.appendChild(tools(() => canvas, render));
    if (building) stage.appendChild(buildTray(business, () => canvas, render));

    // The canvas goes in last so the overlays sit above it.
    requestAnimationFrame(() => {
      canvas?.destroy();
      canvas = new FloorCanvas(stage, () => ctx.state, business.id);
      world = createFloor(ctx.state, business, 0);
      canvas.setWorld(world);
      canvas.onPick = (pick) => drawInspector(ctx, business, pick, canvas, render);
      canvas.placing = building ? holding : null;
      canvas.onPlace = (defId, x, y, rot) => {
        const plan = layoutOf(ctx.state, business.buildingId);
        if (!plan) return;
        // Straight through the same placement the designer uses, so the price,
        // the rules and the ledger entry are all the ones that already existed.
        const result = place(ctx.state, plan, defId, 0, x, y, rot);
        toast(result.message, result.ok ? 'good' : 'bad');
        // The thing is standing there on the very next frame, and the floor's
        // navigation grid picks it up on the one after that, so people start
        // walking round it immediately.
        canvas?.paint();
      };
      canvas.resize();
      canvas.start();
      // "Show me this person": arrive with the camera already on them and a
      // ring under their feet, rather than on a room and a hunt.
      const wantedPerson = ctx.params.employee;
      if (wantedPerson) {
        canvas.focusAgent(`staff_${wantedPerson}`);
        const found = world?.agents.find((a) => a.id === `staff_${wantedPerson}`);
        drawInspector(ctx, business, found ? { kind: 'agent', id: found.id } : null, canvas, render);
      }
      if (world) drawHud(ctx, business, world);
      drawInspector(ctx, business, null, canvas, render);

      // The figures beside the room update on their own clock rather than on
      // every frame, because nobody needs a queue length redrawn sixty times a
      // second and the room is where the eye is.
      if (timer !== null) window.clearInterval(timer);
      timer = window.setInterval(() => {
        if (world) drawHud(ctx, business, world);
      }, 700);
    });
  };

  const drawHud = (context: Ctx, subject: Business, live: FloorWorld): void => {
    const state = context.state;
    const rates = floorRates(state, subject);
    const staff = onDuty(state, subject);
    const customers = live.agents.filter((a) => a.kind === 'customer');
    const queue = customers.filter((a) => a.state === 'queueing' || a.state === 'paying').length;
    const stranded = live.agents.filter((a) => a.state === 'stranded').length;
    const readiness = readinessOf(state, subject);

    hud.replaceChildren(
      h(
        'div',
        { class: 'floor-figures' },
        liveStat('In the shop', `${customers.length}`, 'people'),
        liveStat('Queueing', `${queue}`, queue > 3 ? 'too long' : 'moving', queue > 3 ? 'bad' : undefined),
        liveStat('On shift', `${staff.length}`, stranded > 0 ? `${stranded} idle` : 'in position', stranded > 0 ? 'bad' : undefined),
        liveStat('Arriving', `${Math.round(rates.arrivals)}/h`, `serves ${Math.round(rates.capacity)}/h`, rates.arrivals > rates.capacity * 1.15 ? 'bad' : 'good'),
      ),
      h(
        'div',
        { class: 'floor-readout' },
        h('span', {
          class: 'sub',
          text: `${TRADE_NAMES[tradeOf(subject)]} · ${
            readiness.bottleneck ? `held back by ${readiness.bottleneck.name.toLowerCase()}` : 'everything it needs'
          }`,
        }),
        bar(readiness.overall / 100, readiness.overall > 70 ? 'good' : readiness.overall < 40 ? 'bad' : ''),
      ),
    );
  };

  render();

  return {
    el,
    destroy: () => {
      if (timer !== null) window.clearInterval(timer);
      canvas?.destroy();
      canvas = null;
    },
  };
}

// ------------------------------------------------------------------ chrome

function head(ctx: Ctx, business: Business, all: Business[], render: () => void): HTMLElement {
  return h(
    'div',
    { class: 'view-head floor-head' },
    h(
      'div',
      {},
      h('h1', { text: business.name }),
      h('p', { text: 'Your business, working. Click anything in the room to see what it is doing.' }),
    ),
    all.length > 1
      ? pills(
          all.map((b) => ({ value: b.id, label: nameFor(ctx, all, b) })),
          business.id,
          (value) => {
            lastBusinessId = value;
            ctx.go('floor', { business: value });
            void render;
          },
        )
      : null,
  );
}

/**
 * A business by name, and by where it is when the name is not enough.
 *
 * Two shops of the same trade end up with the same name, and a row of pills
 * with two identical buttons on it is a row you cannot use.
 */
function nameFor(ctx: Ctx, all: Business[], business: Business): string {
  if (all.filter((other) => other.name === business.name).length < 2) return business.name;
  const building = ctx.state.buildings.find((b) => b.id === business.buildingId);
  return building ? `${business.name} · ${district(building.district).name}` : business.name;
}

function tools(get: () => FloorCanvas | null, render: () => void): HTMLElement {
  const iconButton = (name: string, title: string, run: () => void): HTMLElement =>
    h('button', { class: 'icon-btn', title, aria: { label: title }, on: { click: run } }, icon(name, 16));

  return h(
    'div',
    { class: 'floor-tools' },
    h(
      'button',
      {
        class: `icon-btn${building ? ' active' : ''}`,
        title: building ? 'Stop building' : 'Build something',
        aria: { label: 'Build' },
        on: {
          click: () => {
            building = !building;
            if (!building) holding = null;
            const canvas = get();
            if (canvas) {
              canvas.placing = null;
              // The tray covers the front of the room, which is where the door
              // and the queue are, so the camera moves up out of its way.
              canvas.panBy(0, building ? -canvas.canvas.clientHeight * 0.18 : canvas.canvas.clientHeight * 0.18);
            }
            render();
          },
        },
      },
      icon('build', 16),
    ),
    iconButton('plus', 'Zoom in', () => get()?.zoomBy(1.25)),
    h('button', { class: 'icon-btn', title: 'Zoom out', aria: { label: 'Zoom out' }, on: { click: () => get()?.zoomBy(1 / 1.25) } }, '−'),
    iconButton('map', 'Fit the whole floor', () => get()?.fit()),
    h(
      'button',
      {
        class: 'icon-btn',
        title: 'How fast the floor runs',
        aria: { label: 'Floor speed' },
        on: {
          click: () => {
            const canvas = get();
            if (!canvas) return;
            canvas.speed = canvas.speed >= 60 ? 10 : canvas.speed * 2;
            toast(`Floor running at ${canvas.speed}× — the game's own clock is unchanged.`, 'info');
            void render;
          },
        },
      },
      icon('clock', 16),
    ),
  );
}

function liveStat(label: string, value: string, sub: string, tone?: 'good' | 'bad'): HTMLElement {
  return h(
    'div',
    { class: 'floor-stat' },
    h('span', { class: 'floor-stat-label', text: label }),
    h('span', { class: `floor-stat-value${tone ? ` ${tone}` : ''}`, text: value }),
    h('span', { class: 'floor-stat-sub', text: sub }),
  );
}

// ------------------------------------------------------------ build mode

/**
 * The tray you build from, standing in the room you are building in.
 *
 * The designer is still there for laying out a floor from scratch; this is for
 * the thing the player actually wants most of the time — they are watching a
 * queue back up, and they want another till, now, in the gap by the door. So
 * the catalogue is the same one, the placement rules are the same ones, and the
 * money comes out of the same account. What is different is that they can see
 * the queue while they do it.
 */
function buildTray(
  business: Business,
  get: () => FloorCanvas | null,
  render: () => void,
): HTMLElement {
  const category = businessTypeOrThrow(business.typeId).category;
  // What is worth having here. An item that says which trades it suits is only
  // offered to those; everything else is general kit and always offered.
  const offered = ITEMS.filter((def) => !def.suits || def.suits.includes(category));
  const groups = [...new Set(offered.map((def) => def.group))];

  const tray = h('div', { class: 'floor-build' });
  tray.appendChild(
    h(
      'div',
      { class: 'floor-build-head' },
      h('strong', { text: holding ? item(holding.defId)?.name ?? 'Build' : 'Build' }),
      h('span', {
        class: 'sub',
        text: holding
          ? 'Click the floor to put it down. It starts working the moment it lands.'
          : 'Pick something, then click where it goes.',
      }),
      holding
        ? button('Turn it', () => {
            if (!holding) return;
            holding = { defId: holding.defId, rot: ((holding.rot + 90) % 360) as 0 | 90 | 180 | 270 };
            const canvas = get();
            if (canvas) canvas.placing = holding;
            render();
          })
        : null,
    ),
  );

  const list = h('div', { class: 'floor-build-items' });
  for (const group of groups) {
    list.appendChild(h('div', { class: 'floor-build-group', text: group }));
    for (const def of offered.filter((entry) => entry.group === group)) {
      const held = holding?.defId === def.id;
      const gives = Object.entries(def.gives)
        .filter(([, value]) => (value ?? 0) > 0)
        .map(([key, value]) => `${value} ${GIVE_NAMES[key] ?? key}`)
        .join(', ');
      list.appendChild(
        h(
          'button',
          {
            class: `floor-build-item${held ? ' active' : ''}`,
            title: `${def.detail}${gives ? `\n\nGives ${gives}.` : ''}`,
            on: {
              click: () => {
                holding = held ? null : { defId: def.id, rot: 0 };
                const canvas = get();
                if (canvas) canvas.placing = holding;
                render();
              },
            },
          },
          h('span', { class: 'floor-build-name', text: def.name }),
          h('span', { class: 'floor-build-cost', text: money(def.cost) }),
          gives ? h('span', { class: 'floor-build-gives', text: gives }) : null,
        ),
      );
    }
  }
  tray.appendChild(list);
  return tray;
}

// --------------------------------------------------------------- inspector

/**
 * What the player clicked on, and what it is doing.
 *
 * The other half of the world/management connection: the room shows you where
 * the problem is, and this says what it is in the same words the management
 * screens use, with the button that fixes it.
 */
function drawInspector(
  ctx: Ctx,
  business: Business,
  pick: Pick | null,
  canvas: FloorCanvas | null,
  render: () => void,
): void {
  const host = document.querySelector('.floor-inspect');
  if (!host) return;
  host.replaceChildren();

  if (!pick) {
    host.appendChild(
      h('p', { class: 'floor-hint', text: 'Click a person or a piece of equipment.' }),
    );
    return;
  }

  const world = canvas?.getWorld();
  const layout = layoutOf(ctx.state, business.buildingId);
  if (!world || !layout) return;

  if (pick.kind === 'agent') {
    const agent = world.agents.find((a) => a.id === pick.id);
    if (agent) host.appendChild(agentCard(ctx, agent, canvas, render));
    return;
  }

  if (pick.kind !== 'item') return;
  const report = reportOn(world, layout, pick.id);
  if (!report) return;
  const { placed, def, staff, queue } = report;
  const condition = conditionOf(placed);
  const status = statusOf(layout, placed);

  const card = h(
    'div',
    { class: 'panel floor-card' },
    h(
      'div',
      { class: 'row-between' },
      h('h3', { class: 'panel-title', text: def.name }),
      tag(
        status === 'operational' ? 'Working' : status === 'partial' ? 'Missing something' : status === 'worn' ? 'Worn out' : 'Nobody on it',
        status === 'operational' ? 'good' : status === 'worn' ? 'bad' : 'warn',
      ),
    ),
    h('p', { class: 'sub', text: def.detail }),
    stat('Condition', `${Math.round(condition)}%`, condition < 60 ? 'bad' : condition < 80 ? undefined : 'good'),
    stat('Upkeep', `${money(def.upkeep)}/month`),
  );

  // What it contributes, in the game's own vocabulary.
  const gives = Object.entries(def.gives).filter(([, value]) => (value ?? 0) > 0);
  if (gives.length > 0) {
    card.appendChild(
      stat('Gives', gives.map(([key, value]) => `${value} ${GIVE_NAMES[key] ?? key}`).join(', ')),
    );
  }

  if (staff) {
    card.appendChild(stat('Worked by', staff.name, 'good'));
    card.appendChild(
      stat('Doing', DOING[staff.state] ?? staff.state),
    );
  } else if ((def.gives.desk ?? 0) > 0 || (def.gives.checkout ?? 0) > 0) {
    card.appendChild(stat('Worked by', 'nobody right now', 'bad'));
  }
  if (queue > 0) card.appendChild(stat('Queue', `${queue} waiting`, queue > 3 ? 'bad' : undefined));

  const actions = h('div', { class: 'row' });
  if (condition < 92) {
    actions.appendChild(
      button(`Repair — ${money(repairCost(placed))}`, () => {
        const result = repair(ctx.state, layout, placed.id);
        toast(result.message, result.ok ? 'good' : 'bad');
        render();
      }, 'btn primary'),
    );
  }
  actions.appendChild(
    button(`Sell it — ${money(Math.round(def.cost * RESALE))}`, () => {
      const result = remove(ctx.state, layout, placed.id);
      toast(result.message, result.ok ? 'good' : 'bad');
      if (canvas) canvas.selected = null;
      render();
    }),
  );
  actions.appendChild(button('Move it', () => ctx.go('designer', { building: business.buildingId })));
  card.appendChild(actions);

  host.appendChild(card);
}

function agentCard(ctx: Ctx, agent: Agent, canvas: FloorCanvas | null, render: () => void): HTMLElement {
  if (agent.kind === 'customer') {
    return h(
      'div',
      { class: 'panel floor-card' },
      h(
        'div',
        { class: 'row-between' },
        h('h3', { class: 'panel-title', text: 'Customer' }),
        tag(
          agent.mood === 'happy' ? 'Happy' : agent.mood === 'cross' ? 'Fed up' : 'Fine',
          agent.mood === 'happy' ? 'good' : agent.mood === 'cross' ? 'bad' : 'muted',
        ),
      ),
      stat('Doing', DOING[agent.state] ?? agent.state),
      stat('Patience left', `${Math.max(0, Math.round(agent.patience))}s`, agent.patience < 25 ? 'bad' : undefined),
      h('p', {
        class: 'sub',
        text:
          agent.state === 'queueing'
            ? 'If the queue outlasts their patience they walk out, and that is one of the customers your figures call turned away.'
            : agent.state === 'browsing'
              ? 'Picking something off a shelf. What is on the shelves is what is in your stock.'
              : 'Moving through the shop.',
      }),
    );
  }

  const person = ctx.state.employees.find((e) => e.id === agent.employeeId);
  const card = h(
    'div',
    { class: 'panel floor-card' },
    h(
      'div',
      { class: 'row-between' },
      h('h3', { class: 'panel-title', text: agent.name }),
      tag(agent.state === 'stranded' ? 'Nowhere to work' : 'On shift', agent.state === 'stranded' ? 'bad' : 'good'),
    ),
  );
  if (person) {
    card.appendChild(stat('Job', titleOf(person)));
    card.appendChild(stat('Performance', `${Math.round(performanceOf(person))}/100`));
    card.appendChild(stat('Morale', `${Math.round(person.morale)}/100`, person.morale < 45 ? 'bad' : undefined));
  }
  card.appendChild(stat('Doing', DOING[agent.state] ?? agent.state));
  if (agent.state === 'stranded') {
    card.appendChild(
      h('p', {
        class: 'sub',
        text: 'They are on the payroll and no workstation is assigned to them, so they are contributing nothing.',
      }),
    );
    const layout = layoutOf(ctx.state, ctx.state.businesses.find((b) => b.id === person?.businessId)?.buildingId ?? '');
    if (layout) {
      card.appendChild(
        h(
          'div',
          { class: 'row' },
          button('Put everybody at a station', () => {
            const result = autoAssign(ctx.state, layout);
            toast(
              result.left > 0
                ? `${result.seated} seated. ${result.left} still have nowhere — there are not enough workstations.`
                : `${result.seated} seated. Everybody has somewhere to work.`,
              result.left > 0 ? 'info' : 'good',
            );
            render();
          }, 'btn primary'),
        ),
      );
    }
  }
  card.appendChild(
    h(
      'div',
      { class: 'row' },
      button('Their file', () => ctx.go('employees'), 'btn primary'),
      button('The rota', () => ctx.go('workforce', { business: ctx.params.business ?? '' })),
      button('Follow', () => {
        canvas?.focusAgent(agent.id);
        void render;
      }),
    ),
  );
  return card;
}

/** The contributions, in the words the rest of the game uses for them. */
const GIVE_NAMES: Record<string, string> = {
  desk: 'workstation', equips: 'kit', meeting: 'meeting seat', training: 'training place',
  rest: 'break space', storage: 'units of stock', sanitary: 'facility', reception: 'reception',
  management: 'management', production: 'output', comfort: 'comfort', checkout: 'customers/hour',
  cooking: 'covers/hour', seats: 'seats', cold: 'chilled units', server: 'users', calls: 'jobs at once',
  bay: 'vehicles at once',
};

/** What each state means, said plainly. */
const DOING: Record<string, string> = {
  arriving: 'just come in',
  walking: 'crossing the floor',
  working: 'at their station',
  serving: 'serving a customer',
  browsing: 'looking at the shelves',
  queueing: 'waiting to pay',
  paying: 'paying',
  seated: 'waiting for their food',
  eating: 'eating',
  waiting: 'waiting for a table',
  carrying: 'fetching stock',
  resting: 'on a break',
  meeting: 'in a meeting',
  stranded: 'standing about — nowhere to work',
  leaving: 'on their way out',
};
