import type { GameState } from './state';
import type { Business, Employee } from './types';
import type { ItemDef } from '../data/buildingItems';
import { item } from '../data/buildingItems';
import type { Layout, PlacedItem } from './layout';
import { conditionFactor, dependenciesMet, layoutOf, tilesOf } from './layout';
import { hourlyCapacity } from './business';
import { onDuty } from './rota';
import { tradeOf, type Trade } from './needs';
import { demandAt } from './demand';
import { clamp } from './util';

/**
 * The floor: what is actually happening inside a business, minute by minute.
 *
 * Until now a shop was a row of figures. It had eleven customers an hour and
 * four people on and two tills, and every one of those was true, and none of
 * them could be seen. This is the same shop with its roof off: the customers
 * walk in, go to the shelves, queue at a till, pay and leave, and the staff
 * stand where the player put them and serve.
 *
 * Two rules hold the whole thing together, and both matter more than any of
 * the animation.
 *
 * **It reads the simulation; it never writes to it.** Nothing in this file
 * touches money, stock, morale or the day's figures. The arrival rate is the
 * demand the business genuinely sees this hour, the service rate is the
 * throughput `hourlyCapacity` genuinely allows, and the people on the floor are
 * the people the rota genuinely has on. So what the player watches is the
 * arithmetic they were already being charged for, drawn out — and when the
 * queue builds up and somebody walks out, that customer was already being lost
 * in the ledger before anybody could see it happen.
 *
 * **It is not saved.** Where every person is standing at 14:37 is not part of
 * the company; the building, the objects in it, their condition and who is
 * assigned to them all are, and all of those were already saved. Closing the
 * view and opening it again gives you the same shop with the same staff at the
 * same stations, mid-afternoon, busy.
 */

// --------------------------------------------------------------- the people

export type AgentKind = 'staff' | 'customer';

/**
 * What somebody is doing, in the words the player would use.
 *
 * Every one of these corresponds to something real: `queueing` means the tills
 * cannot keep up, `stranded` means somebody was hired and has nowhere to work,
 * `waiting` at a restaurant means every table is full. None of them is an
 * animation playing to fill time.
 */
export type AgentState =
  | 'arriving'
  | 'walking'
  | 'working'
  | 'serving'
  | 'browsing'
  | 'queueing'
  | 'paying'
  | 'seated'
  | 'eating'
  | 'waiting'
  | 'carrying'
  | 'resting'
  | 'meeting'
  | 'stranded'
  | 'leaving';

export interface Agent {
  id: string;
  kind: AgentKind;
  /** Set on staff: the person on the payroll this is. */
  employeeId?: string;
  name: string;
  /** Tile coordinates, fractional — this is where they are standing. */
  x: number;
  y: number;
  /** Which way they are facing, in radians, for the artwork. */
  facing: number;
  /** Where they are heading, tile by tile. */
  path: { x: number; y: number }[];
  state: AgentState;
  /** The object they are using or heading for. */
  targetId: string | null;
  /** Seconds left of whatever they are in the middle of. */
  timer: number;
  /** How long they will put up with a queue before walking out. */
  patience: number;
  /** A stable number per person, so their appearance never flickers. */
  look: number;
  /** Customers only: how it has gone for them so far. */
  mood: 'happy' | 'fine' | 'cross';
  /** Customers only: whether they have anything to pay for yet. */
  carrying: boolean;
}

// ---------------------------------------------------------------- the world

export interface FloorTally {
  /** Customers who came in and were served, this visit to the screen. */
  served: number;
  /** Customers who gave up in the queue or could not get a table. */
  lost: number;
  /** The longest queue seen at any till. */
  worstQueue: number;
  /** Seconds of simulated floor time. */
  elapsed: number;
}

/**
 * A lorry at the back door.
 *
 * Not scenery on a timer: a vehicle is here because this business has an order
 * that arrives in the next few hours, which is the same order the procurement
 * screen is showing as in transit and the same one that will put stock on the
 * shelves when it lands. No order, no lorry — and a depot with nothing coming
 * in has an empty bay, which is the point.
 */
export interface Delivery {
  id: string;
  /** Where it has pulled up, in tile coordinates. */
  x: number;
  y: number;
  /** Which way it is pointing. */
  facing: number;
  /** Seconds left of unloading. */
  timer: number;
  /** How much of the load is still on it, 0..1. */
  left: number;
  orderId: string;
}

export interface FloorWorld {
  buildingId: string;
  businessId: string;
  floor: number;
  w: number;
  h: number;
  trade: Trade;
  agents: Agent[];
  /** The door everybody comes in by, in tile coordinates. */
  door: { x: number; y: number };
  tally: FloorTally;
  /** Carried between frames so arrivals are smooth rather than lumpy. */
  pending: number;
  /** Rebuilt whenever the layout changes underneath us. */
  blocked: boolean[];
  stamp: string;
  /** Lorries at the bay, one per order arriving soon. */
  deliveries: Delivery[];
}

/** Objects a customer walks up to in order to be served. */
const SERVICE_GIVES = ['checkout', 'reception', 'calls', 'bay'] as const;

/**
 * How long things take, in floor seconds.
 *
 * These are the numbers that decide whether the room looks like the business
 * the figures describe, and they are not arbitrary. How many people are in a
 * shop at once is the rate they arrive multiplied by how long each one stays —
 * so a shop taking thirty customers an hour, each in the place for about eight
 * minutes, has four people in it. Get the dwell time wrong and a busy shop
 * looks deserted however correct the arrival rate is.
 *
 * The view then runs this clock faster than life, so eight minutes of shopping
 * is a quarter of a minute of watching. Compressing time does not change the
 * occupancy, because both halves of that multiplication are compressed with it.
 */
const TILE_SECONDS = 9;
const BROWSE = [90, 210] as const;
const PAY = [20, 40] as const;
const QUEUE_TICK = 8;
const PATIENCE = [240, 600] as const;
const EAT = [900, 1500] as const;
const ORDER = 180;
const MAX_CUSTOMERS = 46;

// ------------------------------------------------------------------- making

export function createFloor(state: GameState, business: Business, floor = 0): FloorWorld | null {
  const layout = layoutOf(state, business.buildingId);
  if (!layout) return null;

  const world: FloorWorld = {
    buildingId: business.buildingId,
    businessId: business.id,
    floor,
    w: layout.w,
    h: layout.h,
    trade: tradeOf(business),
    agents: [],
    door: doorOf(layout, floor),
    tally: { served: 0, lost: 0, worstQueue: 0, elapsed: 0 },
    pending: 0,
    blocked: [],
    stamp: '',
    deliveries: [],
  };
  rebuild(world, layout);
  syncStaff(state, business, world, layout);
  return world;
}

/**
 * A fingerprint of everything the floor's navigation depends on.
 *
 * Cheaper than diffing the layout, and it means placing an object rebuilds the
 * walkable grid on the very next frame rather than when somebody remembers to
 * call something.
 */
function stampOf(layout: Layout, floor: number): string {
  let out = `${layout.w}x${layout.h}:`;
  for (const placed of layout.items) {
    if (placed.floor !== floor) continue;
    out += `${placed.id}@${placed.x},${placed.y},${placed.rot};`;
  }
  return out;
}

function rebuild(world: FloorWorld, layout: Layout): void {
  const blocked = new Array<boolean>(layout.w * layout.h).fill(false);
  for (const placed of layout.items) {
    if (placed.floor !== world.floor) continue;
    const def = item(placed.defId);
    // A rug is walked over; a fridge is walked round. The distinction is
    // already in the item table because the designer needed it.
    if (!def || def.flat) continue;
    for (const tile of tilesOf(placed)) {
      if (tile.x < 0 || tile.y < 0 || tile.x >= layout.w || tile.y >= layout.h) continue;
      blocked[tile.y * layout.w + tile.x] = true;
    }
  }
  world.blocked = blocked;
  world.stamp = stampOf(layout, world.floor);
}

/** Where the front door is: a door on an outside edge, or the middle of the front. */
function doorOf(layout: Layout, floor: number): { x: number; y: number } {
  const doors = layout.walls.filter((wall) => wall.floor === floor && wall.kind === 'door');
  const front = doors.find((wall) => wall.dir === 'h' && wall.y >= layout.h) ?? doors[0];
  if (front) {
    return {
      x: clamp(front.dir === 'h' ? front.x : front.x - 0.5, 0, layout.w - 1),
      y: clamp(front.dir === 'h' ? front.y - 0.5 : front.y, 0, layout.h - 1),
    };
  }
  return { x: Math.floor(layout.w / 2), y: layout.h - 1 };
}

// ----------------------------------------------------------------- stepping

/**
 * One step of the floor, in seconds of floor time.
 *
 * Called from the view's animation frame rather than from the engine's clock,
 * because this is a window onto the simulation rather than part of it. If the
 * player is not looking at the floor, none of this runs at all.
 */
export function stepFloor(state: GameState, world: FloorWorld, seconds: number): void {
  const business = state.businesses.find((b) => b.id === world.businessId);
  const layout = layoutOf(state, world.buildingId);
  if (!business || !layout) return;

  if (stampOf(layout, world.floor) !== world.stamp) rebuild(world, layout);

  world.tally.elapsed += seconds;
  syncStaff(state, business, world, layout);
  syncDeliveries(state, business, world, layout, seconds);
  arrivals(state, business, world, layout, seconds);

  for (const agent of world.agents) {
    advance(world, agent, seconds);
    if (agent.path.length === 0 && agent.timer <= 0) decide(state, business, world, layout, agent);
    else if (agent.timer > 0 && agent.path.length === 0) agent.timer -= seconds;
  }

  // Anybody who has walked out is gone.
  world.agents = world.agents.filter((agent) => !(agent.state === 'leaving' && offStage(world, agent)));

  const queue = world.agents.filter((agent) => agent.state === 'queueing').length;
  world.tally.worstQueue = Math.max(world.tally.worstQueue, queue);
}

function offStage(world: FloorWorld, agent: Agent): boolean {
  return agent.path.length === 0 && Math.hypot(agent.x - world.door.x, agent.y - world.door.y) < 1.2;
}

/** Moving along the path they were given. */
function advance(world: FloorWorld, agent: Agent, seconds: number): void {
  if (agent.path.length === 0) return;
  let budget = seconds / TILE_SECONDS;
  while (budget > 0 && agent.path.length > 0) {
    const next = agent.path[0];
    const dx = next.x - agent.x;
    const dy = next.y - agent.y;
    const distance = Math.hypot(dx, dy);
    if (distance < 0.001) {
      agent.path.shift();
      continue;
    }
    agent.facing = Math.atan2(dy, dx);
    const step = Math.min(distance, budget);
    agent.x += (dx / distance) * step;
    agent.y += (dy / distance) * step;
    budget -= step;
    if (step >= distance - 0.001) agent.path.shift();
  }
  if (agent.path.length === 0 && agent.state === 'walking') agent.state = 'arriving';
  void world;
}

// ----------------------------------------------------------- the back door

/** How many hours ahead of an order landing the lorry is on the forecourt. */
const LORRY_WINDOW = 3;

/**
 * The lorries, kept in step with what is actually on its way here.
 *
 * An order that is due within a few hours has a vehicle at the bay; one that
 * has landed no longer does. The unloading takes as long as the load is big,
 * and while it is happening there is something for the warehouse staff to walk
 * to — which is the whole reason a depot has people in it.
 */
function syncDeliveries(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  seconds: number,
): void {
  const now = state.day * 24 + state.hour;
  const due = (state.orders ?? []).filter(
    (order) =>
      order.businessId === business.id &&
      order.status !== 'delivered' &&
      order.arrivesOnTick - now <= LORRY_WINDOW &&
      order.arrivesOnTick - now > -LORRY_WINDOW,
  );

  // Anything that has landed, or been cancelled, drives away.
  world.deliveries = world.deliveries.filter((lorry) => due.some((order) => order.id === lorry.orderId));

  for (const order of due) {
    if (world.deliveries.some((lorry) => lorry.orderId === order.id)) continue;
    if (world.deliveries.length >= 3) break;
    const bay = pickItem(layout, world.floor, (placed) => {
      const def = item(placed.defId);
      return Boolean(def && (def.gives.bay ?? 0) > 0);
    }, world.deliveries.length);
    // At the loading bay if the building has one, and at the front if it does
    // not — which is exactly how a shop with no bay actually takes a delivery.
    const spot = bay
      ? { x: tilesOf(bay)[0].x + 0.5, y: Math.max(0, tilesOf(bay)[0].y - 1.2) }
      : { x: world.door.x + 1.6 + world.deliveries.length * 1.4, y: world.h - 0.4 };
    const units = order.lines.reduce((total, line) => total + line.quantity, 0);
    world.deliveries.push({
      id: `van_${order.id}`,
      x: spot.x,
      y: spot.y,
      facing: bay ? Math.PI / 2 : 0,
      // A minute of unloading per fifty units, floor time.
      timer: clamp(units / 50, 1, 20) * 60,
      left: 1,
      orderId: order.id,
    });
  }

  for (const lorry of world.deliveries) {
    // It only empties while somebody is actually fetching from it.
    const hands = world.agents.filter((a) => a.kind === 'staff' && a.state === 'carrying').length;
    if (hands > 0 && lorry.timer > 0) {
      lorry.timer -= seconds * Math.min(3, hands);
      lorry.left = clamp(lorry.timer / Math.max(1, lorry.timer + seconds), 0, 1);
    }
    lorry.left = Math.max(0, Math.min(1, lorry.timer / 600));
  }
}

// --------------------------------------------------------------- the staff

/**
 * The people on the floor are the people on the rota.
 *
 * Not a copy of the team kept in step by hand: read fresh every step from
 * `onDuty`, so somebody whose shift ends walks out, and somebody the player
 * reassigns in the management screen is already walking across the shop by the
 * time they look back at it.
 */
function syncStaff(state: GameState, business: Business, world: FloorWorld, layout: Layout): void {
  const working = onDuty(state, business);
  const here = new Map(world.agents.filter((a) => a.kind === 'staff').map((a) => [a.employeeId, a]));

  for (const person of working) {
    const existing = here.get(person.id);
    const station = stationFor(layout, world.floor, person);
    if (existing) {
      // Reassigned while the player watched: they get up and walk over.
      if (station && existing.targetId !== station.id) {
        existing.targetId = station.id;
        existing.path = routeTo(world, existing, standingBy(station, 'staff'));
        existing.state = 'walking';
        existing.timer = 0;
      }
      here.delete(person.id);
      continue;
    }
    world.agents.push(newStaff(world, person, station));
  }

  // Whoever is left in the map is off shift, and goes home.
  for (const stale of here.values()) {
    if (!stale) continue;
    stale.state = 'leaving';
    stale.targetId = null;
    if (stale.path.length === 0) stale.path = routeTo(world, stale, world.door);
  }
}

function newStaff(world: FloorWorld, person: Employee, station: PlacedItem | null): Agent {
  const agent: Agent = {
    id: `staff_${person.id}`,
    kind: 'staff',
    employeeId: person.id,
    name: person.name,
    x: world.door.x,
    y: world.door.y,
    facing: -Math.PI / 2,
    path: [],
    state: station ? 'walking' : 'stranded',
    targetId: station?.id ?? null,
    timer: 0,
    patience: Infinity,
    look: seedOf(person.id),
    mood: 'fine',
    carrying: false,
  };
  if (station) agent.path = routeTo(world, agent, standingBy(station, 'staff'));
  return agent;
}

/** The object this person has been assigned to, if it is on this floor. */
function stationFor(layout: Layout, floor: number, person: Employee): PlacedItem | null {
  if (!person.workplaceId) return null;
  const placed = layout.items.find((it) => it.id === person.workplaceId);
  if (!placed || placed.floor !== floor) return null;
  return placed;
}

/**
 * The tile somebody stands on to use a thing — beside it, not inside it.
 *
 * Which side matters for anything with a counter. Staff belong behind it and
 * customers in front of it, and a cashier drawn on the customer's side of their
 * own till is the sort of detail that makes a room stop being believable.
 * "Behind" is the side away from the door, because that is where the door is.
 */
function standingBy(placed: PlacedItem, side: 'staff' | 'customer' = 'customer'): { x: number; y: number } {
  const tiles = tilesOf(placed);
  const first = tiles[0] ?? { x: 0, y: 0 };
  const def = item(placed.defId);
  const counter = def ? SERVICE_GIVES.some((key) => (def.gives[key] ?? 0) > 0) : false;
  if (counter && side === 'staff') {
    const last = tiles[tiles.length - 1] ?? first;
    return { x: first.x, y: Math.max(0, Math.min(first.y, last.y) - 1) };
  }
  const bottom = Math.max(...tiles.map((t) => t.y), first.y);
  return { x: first.x, y: bottom + 1 };
}

// ------------------------------------------------------------- the customers

/**
 * How many people walk in, and how quickly they can be dealt with.
 *
 * Both come from the engine. `demandAt` is the same curve the rota is built
 * against and the same one the trading hour uses; `hourlyCapacity` is the
 * throughput the business actually has, tills, staff, room and all. Serving is
 * therefore neither generous nor mean here — it is the figure the player is
 * already being paid on.
 */
export function floorRates(state: GameState, business: Business): { arrivals: number; capacity: number } {
  const day = ((Math.max(0, Math.floor(state.day) - 1) % 7) + 7) % 7;
  return {
    arrivals: demandAt(business, day as 0, state.hour),
    capacity: Math.max(0, hourlyCapacity(state, business)),
  };
}

function arrivals(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  seconds: number,
): void {
  if (business.status !== 'open') return;
  const closes = business.openTo > business.openFrom ? business.openTo : 24;
  const open = state.hour >= business.openFrom && state.hour < closes;
  if (!open) return;
  // An office or a software firm has no public coming through the door, and
  // pretending otherwise would be exactly the decoration this is meant to
  // replace.
  if (world.trade === 'office' || world.trade === 'software') return;

  const { arrivals: perHour } = floorRates(state, business);
  // One minute of floor time is one minute of the hour. The view runs the
  // floor faster than life, and the rate comes with it.
  world.pending += (perHour / 3600) * seconds;
  const customers = world.agents.filter((a) => a.kind === 'customer').length;

  while (world.pending >= 1) {
    world.pending -= 1;
    if (customers + 1 > MAX_CUSTOMERS) continue;
    world.agents.push(newCustomer(world, layout));
  }
}

let customerCounter = 0;

function newCustomer(world: FloorWorld, layout: Layout): Agent {
  customerCounter += 1;
  const id = `cus_${customerCounter}`;
  const look = seedOf(id);
  const agent: Agent = {
    id,
    kind: 'customer',
    name: 'Customer',
    x: world.door.x,
    y: world.door.y + 0.6,
    facing: -Math.PI / 2,
    path: [],
    state: 'arriving',
    targetId: null,
    timer: 0,
    // Between four and ten minutes of queueing. Somebody who runs out of it
    // walks out, and that is a lost customer in the ledger too.
    patience: PATIENCE[0] + (look % (PATIENCE[1] - PATIENCE[0])),
    look,
    mood: 'fine',
    carrying: false,
  };
  void layout;
  return agent;
}

// ------------------------------------------------------------ what to do next

/**
 * The one decision function, per trade.
 *
 * Each of these is the operational loop of that kind of business, and each step
 * of it is something the player can see going wrong: no shelves to browse, no
 * till to pay at, nobody on the till, every table taken.
 */
function decide(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
): void {
  if (agent.kind === 'staff') return decideStaff(state, world, layout, agent);
  switch (world.trade) {
    case 'kitchen':
      return decideDiner(state, business, world, layout, agent);
    case 'workshop':
    case 'depot':
      return decideClient(state, business, world, layout, agent);
    default:
      return decideShopper(state, business, world, layout, agent);
  }
}

/**
 * What somebody at work does next.
 *
 * Serving, if they are on a counter and there is somebody at it. Otherwise
 * working at their station, with errands across the floor — fetching stock, a
 * meeting, ten minutes in the break room — and every one of those errands
 * happens only if the player built somewhere for it to happen. A company with
 * no meeting table never holds a meeting; one with nowhere to sit down never
 * gives anybody a break. That is the same rule the comfort and morale figures
 * already worked on, made visible.
 */
function decideStaff(state: GameState, world: FloorWorld, layout: Layout, agent: Agent): void {
  const station = agent.targetId ? layout.items.find((it) => it.id === agent.targetId) : null;
  if (!station) {
    // Hired, and nowhere to work. They stand about, and it is meant to look
    // exactly as wasteful as it is.
    agent.state = 'stranded';
    agent.timer = 30;
    return;
  }
  const def = item(station.defId);
  const serves = def ? SERVICE_GIVES.some((key) => (def.gives[key] ?? 0) > 0) : false;

  if (serves) {
    // On a till or a counter: serving whoever is in front of *this* one. A
    // cashier who looks busy because there is a queue at the other end of the
    // shop is telling the player something untrue.
    const mine = world.agents.filter(
      (a) => a.kind === 'customer' && a.targetId === station.id && (a.state === 'queueing' || a.state === 'paying'),
    );
    agent.state = mine.length > 0 ? 'serving' : 'working';
    agent.timer = 20;
    return;
  }

  // Finished an errand, or just arrived: back to their own station.
  if (agent.state === 'carrying' || agent.state === 'meeting' || agent.state === 'resting' || agent.state === 'arriving') {
    agent.path = routeTo(world, agent, standingBy(station, 'staff'));
    agent.state = 'walking';
    return;
  }
  if (agent.state === 'walking') {
    agent.state = 'working';
    agent.timer = 45;
    return;
  }

  // At their station. Every so often there is somewhere else to be, and which
  // errand comes up is settled by the clock and the person rather than by a
  // die, so the room does not twitch.
  const slot = Math.floor(world.tally.elapsed / 90) + agent.look;
  // A lorry on the forecourt beats anything else: it is blocking a bay and the
  // stock on it is not on the shelves until somebody moves it.
  const lorry = world.deliveries.find((van) => van.left > 0.02);
  if (lorry && agent.state === 'working' && !serves) {
    agent.path = routeTo(world, agent, { x: lorry.x, y: Math.min(world.h - 1, lorry.y + 1) });
    agent.state = 'carrying';
    agent.timer = 90;
    return;
  }
  if (agent.state === 'working' && slot % 5 === 0) {
    const errand = errandFor(world, layout, agent, slot);
    if (errand) {
      agent.path = routeTo(world, agent, standingBy(errand.where));
      agent.state = errand.doing;
      agent.timer = errand.seconds;
      return;
    }
  }

  agent.state = 'working';
  agent.timer = 45;
  void state;
}

/** Somewhere else to be, if the building has one. */
function errandFor(
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
  slot: number,
): { where: PlacedItem; doing: AgentState; seconds: number } | null {
  const find = (wanted: (def: ItemDef) => boolean): PlacedItem | null =>
    pickItem(layout, world.floor, (placed) => {
      const def = item(placed.defId);
      return Boolean(def && wanted(def));
    }, agent.look);

  // A meeting, if there is a table to hold one round — and only for the kinds
  // of business where people meet rather than serve.
  if (slot % 15 === 0 && (world.trade === 'office' || world.trade === 'software')) {
    const table = find((def) => (def.gives.meeting ?? 0) > 0);
    if (table) return { where: table, doing: 'meeting', seconds: 900 };
  }
  // A break, if there is anywhere to take one.
  if (slot % 10 === 0) {
    const rest = find((def) => (def.gives.rest ?? 0) > 0 || (def.gives.comfort ?? 0) > 1);
    if (rest) return { where: rest, doing: 'resting', seconds: 600 };
  }
  // Paperwork, in the places that have any.
  if (slot % 7 === 0 && (world.trade === 'office' || world.trade === 'software')) {
    const kit = find((def) => def.id === 'printer' || def.id === 'filing-cabinet' || def.id === 'whiteboard');
    if (kit) return { where: kit, doing: 'carrying', seconds: 150 };
  }
  // A factory runs on somebody moving material to the machine and the finished
  // goods away from it. Which of the two this trip is depends on the clock, so
  // the floor has traffic in both directions rather than a conga line.
  if (world.trade === 'workshop' || world.trade === 'depot') {
    const toward = slot % 2 === 0;
    const target = toward
      ? find((def) => (def.gives.production ?? 0) > 0 || (def.gives.bay ?? 0) > 0)
      : find((def) => (def.gives.storage ?? 0) > 0);
    if (target) return { where: target, doing: 'carrying', seconds: 150 };
  }
  // And fetching stock, which is what most of a shop floor is.
  const store = find((def) => (def.gives.storage ?? 0) > 0 || (def.gives.cold ?? 0) > 0);
  if (store) return { where: store, doing: 'carrying', seconds: 120 };
  return null;
}

/** A shop: in, round the shelves, queue, pay, out. */
function decideShopper(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
): void {
  switch (agent.state) {
    case 'arriving': {
      const shelf = pickItem(layout, world.floor, (candidate) => {
        const def = item(candidate.defId);
        return Boolean(def && ((def.gives.storage ?? 0) > 0 || (def.gives.cold ?? 0) > 0));
      }, agent.look);
      if (!shelf) {
        // Nothing on display. They look around and leave, which is precisely
        // what an empty shop earns.
        agent.mood = 'cross';
        return giveUp(world, agent);
      }
      agent.targetId = shelf.id;
      agent.path = routeTo(world, agent, standingBy(shelf));
      agent.state = 'walking';
      return;
    }
    case 'walking':
      agent.state = 'browsing';
      agent.timer = BROWSE[0] + (agent.look % (BROWSE[1] - BROWSE[0]));
      return;
    case 'browsing': {
      agent.carrying = true;
      const till = pickService(layout, world.floor, 'checkout', agent.look);
      if (!till) {
        // Goods in hand and nowhere to pay. Nobody waits for that.
        agent.mood = 'cross';
        return giveUp(world, agent);
      }
      agent.targetId = till.id;
      agent.path = routeTo(world, agent, queueSpot(world, till));
      agent.state = 'queueing';
      agent.timer = 0;
      return;
    }
    case 'queueing':
      return serveQueue(state, business, world, layout, agent);
    case 'paying':
      world.tally.served += 1;
      agent.carrying = false;
      agent.mood = agent.mood === 'cross' ? 'fine' : 'happy';
      return giveUp(world, agent, 'leaving');
    default:
      return giveUp(world, agent);
  }
}

/** A restaurant: wait, sit, order, eat, pay, leave. */
function decideDiner(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
): void {
  switch (agent.state) {
    case 'arriving': {
      const table = freeSeat(world, layout, agent.look);
      if (!table) {
        // Every table taken. They wait as long as their patience lasts.
        agent.state = 'waiting';
        agent.timer = QUEUE_TICK;
        agent.patience -= QUEUE_TICK;
        if (agent.patience <= 0) {
          world.tally.lost += 1;
          agent.mood = 'cross';
          return giveUp(world, agent);
        }
        return;
      }
      agent.targetId = table.id;
      agent.path = routeTo(world, agent, standingBy(table));
      agent.state = 'walking';
      return;
    }
    case 'waiting':
      agent.state = 'arriving';
      return;
    case 'walking':
      agent.state = 'seated';
      // Ordering, then waiting for the kitchen. How long that takes is the
      // kitchen's real capacity against the room's real demand.
      agent.timer = ORDER + waitForFood(state, business);
      return;
    case 'seated':
      agent.state = 'eating';
      agent.timer = EAT[0] + (agent.look % (EAT[1] - EAT[0]));
      return;
    case 'eating': {
      const till = pickService(layout, world.floor, 'checkout', agent.look);
      if (!till) {
        world.tally.served += 1;
        return giveUp(world, agent, 'leaving');
      }
      agent.targetId = till.id;
      agent.path = routeTo(world, agent, queueSpot(world, till));
      agent.state = 'queueing';
      return;
    }
    case 'queueing':
      return serveQueue(state, business, world, layout, agent);
    case 'paying':
      world.tally.served += 1;
      agent.mood = 'happy';
      return giveUp(world, agent, 'leaving');
    default:
      return giveUp(world, agent);
  }
}

/** A garage or a depot: arrive, be received, wait while the work is done. */
function decideClient(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
): void {
  switch (agent.state) {
    case 'arriving': {
      const desk =
        pickService(layout, world.floor, 'reception', agent.look) ??
        pickService(layout, world.floor, 'calls', agent.look) ??
        pickService(layout, world.floor, 'bay', agent.look);
      if (!desk) {
        agent.mood = 'cross';
        return giveUp(world, agent);
      }
      agent.targetId = desk.id;
      agent.path = routeTo(world, agent, queueSpot(world, desk));
      agent.state = 'queueing';
      return;
    }
    case 'queueing':
      return serveQueue(state, business, world, layout, agent);
    case 'paying':
      world.tally.served += 1;
      agent.mood = 'happy';
      return giveUp(world, agent, 'leaving');
    default:
      return giveUp(world, agent);
  }
}

/**
 * The queue, and why it moves at the speed it does.
 *
 * The till serves at the rate the business can actually serve — capacity for
 * the hour, shared between however many service points there are — and if
 * nobody is standing at the counter it does not serve at all. Waiting eats
 * patience, and running out of patience is a customer walking out with their
 * basket, which is the thing the figures have always called "turned away".
 */
function serveQueue(
  state: GameState,
  business: Business,
  world: FloorWorld,
  layout: Layout,
  agent: Agent,
): void {
  const till = agent.targetId ? layout.items.find((it) => it.id === agent.targetId) : null;
  const manned = till
    ? world.agents.some(
        (other) =>
          other.kind === 'staff' &&
          other.targetId === till.id &&
          (other.state === 'serving' || other.state === 'working'),
      )
    : false;

  const ahead = world.agents.filter(
    (other) =>
      other.kind === 'customer' &&
      other !== agent &&
      other.targetId === agent.targetId &&
      (other.state === 'queueing' || other.state === 'paying'),
  ).length;

  const { capacity } = floorRates(state, business);
  const points = Math.max(1, countService(layout, world.floor));
  // Seconds to put one person through, at this business's own throughput.
  const perCustomer = capacity > 0 ? (3600 / capacity) * points : Infinity;
  const wait = manned ? perCustomer * Math.max(1, ahead + 1) : Infinity;

  agent.timer = QUEUE_TICK;
  agent.patience -= QUEUE_TICK;
  if (agent.patience <= 0 || !Number.isFinite(wait)) {
    // Out of patience, or nobody is ever coming. Either way they go, and the
    // sale goes with them.
    world.tally.lost += 1;
    agent.mood = 'cross';
    return giveUp(world, agent);
  }
  if (ahead === 0 && manned) {
    agent.state = 'paying';
    agent.timer = Math.max(PAY[0], Math.min(PAY[1], perCustomer));
    if (agent.patience < PATIENCE[0] * 0.3) agent.mood = 'cross';
  }
}

/** How long the kitchen takes, from what the kitchen can actually do. */
function waitForFood(state: GameState, business: Business): number {
  const { arrivals: perHour, capacity } = floorRates(state, business);
  if (capacity <= 0) return 1800;
  // A kitchen running at its limit takes longer, and one with room to spare
  // does not. Same numbers the covers-per-hour ceiling is built from.
  const pressure = clamp(perHour / Math.max(1, capacity), 0.3, 3);
  return 420 * pressure;
}

function giveUp(world: FloorWorld, agent: Agent, state: AgentState = 'leaving'): void {
  agent.state = state;
  agent.targetId = null;
  agent.timer = 0;
  agent.path = routeTo(world, agent, world.door);
}

// ------------------------------------------------------------ finding things

function pickItem(
  layout: Layout,
  floor: number,
  wanted: (placed: PlacedItem) => boolean,
  seed = 0,
): PlacedItem | null {
  const options = layout.items.filter((placed) => placed.floor === floor && wanted(placed));
  if (options.length === 0) return null;
  return options[seed % options.length];
}

/** A service point of a given kind that is actually working. */
function pickService(
  layout: Layout,
  floor: number,
  gives: (typeof SERVICE_GIVES)[number],
  seed = 0,
): PlacedItem | null {
  return pickItem(
    layout,
    floor,
    (placed) => {
      const def = item(placed.defId);
      if (!def || (def.gives[gives] ?? 0) <= 0) return false;
      // A broken till is not a till, and neither is one whose dependencies are
      // missing — the same rule the capacity maths already uses.
      return dependenciesMet(layout, placed) && conditionFactor(placed) > 0.35;
    },
    seed,
  );
}

function countService(layout: Layout, floor: number): number {
  return layout.items.filter((placed) => {
    if (placed.floor !== floor) return false;
    const def = item(placed.defId);
    return Boolean(def && SERVICE_GIVES.some((key) => (def.gives[key] ?? 0) > 0));
  }).length;
}

/** A table nobody is sitting at. */
function freeSeat(world: FloorWorld, layout: Layout, seed: number): PlacedItem | null {
  const taken = new Set(
    world.agents
      .filter((a) => a.kind === 'customer' && (a.state === 'seated' || a.state === 'eating' || a.state === 'walking'))
      .map((a) => a.targetId),
  );
  const tables = layout.items.filter((placed) => {
    if (placed.floor !== world.floor) return false;
    const def = item(placed.defId);
    return Boolean(def && (def.gives.seats ?? 0) > 0) && !taken.has(placed.id);
  });
  if (tables.length === 0) return null;
  return tables[seed % tables.length];
}

/** Where to stand in the queue: behind whoever is already there. */
function queueSpot(world: FloorWorld, till: PlacedItem): { x: number; y: number } {
  const ahead = world.agents.filter(
    (other) => other.targetId === till.id && (other.state === 'queueing' || other.state === 'paying'),
  ).length;
  const base = standingBy(till);
  return { x: base.x, y: Math.min(world.h - 1, base.y + 1 + ahead * 0.8) };
}

// ------------------------------------------------------------- getting there

/**
 * A route that goes round the furniture rather than through it.
 *
 * Breadth-first over the tiles, which on a floor plate of a few hundred tiles
 * is both quick and always finds the shortest way if there is one. Corners are
 * then pulled out of the result, so people walk in lines rather than tracing
 * every tile like a maze solver.
 */
export function routeTo(
  world: FloorWorld,
  agent: Agent,
  goal: { x: number; y: number },
): { x: number; y: number }[] {
  const start = { x: Math.round(agent.x), y: Math.round(agent.y) };
  const target = nearestOpen(world, goal);
  if (!target) return [];
  if (start.x === target.x && start.y === target.y) return [];

  const width = world.w;
  const height = world.h;
  const from = new Int32Array(width * height).fill(-1);
  const seen = new Uint8Array(width * height);
  const queue: number[] = [];
  const startIndex = clampIndex(world, start.x, start.y);
  queue.push(startIndex);
  seen[startIndex] = 1;

  let found = -1;
  const goalIndex = target.y * width + target.x;
  for (let head = 0; head < queue.length; head += 1) {
    const current = queue[head];
    if (current === goalIndex) {
      found = current;
      break;
    }
    const cx = current % width;
    const cy = Math.floor(current / width);
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) {
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
      const next = ny * width + nx;
      if (seen[next]) continue;
      // The tile you are standing on may be blocked — somebody can always step
      // off a spot they are already on.
      if (world.blocked[next] && next !== goalIndex) continue;
      seen[next] = 1;
      from[next] = current;
      queue.push(next);
    }
  }
  if (found < 0) return [];

  const back: { x: number; y: number }[] = [];
  let cursor = found;
  while (cursor !== startIndex && cursor >= 0) {
    back.push({ x: cursor % width, y: Math.floor(cursor / width) });
    cursor = from[cursor];
  }
  back.reverse();
  return straighten(back);
}

function clampIndex(world: FloorWorld, x: number, y: number): number {
  const cx = Math.min(world.w - 1, Math.max(0, x));
  const cy = Math.min(world.h - 1, Math.max(0, y));
  return cy * world.w + cx;
}

/** The nearest tile you can actually stand on, spiralling out from the goal. */
function nearestOpen(world: FloorWorld, goal: { x: number; y: number }): { x: number; y: number } | null {
  const gx = Math.round(goal.x);
  const gy = Math.round(goal.y);
  for (let radius = 0; radius < 8; radius += 1) {
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== radius) continue;
        const x = gx + dx;
        const y = gy + dy;
        if (x < 0 || y < 0 || x >= world.w || y >= world.h) continue;
        if (!world.blocked[y * world.w + x]) return { x, y };
      }
    }
  }
  return null;
}

/** Drop the waypoints that only exist because the grid has corners. */
function straighten(path: { x: number; y: number }[]): { x: number; y: number }[] {
  if (path.length < 3) return path;
  const out = [path[0]];
  for (let i = 1; i < path.length - 1; i += 1) {
    const previous = out[out.length - 1];
    const next = path[i + 1];
    const straight =
      (previous.x === path[i].x && path[i].x === next.x) ||
      (previous.y === path[i].y && path[i].y === next.y);
    if (!straight) out.push(path[i]);
  }
  out.push(path[path.length - 1]);
  return out;
}

// -------------------------------------------------------------------- odds

function seedOf(id: string): number {
  let seed = 0;
  for (const character of id) seed = (seed * 31 + character.charCodeAt(0)) >>> 0;
  return seed % 997;
}

/** What one object is doing right now, for its information panel. */
export interface ObjectReport {
  placed: PlacedItem;
  def: ItemDef;
  staff: Agent | null;
  queue: number;
  busy: boolean;
}

export function reportOn(world: FloorWorld, layout: Layout, itemId: string): ObjectReport | null {
  const placed = layout.items.find((it) => it.id === itemId);
  const def = placed ? item(placed.defId) : null;
  if (!placed || !def) return null;
  const staff = world.agents.find((a) => a.kind === 'staff' && a.targetId === itemId) ?? null;
  const queue = world.agents.filter(
    (a) => a.kind === 'customer' && a.targetId === itemId && (a.state === 'queueing' || a.state === 'paying'),
  ).length;
  return {
    placed,
    def,
    staff,
    queue,
    busy: Boolean(staff && (staff.state === 'serving' || staff.state === 'working')),
  };
}
