import type { GameState } from './state';
import { buildingById, employeesOf } from './state';
import type { Business, BusinessCategory } from './types';
import { businessTypeOrThrow } from '../data/businessTypes';
import { layoutOf, totals, type BuildingTotals, type SeedItem } from './layout';
import { storageUsed } from './business';
import { clamp, sum } from './util';

/**
 * What a business actually needs to trade.
 *
 * The temptation here is one list — desks, people, money — applied to every
 * business with a multiplier, and it would be wrong in the way that matters
 * most: it would make a bakery and a software firm the same game with different
 * nouns. A shop lives or dies on how fast it can put people through a till. A
 * kitchen lives or dies on how many covers it can cook and how many people can
 * sit down. A software firm lives or dies on whether the servers can carry the
 * customers. None of those three cares in the slightest about the other two.
 *
 * So a need profile is written per trade, and the profiles do not share rows.
 * The ones that look shared — space, people — are still scaled differently,
 * because a warehouse needs floor and a consultancy needs heads.
 *
 * Everything here is read. Nothing is stored: `currentAmount` comes from the
 * layout the player built, `requiredAmount` from the business as it is
 * currently trading, and both are recomputed whenever anybody asks. That is
 * what makes a need go green the instant the thing that was missing is bought,
 * and it is why there is no second copy of any of these numbers to drift.
 */

export type NeedStatus = 'critical' | 'warning' | 'healthy' | 'spare';

export type NeedKind =
  | 'workplaces' | 'equipment' | 'staff' | 'storage' | 'cold'
  | 'checkout' | 'cooking' | 'seats' | 'server' | 'calls' | 'bay'
  | 'space' | 'welfare' | 'management' | 'condition';

export interface Need {
  kind: NeedKind;
  name: string;
  /** What there is now. */
  current: number;
  /** What the business cannot trade properly without. */
  required: number;
  /** What it would want if money were no object. */
  ideal: number;
  status: NeedStatus;
  /** What it does, and what going without does. */
  matters: string;
  /** What is missing, said plainly. Empty when nothing is. */
  shortfall: string;
  /** Roughly what closing the gap costs, or 0 when nothing is needed. */
  cost: number;
  /** The item that would close it, so the screen can offer the button. */
  fix: string | null;
  /** How the figures read: a count, a rate, or an area. */
  unit: 'count' | 'perHour' | 'units' | 'tiles' | 'percent';
}

/** Which trade a business is, in the terms this file thinks in. */
export type Trade =
  | 'shop'
  | 'kitchen'
  | 'workshop'
  | 'office'
  | 'depot'
  | 'software'
  /** People come to use the place for an hour or an evening: a gym, a cinema, a club. */
  | 'venue'
  /** People sleep here. The rooms are the business. */
  | 'hotel'
  /** Big things on display that customers walk round before buying one. */
  | 'showroom'
  /** Things are made here, in quantity, by machines with operators on them. */
  | 'factory'
  /** The work happens somewhere else; this is the office and the yard behind it. */
  | 'site';

/**
 * A business type's trade.
 *
 * Read from what the type actually does rather than from a label on it: a type
 * that sells stock over a counter is a shop, one that cooks is a kitchen, one
 * that moves goods is a depot. This is what lets nineteen business types share
 * five genuinely different need profiles without anybody writing nineteen.
 */
export function tradeOf(business: Business): Trade {
  const type = businessTypeOrThrow(business.typeId);
  // The handful of trades whose operating model is their own, named before the
  // general rules below get a chance to file them under something close.
  const own: Record<string, Trade> = {
    autodealer: 'showroom',
    factory: 'factory',
    construction: 'site',
    hotel: 'hotel',
    cinema: 'venue',
    nightclub: 'venue',
    fitnessclub: 'venue',
  };
  if (own[type.id]) return own[type.id];
  if (type.category === 'food') return 'kitchen';
  if (type.category === 'retail') return 'shop';
  if (type.id === 'logistics') return 'depot';
  // A software business runs on servers. A marketing agency runs on people at
  // desks and would never buy one — which is why these are not the same trade
  // however similar the office looks.
  if (type.id === 'itservices') return 'software';
  if (type.id === 'marketing') return 'office';
  if (type.category === 'specialized') return 'workshop';
  // Services split on whether the work happens at a bench or at a desk.
  return type.productIds.length > 0 ? 'workshop' : 'office';
}

/**
 * How many customers one seat serves in an hour.
 *
 * A table is not one customer a day: people sit down, eat and leave, and the
 * seat is used again. Two and a half turns an hour is a café rather than a
 * restaurant, which is what most of the food businesses in this game are.
 */
export const SEAT_TURNS = 2.5;

/**
 * Every trade there is.
 *
 * Derived from the names rather than written twice, so adding a trade cannot
 * leave a list somewhere else quietly out of date — which is exactly what
 * happened the first time one was added.
 */
export const TRADE_NAMES: Record<Trade, string> = {
  shop: 'Shop',
  kitchen: 'Kitchen and dining room',
  workshop: 'Workshop',
  office: 'Office',
  depot: 'Depot',
  software: 'Software business',
  venue: 'Venue',
  hotel: 'Hotel',
  showroom: 'Showroom',
  factory: 'Factory',
  site: 'Yard and site office',
};

export const TRADES = Object.keys(TRADE_NAMES) as Trade[];

// ---------------------------------------------------------------- building

function statusFor(current: number, required: number, ideal: number): NeedStatus {
  if (required > 0 && current < required * 0.6) return 'critical';
  if (current < required) return 'warning';
  if (ideal > 0 && current > ideal * 1.8 && current > required + 2) return 'spare';
  return 'healthy';
}

interface Row {
  kind: NeedKind;
  name: string;
  current: number;
  required: number;
  ideal: number;
  matters: string;
  unit?: Need['unit'];
  fix?: string | null;
  unitCost?: number;
  /** What one of the fix items provides, for working out how many are needed. */
  per?: number;
}

function need(row: Row): Need {
  const status = statusFor(row.current, row.required, row.ideal);
  const missing = Math.max(0, row.required - row.current);
  const per = row.per ?? 1;
  const howMany = per > 0 ? Math.ceil(missing / per) : 0;
  return {
    kind: row.kind,
    name: row.name,
    current: Math.round(row.current * 10) / 10,
    required: Math.round(row.required * 10) / 10,
    ideal: Math.round(row.ideal * 10) / 10,
    status,
    matters: row.matters,
    shortfall: missing > 0 ? shortfallText(row, missing, howMany) : '',
    cost: missing > 0 ? Math.round(howMany * (row.unitCost ?? 0)) : 0,
    fix: missing > 0 ? (row.fix ?? null) : null,
    unit: row.unit ?? 'count',
  };
}

function shortfallText(row: Row, missing: number, howMany: number): string {
  const rounded = Math.round(missing * 10) / 10;
  switch (row.unit) {
    case 'perHour': return `${rounded} an hour short`;
    case 'units': return `${Math.round(missing)} units short`;
    case 'tiles': return `${Math.round(missing)} tiles short`;
    case 'percent': return `${Math.round(missing)} points below where it should be`;
    default: return howMany > 0 ? `${howMany} short` : `${rounded} short`;
  }
}

/** How busy the place actually is, which is what most requirements scale on. */
function demandPerHour(business: Business): number {
  const yesterday = business.yesterday.customers + business.yesterday.lostCustomers;
  const hours = Math.max(1, business.openTo - business.openFrom);
  // A business that has not traded yet is judged on what it expects, not on
  // nothing — otherwise a new shop opens with every need satisfied and the
  // player learns nothing until the first bad day.
  const expected = businessTypeOrThrow(business.typeId).baseCustomers;
  return Math.max(yesterday, expected) / hours;
}

/**
 * The needs of one business, in the order they should be read.
 *
 * The first rows are the ones particular to the trade, because those are the
 * decisions that make one business different from another. The shared rows —
 * room, welfare, the state of the kit — come after, because they matter
 * everywhere and are rarely the interesting problem.
 */
export function needsOf(state: GameState, business: Business): Need[] {
  const layout = layoutOf(state, business.buildingId);
  const building = buildingById(state, business.buildingId);
  // A building nobody has laid out has no needs to report: the game is using
  // the figures it always used, and inventing shortages against a floor plan
  // that does not exist would be telling the player off for not opening a
  // screen.
  if (!layout || !building) return [];
  const built = totals(layout);

  const heads = employeesOf(state, business.id).length;
  const perHour = demandPerHour(business);
  const trade = tradeOf(business);
  const type = businessTypeOrThrow(business.typeId);

  const rows: Need[] = [];

  // ---- what this trade in particular runs on
  if (trade === 'shop') {
    rows.push(need({
      kind: 'checkout', name: 'Checkout capacity', unit: 'perHour',
      current: built.checkout, required: perHour, ideal: perHour * 1.3,
      matters: 'However many people are on the floor, a shop serves customers as fast as it has tills. Anybody who will not queue leaves.',
      fix: 'till', unitCost: 3_200, per: 30,
    }));
    rows.push(need({
      kind: 'storage', name: 'Shelf and stock room', unit: 'units',
      current: building.storageCapacity + built.storage, required: storageUsed(business) * 1.1, ideal: storageUsed(business) * 1.6,
      matters: 'Stock has to go somewhere. A shop that cannot hold a delivery orders in small, expensive amounts.',
      fix: 'display-stand', unitCost: 420, per: 45,
    }));
  }

  if (trade === 'kitchen') {
    rows.push(need({
      kind: 'cooking', name: 'Kitchen capacity', unit: 'perHour',
      current: built.cooking, required: perHour, ideal: perHour * 1.25,
      matters: 'Covers a kitchen can actually send out. Past this, the dining room fills up with people waiting rather than eating.',
      fix: 'cooker', unitCost: 6_800, per: 22,
    }));
    rows.push(need({
      kind: 'seats', name: 'Seats',
      current: built.seats, required: Math.ceil(perHour / SEAT_TURNS), ideal: Math.ceil(perHour / 1.8),
      matters: `However fast the kitchen is, this is how many people can sit down. A seat serves about ${SEAT_TURNS} customers an hour before somebody has to wait for one.`,
      fix: 'dining-table', unitCost: 540, per: 4,
    }));
    rows.push(need({
      kind: 'cold', name: 'Refrigeration', unit: 'units',
      current: built.cold, required: perishableHeld(business), ideal: perishableHeld(business) * 1.5,
      matters: 'Perishable stock without cold storage is stock you throw away, and the waste comes straight off the margin.',
      fix: 'fridge', unitCost: 5_200, per: 180,
    }));
  }

  if (trade === 'software') {
    const online = Math.round(perHour * 34);
    rows.push(need({
      kind: 'server', name: 'Server capacity', unit: 'units',
      current: built.server, required: online, ideal: online * 1.4,
      matters: 'Every customer is load. Past what the servers carry, the service is slow for everybody and they stop coming back.',
      fix: 'server-rack', unitCost: 24_000, per: 400,
    }));
  }

  if (trade === 'office' || trade === 'software') {
    rows.push(need({
      kind: 'management', name: 'Somewhere to meet',
      current: built.meeting, required: heads > 5 ? Math.ceil(heads / 4) : 0, ideal: Math.ceil(heads / 3),
      matters: 'Work done for other people is agreed in rooms. A firm of this size without one has every conversation across the floor.',
      fix: 'meeting-table', unitCost: 1_400, per: 6,
    }));
  }

  if (trade === 'workshop') {
    rows.push(need({
      kind: 'calls', name: 'Jobs in hand at once',
      current: built.calls, required: Math.ceil(perHour * 0.8), ideal: Math.ceil(perHour * 1.1),
      matters: 'A job needs a bench and somebody at it. Work that cannot be started is work that goes elsewhere.',
      fix: 'workshop-bench', unitCost: 4_300, per: 1,
    }));
    rows.push(need({
      kind: 'storage', name: 'Parts and materials', unit: 'units',
      current: building.storageCapacity + built.storage, required: storageUsed(business) * 1.15, ideal: storageUsed(business) * 1.7,
      matters: 'A workshop without parts on the shelf is a workshop waiting on a delivery.',
      fix: 'shelving', unitCost: 600, per: 60,
    }));
  }

  if (trade === 'depot') {
    rows.push(need({
      kind: 'bay', name: 'Loading bays',
      current: built.bay, required: Math.max(1, Math.ceil(perHour / 6)), ideal: Math.max(2, Math.ceil(perHour / 4)),
      matters: 'Vans queue for a bay before they queue for anything else. A depot with one bay unloads one van.',
      fix: 'loading-bay', unitCost: 12_000, per: 1,
    }));
    rows.push(need({
      kind: 'storage', name: 'Warehouse space', unit: 'units',
      current: building.storageCapacity + built.storage, required: storageUsed(business) * 1.2, ideal: storageUsed(business) * 2,
      matters: 'Everything that comes in has to go somewhere before it goes out again.',
      fix: 'racking', unitCost: 2_400, per: 240,
    }));
  }

  // ---- and what every business needs, scaled by what this one is
  rows.push(need({
    kind: 'workplaces', name: 'Places to work',
    current: built.workstations, required: heads, ideal: heads + 2,
    matters: 'Somewhere of their own for each person on the payroll. Without one they are being paid to stand about.',
    fix: workplaceFor(trade), unitCost: workplaceCost(trade), per: 1,
  }));

  rows.push(need({
    kind: 'equipment', name: 'Equipped and working',
    current: built.workstations, required: built.workstations + built.bareDesks, ideal: built.workstations + built.bareDesks,
    matters: 'A desk with nothing on it is furniture. Equipment is what turns a place to sit into a job.',
    fix: 'computer', unitCost: 800, per: 1,
  }));

  rows.push(need({
    kind: 'staff', name: 'People',
    current: heads, required: Math.max(1, Math.ceil(perHour / Math.max(1, type.customersPerStaffHour))), ideal: Math.max(2, Math.ceil(perHour / Math.max(1, type.customersPerStaffHour)) + 1),
    matters: 'The people who actually do the work. Everything else here is what they do it with.',
    fix: null, unitCost: 0,
  }));

  rows.push(need({
    kind: 'space', name: 'Room to move', unit: 'tiles',
    current: built.area - built.used, required: heads * 4, ideal: heads * 8,
    matters: 'Floor that is not already occupied. A place packed to the walls is slower and nobody enjoys being in it.',
    fix: null, unitCost: 0,
  }));

  rows.push(need({
    kind: 'welfare', name: 'Facilities for the staff',
    current: built.sanitary, required: heads, ideal: heads + 4,
    matters: 'Plumbing for the number of people in the building. Going without is noticed every single day.',
    fix: 'toilets', unitCost: 3_400, per: 12,
  }));

  const worn = layout.items.filter((placed) => (placed.condition ?? 100) < 60).length;
  rows.push(need({
    kind: 'condition', name: 'Kit in good order', unit: 'percent',
    current: Math.round(averageCondition(state, business)), required: 70, ideal: 90,
    matters: 'Worn-out equipment does less than it should and costs more to keep. Below sixty per cent it is visibly failing.',
    fix: null, unitCost: 0,
  }));
  if (worn > 0) {
    rows[rows.length - 1].shortfall = `${worn} ${worn === 1 ? 'thing needs' : 'things need'} attention`;
  }

  return rows;
}

function workplaceFor(trade: Trade): string {
  if (trade === 'shop') return 'till';
  if (trade === 'kitchen') return 'cooker';
  if (trade === 'workshop') return 'workshop-bench';
  if (trade === 'depot') return 'loading-bay';
  return 'desk';
}

function workplaceCost(trade: Trade): number {
  if (trade === 'shop') return 3_200;
  if (trade === 'kitchen') return 6_800;
  if (trade === 'workshop') return 4_300;
  if (trade === 'depot') return 12_000;
  return 1_300;
}

/** How much perishable stock is sitting in the building right now. */
function perishableHeld(business: Business): number {
  return Math.round(sum(Object.values(business.stock), (units) => units) * 0.4);
}

export function averageCondition(state: GameState, business: Business): number {
  const layout = layoutOf(state, business.buildingId);
  if (!layout || layout.items.length === 0) return 100;
  return sum(layout.items, (placed) => placed.condition ?? 100) / layout.items.length;
}

/**
 * The kit a building already in use is understood to have.
 *
 * Opening the designer on a shop that has been trading for a year must not
 * change that shop. It plainly has a counter, because it has been serving
 * people; it plainly has somewhere to put the stock, because it has been
 * holding some. None of that was ever drawn, and this is what draws it — free,
 * because the company has been paying for it all along in the setup cost it
 * paid to open.
 *
 * Written per trade for the same reason the needs are: a kitchen that opened
 * with a shop's worth of tills would be as wrong as a shop with an oven.
 */
export function openingKit(state: GameState, business: Business): SeedItem[] {
  const type = businessTypeOrThrow(business.typeId);
  const heads = Math.max(1, employeesOf(state, business.id).length);
  const trade = tradeOf(business);
  // Sized on what the place demonstrably does rather than on what it is
  // expected to do. A coffee shop with three people behind the counter has
  // been serving what three people can serve, and giving it one machine's
  // worth of capacity would halve it the moment the screen was opened — which
  // it did, until this line read the staff as well as the demand.
  const perHour = Math.max(
    demandPerHour(business),
    heads * type.customersPerStaffHour,
  );

  // A building people have been working in has a lavatory in it. Nobody drew
  // it, and leaving it out meant opening the screen reported a critical
  // shortage in a business that had been trading happily for a year.
  const welfare: SeedItem[] = [{ defId: 'toilets', count: Math.max(1, Math.ceil(heads / 12)) }];

  /**
   * Somewhere for everybody the trade's own workplaces do not seat.
   *
   * Not everyone in a shop stands at a till: somebody does the ordering, and
   * somebody is in the back with the stock. Without this, opening the screen
   * on a clothes shop with five staff and two tills declared three of them to
   * have nowhere to work — which was true of the drawing and not of the shop.
   */
  const backOffice = (seated: number): SeedItem[] => {
    const left = Math.max(0, heads - seated);
    return left > 0 ? [{ defId: 'desk', count: left, equip: 'computer' }] : [];
  };

  switch (trade) {
    case 'shop': {
      const tills = Math.max(1, Math.ceil(perHour / 30));
      return [
        { defId: 'till', count: tills },
        { defId: 'display-stand', count: Math.max(2, Math.ceil(heads / 2)) },
        ...backOffice(tills),
        ...welfare,
      ];
    }
    case 'kitchen': {
      const ranges = Math.max(1, Math.ceil(perHour / 22));
      return [
        { defId: 'cooker', count: ranges },
        { defId: 'dining-table', count: Math.max(2, Math.ceil(perHour / SEAT_TURNS / 4)) },
        { defId: 'fridge', count: 1 },
        ...backOffice(ranges),
        ...welfare,
      ];
    }
    case 'workshop': {
      const benches = Math.max(1, Math.ceil(perHour * 0.8));
      return [
        { defId: 'workshop-bench', count: benches },
        { defId: 'shelving', count: 2 },
        ...backOffice(benches),
        ...welfare,
      ];
    }
    case 'depot': {
      const bays = Math.max(1, Math.ceil(perHour / 6));
      return [
        { defId: 'loading-bay', count: bays },
        { defId: 'racking', count: 2 },
        ...backOffice(bays),
        ...welfare,
      ];
    }
    case 'software':
      return [
        { defId: 'desk', count: Math.max(1, Math.max(heads, type.roles.length * 3)), equip: 'computer' },
        { defId: 'server-rack', count: Math.max(1, Math.ceil(perHour * 34 / 400)) },
        ...welfare,
      ];
    case 'office':
    default:
      return [
        { defId: 'desk', count: Math.max(1, Math.max(heads, type.roles.length * 3)), equip: 'computer' },
        ...welfare,
      ];
  }
}

// ------------------------------------------------------- operational readiness

export interface Readiness {
  /** 0..100, and the parts it is made of. */
  overall: number;
  parts: { name: string; value: number; status: NeedStatus }[];
  /** The single thing most holding this business back, if anything is. */
  bottleneck: Need | null;
}

/**
 * How ready a business is to actually trade.
 *
 * The average of how well each of its needs is met, weighted so that the
 * trade's own capacity driver counts for more than the office plant. Read from
 * the same rows the needs panel shows, so the headline figure and the detail
 * can never disagree — which is the usual failing of a readiness number.
 */
export function readinessOf(state: GameState, business: Business): Readiness {
  const rows = needsOf(state, business);
  if (rows.length === 0) return { overall: 100, parts: [], bottleneck: null };

  const weightOf = (kind: NeedKind): number => {
    if (['checkout', 'cooking', 'server', 'calls', 'bay'].includes(kind)) return 3;
    if (['workplaces', 'staff', 'equipment'].includes(kind)) return 2.5;
    if (['seats', 'cold', 'storage'].includes(kind)) return 2;
    return 1;
  };

  let total = 0;
  let weight = 0;
  const parts = rows.map((row) => {
    const met = row.required <= 0 ? 1 : clamp(row.current / row.required, 0, 1);
    const w = weightOf(row.kind);
    total += met * w;
    weight += w;
    return { name: row.name, value: Math.round(met * 100), status: row.status };
  });

  const short = rows.filter((row) => row.status === 'critical' || row.status === 'warning');
  short.sort((a, b) => {
    const gapA = a.required > 0 ? a.current / a.required : 1;
    const gapB = b.required > 0 ? b.current / b.required : 1;
    if (Math.abs(gapA - gapB) > 0.01) return gapA - gapB;
    return weightOf(b.kind) - weightOf(a.kind);
  });

  return {
    overall: Math.round((total / Math.max(1, weight)) * 100),
    parts,
    bottleneck: short[0] ?? null,
  };
}

// ------------------------------------------------------------ the ceiling

/**
 * The most customers this business can serve in an hour, whatever its staff.
 *
 * This is where a need stops being a number on a screen. A shop with one till
 * serves thirty people an hour with four staff on the floor and thirty with
 * fourteen, and the fourteenth person's wages are simply gone. Every trade has
 * one of these and they are not the same thing, which is the whole argument
 * for writing them per trade.
 *
 * A building nobody has laid out has no ceiling at all, so nothing changes for
 * a business the player has never opened the designer on.
 */
export function capacityCeiling(state: GameState, business: Business): number {
  const layout = layoutOf(state, business.buildingId);
  if (!layout) return Infinity;
  const built = totals(layout);
  const trade = tradeOf(business);

  switch (trade) {
    case 'shop':
      // Tills, and nothing else. A shop with no till at all can still serve a
      // handful over the counter by hand, which is what a market stall is.
      return built.checkout > 0 ? built.checkout : 6;
    case 'kitchen': {
      // The lower of what can be cooked and what can be sat down, because
      // either one empty is a queue at the door.
      const cooked = built.cooking > 0 ? built.cooking : 5;
      const seated = built.seats > 0 ? built.seats * SEAT_TURNS : 4;
      return Math.min(cooked, seated);
    }
    case 'workshop':
      return built.calls > 0 ? built.calls * 1.4 : 3;
    case 'depot':
      return built.bay > 0 ? built.bay * 6 : 2;
    case 'venue':
      // Whatever people come to use: machines in a gym, seats in a cinema, room
      // on a dance floor. Nobody queues for long at a venue — they look at how
      // full it is and go somewhere else, which is what the ceiling models.
      return built.station > 0 ? built.station * 1.2 : 4;
    case 'hotel':
      // Rooms, and only rooms. Everything else a hotel has is there to make the
      // rooms worth more, not to let it sell more of them.
      return built.room > 0 ? built.room * 0.9 : 1;
    case 'showroom':
      // How many cars are standing where somebody can walk round them. A
      // dealership with a full yard and no showroom sells what it can show.
      return built.display > 0 ? built.display * 0.8 : 1;
    case 'factory':
      // The line. A factory is not limited by how many people walk in — it is
      // limited by what it can make, and the orders follow the output.
      return built.production > 0 ? built.production * 2.2 : 2;
    case 'site':
      // The jobs that can be run at once, which is a question of supervision
      // and plant rather than of counter space.
      return built.calls > 0 ? built.calls * 1.1 : 2;
    case 'office':
    default:
      // An office is limited by the desks people work at rather than by a
      // counter, and that is already the capacity system — so no second
      // ceiling, and the server need shows up as reputation instead.
      return Infinity;
  }
}

/** Every business the player runs, worst readiness first. */
export function worstBusinesses(state: GameState, limit = 5): { business: Business; readiness: Readiness }[] {
  return state.businesses
    .filter((b) => b.companyId === state.playerCompanyId && b.status === 'open')
    .map((business) => ({ business, readiness: readinessOf(state, business) }))
    .filter((row) => row.readiness.bottleneck !== null)
    .sort((a, b) => a.readiness.overall - b.readiness.overall)
    .slice(0, limit);
}

export type { BuildingTotals, BusinessCategory };
