import type { Layout, PlacedItem, Room, Rotation } from '../sim/layout';
import { canPlace, footprint, roomsOn, tilesOf } from '../sim/layout';
import type { ItemDef } from '../data/buildingItems';
import { item } from '../data/buildingItems';
import { clamp } from '../sim/util';

/**
 * The floor the player is drawing on.
 *
 * Canvas rather than DOM, for the same reason the city map is: a floor plate is
 * a few hundred tiles and a few hundred objects, and a thousand absolutely
 * positioned elements that re-layout every time a desk moves one square is a
 * different, worse program. Here, moving a desk repaints one canvas and touches
 * no DOM at all — which is also what keeps the page from scrolling anywhere it
 * was not asked to.
 *
 * The view is a straight top-down plan with a slight three-dimensional lift on
 * anything that stands up, which is how a floor plan reads as a room rather
 * than as a diagram. Everything is drawn in code at the device's real pixel
 * density, so it stays sharp at any zoom.
 */

const MIN_ZOOM = 12;
const MAX_ZOOM = 64;

export type Tool =
  | { kind: 'select' }
  | { kind: 'place'; defId: string; rot: Rotation }
  | { kind: 'edge'; edge: 'wall' | 'door' | 'window' }
  | { kind: 'erase' };

export interface TileHit {
  x: number;
  y: number;
}

export interface EdgeHit {
  x: number;
  y: number;
  dir: 'h' | 'v';
}

/**
 * The palette the floor is drawn in.
 *
 * Kept here rather than read from the stylesheet because this is a canvas:
 * there is no element to inherit a custom property from. The values are the
 * same family as the rest of the interface, and the design check knows to
 * look here rather than treating them as strays.
 */
const PAINT = {
  ground: '#12192b',
  grid: 'rgba(120, 150, 200, 0.10)',
  gridStrong: 'rgba(120, 150, 200, 0.22)',
  shell: '#8b98b5',
  door: '#2f7bff',
  window: '#38bdf8',
  selected: '#5b9bff',
  good: '#2fbf7e',
  bad: '#ef4657',
};

const COLOURS: Record<string, { top: string; side: string }> = {
  desk: { top: '#b0875a', side: '#8a6743' },
  chair: { top: '#39445c', side: '#2a3246' },
  table: { top: '#a8763f', side: '#835a2f' },
  soft: { top: '#d5d8e0', side: '#a9adb8' },
  cabinet: { top: '#8d7150', side: '#6d573d' },
  screen: { top: '#3d4a68', side: '#2c3650' },
  machine: { top: '#5a6275', side: '#434a59' },
  rack: { top: '#7b6748', side: '#5d4e37' },
  plant: { top: '#3f8d5c', side: '#2f6a45' },
  lamp: { top: '#e2c979', side: '#b7a15c' },
  plumbing: { top: '#7f97ad', side: '#63768a' },
  counter: { top: '#9a8256', side: '#786641' },
  board: { top: '#e6e9ef', side: '#b4b8c2' },
};

const ROOM_TINT: Record<string, string> = {
  work: 'rgba(47, 123, 255, 0.07)',
  meeting: 'rgba(139, 92, 246, 0.09)',
  training: 'rgba(56, 189, 248, 0.09)',
  break: 'rgba(47, 191, 126, 0.09)',
  storage: 'rgba(245, 158, 11, 0.08)',
  reception: 'rgba(47, 123, 255, 0.05)',
  sanitary: 'rgba(125, 211, 252, 0.07)',
  management: 'rgba(168, 85, 247, 0.07)',
  production: 'rgba(239, 70, 87, 0.06)',
  empty: 'rgba(0, 0, 0, 0)',
};

export class DesignerCanvas {
  /** The canvas currently on screen, so a browser test can drive the editor. */
  static current: DesignerCanvas | null = null;

  readonly canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private layout: Layout;
  private floor = 0;
  private zoom = 26;
  private panX = 0;
  private panY = 0;
  private dpr = 1;
  private cssW = 0;
  private cssH = 0;
  private hover: TileHit | null = null;
  private hoverEdge: EdgeHit | null = null;
  private selectedId: string | null = null;
  private tool: Tool = { kind: 'select' };
  private dragging: { id: string; dx: number; dy: number; fromX: number; fromY: number } | null = null;
  private panning: { x: number; y: number; panX: number; panY: number } | null = null;
  private rooms: Room[] = [];
  private resizeObserver: ResizeObserver | null = null;
  private frame: number | null = null;
  private showGrid = true;

  /** Something was placed, moved, rotated or deleted. */
  onChange: (what: string) => void = () => {};
  onSelect: (placed: PlacedItem | null) => void = () => {};
  onPlace: (x: number, y: number) => void = () => {};
  onEdge: (edge: EdgeHit) => void = () => {};
  onEraseEdge: (edge: EdgeHit) => void = () => {};
  onMoved: (id: string, x: number, y: number) => boolean = () => false;

  constructor(layout: Layout) {
    this.layout = layout;
    this.canvas = document.createElement('canvas');
    this.canvas.className = 'plan-canvas';
    const context = this.canvas.getContext('2d');
    if (!context) throw new Error('Canvas 2D is not available in this browser.');
    this.ctx = context;
    DesignerCanvas.current = this;
    this.attach();
    this.recomputeRooms();
  }

  destroy(): void {
    if (this.frame !== null) cancelAnimationFrame(this.frame);
    this.resizeObserver?.disconnect();
    if (DesignerCanvas.current === this) DesignerCanvas.current = null;
  }

  // ------------------------------------------------------------- the state

  setLayout(layout: Layout): void {
    this.layout = layout;
    this.recomputeRooms();
    this.draw();
  }

  setFloor(floor: number): void {
    this.floor = clamp(floor, 0, this.layout.floors - 1);
    this.selectedId = null;
    this.recomputeRooms();
    this.draw();
  }

  getFloor(): number {
    return this.floor;
  }

  setTool(tool: Tool): void {
    this.tool = tool;
    if (tool.kind !== 'select') {
      this.selectedId = null;
      this.onSelect(null);
    }
    this.draw();
  }

  getTool(): Tool {
    return this.tool;
  }

  setGrid(on: boolean): void {
    this.showGrid = on;
    this.draw();
  }

  getGrid(): boolean {
    return this.showGrid;
  }

  // The camera, readable from outside. The editor is a canvas, so a test that
  // wants to click a particular tile has no element to aim at — it has to be
  // able to work out where that tile currently is on screen.
  zoomNow(): number {
    return this.zoom;
  }

  panNow(): { x: number; y: number } {
    return { x: this.panX, y: this.panY };
  }

  buildingId(): string {
    return this.layout.buildingId;
  }

  select(id: string | null): void {
    this.selectedId = id;
    this.draw();
  }

  selected(): PlacedItem | null {
    return this.layout.items.find((p) => p.id === this.selectedId) ?? null;
  }

  /** Rooms are recomputed when the walls change, not on every frame. */
  recomputeRooms(): void {
    this.rooms = roomsOn(this.layout, this.floor);
  }

  roomsNow(): Room[] {
    return this.rooms;
  }

  /** The room a tile belongs to, for the properties panel. */
  roomAt(x: number, y: number): Room | null {
    return this.rooms.find((room) => room.tiles.some((t) => t.x === x && t.y === y)) ?? null;
  }

  zoomBy(factor: number): void {
    this.zoom = clamp(this.zoom * factor, MIN_ZOOM, MAX_ZOOM);
    this.draw();
  }

  fit(): void {
    if (this.cssW === 0) this.resize();
    const pad = 28;
    const byWidth = (this.cssW - pad * 2) / this.layout.w;
    const byHeight = (this.cssH - pad * 2) / this.layout.h;
    this.zoom = clamp(Math.min(byWidth, byHeight), MIN_ZOOM, MAX_ZOOM);
    this.panX = (this.cssW - this.layout.w * this.zoom) / 2;
    this.panY = (this.cssH - this.layout.h * this.zoom) / 2;
    this.draw();
  }

  // ------------------------------------------------------------- the view

  resize(): void {
    const parent = this.canvas.parentElement;
    if (!parent) return;
    const width = parent.clientWidth;
    const height = parent.clientHeight;
    if (width === 0 || height === 0) return;
    this.dpr = Math.min(window.devicePixelRatio || 1, 3);
    this.cssW = width;
    this.cssH = height;
    this.canvas.width = Math.round(width * this.dpr);
    this.canvas.height = Math.round(height * this.dpr);
    this.canvas.style.width = `${width}px`;
    this.canvas.style.height = `${height}px`;
    this.draw();
  }

  /** Repaint on the next frame, never more than once per frame. */
  draw(): void {
    if (this.frame !== null) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = null;
      this.paint();
    });
  }

  private toTile(clientX: number, clientY: number): { x: number; y: number; fx: number; fy: number } {
    const rect = this.canvas.getBoundingClientRect();
    const fx = (clientX - rect.left - this.panX) / this.zoom;
    const fy = (clientY - rect.top - this.panY) / this.zoom;
    return { x: Math.floor(fx), y: Math.floor(fy), fx, fy };
  }

  /** Which tile edge a point is nearest, for the wall tools. */
  private toEdge(clientX: number, clientY: number): EdgeHit | null {
    const { x, y, fx, fy } = this.toTile(clientX, clientY);
    if (x < 0 || y < 0 || x > this.layout.w || y > this.layout.h) return null;
    const ox = fx - x;
    const oy = fy - y;
    // Whichever edge of this tile the pointer is closest to.
    const distances: { d: number; hit: EdgeHit }[] = [
      { d: oy, hit: { x, y, dir: 'h' } },
      { d: 1 - oy, hit: { x, y: y + 1, dir: 'h' } },
      { d: ox, hit: { x, y, dir: 'v' } },
      { d: 1 - ox, hit: { x: x + 1, y, dir: 'v' } },
    ];
    distances.sort((a, b) => a.d - b.d);
    const best = distances[0].hit;
    if (best.dir === 'h' && (best.x < 0 || best.x >= this.layout.w || best.y < 0 || best.y > this.layout.h)) return null;
    if (best.dir === 'v' && (best.y < 0 || best.y >= this.layout.h || best.x < 0 || best.x > this.layout.w)) return null;
    return best;
  }

  /** Whether anything stands on a given edge of this floor. */
  private wallAt(edge: EdgeHit): boolean {
    return this.layout.walls.some(
      (w) => w.floor === this.floor && w.x === edge.x && w.y === edge.y && w.dir === edge.dir,
    );
  }

  private itemAt(x: number, y: number): PlacedItem | null {
    // Last drawn wins, which is the one on top.
    for (let i = this.layout.items.length - 1; i >= 0; i -= 1) {
      const placed = this.layout.items[i];
      if (placed.floor !== this.floor) continue;
      if (tilesOf(placed).some((t) => t.x === x && t.y === y)) return placed;
    }
    return null;
  }

  // ------------------------------------------------------------- pointers

  private attach(): void {
    const canvas = this.canvas;
    canvas.style.touchAction = 'none';

    canvas.addEventListener('pointerdown', (event) => {
      // Never let a click on the plan move the page. The editor lives inside a
      // scrolling column and a focus change here used to be enough to jump it.
      event.preventDefault();
      canvas.setPointerCapture(event.pointerId);
      const tile = this.toTile(event.clientX, event.clientY);

      // Middle button, or space-drag, pans. Everything else is the tool.
      if (event.button === 1 || event.shiftKey) {
        this.panning = { x: event.clientX, y: event.clientY, panX: this.panX, panY: this.panY };
        return;
      }

      if (this.tool.kind === 'edge') {
        const edge = this.toEdge(event.clientX, event.clientY);
        if (edge) this.onEdge(edge);
        return;
      }

      if (this.tool.kind === 'place') {
        this.onPlace(tile.x, tile.y);
        return;
      }

      const hit = this.itemAt(tile.x, tile.y);
      if (this.tool.kind === 'erase') {
        // A wall is as removable as a desk. Whichever is actually under the
        // pointer is the thing that goes — the item if there is one, otherwise
        // the wall the pointer is nearest to.
        if (hit) {
          this.onChange(`erase:${hit.id}`);
          return;
        }
        const edge = this.toEdge(event.clientX, event.clientY);
        if (edge && this.wallAt(edge)) this.onEraseEdge(edge);
        return;
      }

      this.selectedId = hit?.id ?? null;
      this.onSelect(hit);
      if (hit) {
        this.dragging = { id: hit.id, dx: tile.x - hit.x, dy: tile.y - hit.y, fromX: hit.x, fromY: hit.y };
      } else {
        this.panning = { x: event.clientX, y: event.clientY, panX: this.panX, panY: this.panY };
      }
      this.draw();
    });

    canvas.addEventListener('pointermove', (event) => {
      const tile = this.toTile(event.clientX, event.clientY);

      if (this.panning) {
        this.panX = this.panning.panX + (event.clientX - this.panning.x);
        this.panY = this.panning.panY + (event.clientY - this.panning.y);
        this.draw();
        return;
      }

      if (this.dragging) {
        const placed = this.layout.items.find((p) => p.id === this.dragging?.id);
        if (placed) {
          const x = tile.x - this.dragging.dx;
          const y = tile.y - this.dragging.dy;
          if ((x !== placed.x || y !== placed.y) && this.onMoved(placed.id, x, y)) this.recomputeRooms();
          this.draw();
        }
        return;
      }

      const changed = this.hover?.x !== tile.x || this.hover?.y !== tile.y;
      this.hover = { x: tile.x, y: tile.y };
      if (this.tool.kind === 'edge' || this.tool.kind === 'erase') {
        this.hoverEdge = this.toEdge(event.clientX, event.clientY);
      } else {
        this.hoverEdge = null;
      }
      if (changed || this.tool.kind === 'edge' || this.tool.kind === 'erase') this.draw();
    });

    const release = (event: PointerEvent): void => {
      if (this.dragging) {
        const placed = this.layout.items.find((p) => p.id === this.dragging?.id);
        if (placed && (placed.x !== this.dragging.fromX || placed.y !== this.dragging.fromY)) {
          this.onChange(`move:${placed.id}`);
        }
      }
      this.dragging = null;
      this.panning = null;
      if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
    };
    canvas.addEventListener('pointerup', release);
    canvas.addEventListener('pointercancel', release);
    canvas.addEventListener('pointerleave', () => {
      this.hover = null;
      this.hoverEdge = null;
      this.draw();
    });

    canvas.addEventListener('wheel', (event) => {
      // The plan zooms; the page does not move. Both halves matter.
      event.preventDefault();
      const before = this.toTile(event.clientX, event.clientY);
      this.zoom = clamp(this.zoom * (event.deltaY < 0 ? 1.12 : 1 / 1.12), MIN_ZOOM, MAX_ZOOM);
      const after = this.toTile(event.clientX, event.clientY);
      this.panX += (after.fx - before.fx) * this.zoom;
      this.panY += (after.fy - before.fy) * this.zoom;
      this.draw();
    }, { passive: false });

    if ('ResizeObserver' in window) {
      this.resizeObserver = new ResizeObserver(() => this.resize());
      const parent = this.canvas.parentElement;
      if (parent) this.resizeObserver.observe(parent);
    }
  }

  // -------------------------------------------------------------- painting

  private paint(): void {
    const ctx = this.ctx;
    if (this.cssW === 0) this.resize();
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.cssW, this.cssH);

    ctx.save();
    ctx.translate(this.panX, this.panY);

    const z = this.zoom;
    const w = this.layout.w;
    const h = this.layout.h;

    // The slab, with a shadow so it reads as a thing sitting in space.
    ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
    ctx.fillRect(6, 8, w * z, h * z);
    ctx.fillStyle = PAINT.ground;
    ctx.fillRect(0, 0, w * z, h * z);

    this.paintRooms(ctx, z);
    if (this.showGrid) this.paintGrid(ctx, z, w, h);
    this.paintWalls(ctx, z);
    this.paintItems(ctx, z);
    this.paintPreview(ctx, z);
    this.paintShell(ctx, z, w, h);

    ctx.restore();
  }

  private paintRooms(ctx: CanvasRenderingContext2D, z: number): void {
    for (const room of this.rooms) {
      const tint = ROOM_TINT[room.kind] ?? ROOM_TINT.empty;
      if (tint === ROOM_TINT.empty) continue;
      ctx.fillStyle = tint;
      for (const tile of room.tiles) ctx.fillRect(tile.x * z, tile.y * z, z, z);
    }
  }

  private paintGrid(ctx: CanvasRenderingContext2D, z: number, w: number, h: number): void {
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x += 1) {
      ctx.strokeStyle = x % 5 === 0 ? PAINT.gridStrong : PAINT.grid;
      ctx.beginPath();
      ctx.moveTo(Math.round(x * z) + 0.5, 0);
      ctx.lineTo(Math.round(x * z) + 0.5, h * z);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += 1) {
      ctx.strokeStyle = y % 5 === 0 ? PAINT.gridStrong : PAINT.grid;
      ctx.beginPath();
      ctx.moveTo(0, Math.round(y * z) + 0.5);
      ctx.lineTo(w * z, Math.round(y * z) + 0.5);
      ctx.stroke();
    }
  }

  private paintWalls(ctx: CanvasRenderingContext2D, z: number): void {
    const thickness = Math.max(3, z * 0.16);
    for (const wall of this.layout.walls) {
      if (wall.floor !== this.floor) continue;
      const x = wall.x * z;
      const y = wall.y * z;
      ctx.fillStyle = wall.kind === 'wall' ? PAINT.shell : wall.kind === 'door' ? PAINT.door : PAINT.window;
      if (wall.dir === 'h') ctx.fillRect(x, y - thickness / 2, z, thickness);
      else ctx.fillRect(x - thickness / 2, y, thickness, z);

      // A door is drawn as a gap with a swing; a window as a lighter bar. Both
      // have to be tellable apart at a glance or the plan is unreadable.
      if (wall.kind === 'door') {
        ctx.fillStyle = PAINT.ground;
        if (wall.dir === 'h') ctx.fillRect(x + z * 0.2, y - thickness / 2, z * 0.6, thickness);
        else ctx.fillRect(x - thickness / 2, y + z * 0.2, thickness, z * 0.6);
        ctx.strokeStyle = 'rgba(47, 123, 255, 0.85)';
        ctx.lineWidth = Math.max(1.2, z * 0.05);
        ctx.beginPath();
        if (wall.dir === 'h') ctx.arc(x + z * 0.2, y, z * 0.6, -Math.PI / 2, 0);
        else ctx.arc(x, y + z * 0.2, z * 0.6, 0, Math.PI / 2);
        ctx.stroke();
      }
    }
  }

  private paintItems(ctx: CanvasRenderingContext2D, z: number): void {
    // Flat things first, then everything that stands up, so a desk sits on the
    // rug rather than under it.
    const here = this.layout.items.filter((placed) => placed.floor === this.floor);
    const flat = here.filter((placed) => item(placed.defId)?.flat);
    const standing = here.filter((placed) => !item(placed.defId)?.flat);
    // Anything small enough to be sitting on a piece of furniture is drawn
    // inset and last, so a computer reads as a thing on a desk rather than as
    // a second object fighting it for the tile.
    const onTop = new Set<string>();
    for (const placed of standing) {
      const def = item(placed.defId);
      if (!def || def.w !== 1 || def.h !== 1) continue;
      const mine = tilesOf(placed);
      const under = standing.some((other) => {
        if (other.id === placed.id) return false;
        const otherDef = item(other.defId);
        if (!otherDef || !['desk', 'table', 'counter'].includes(otherDef.look)) return false;
        return tilesOf(other).some((t) => mine.some((m) => m.x === t.x && m.y === t.y));
      });
      if (under) onTop.add(placed.id);
    }
    const loose = standing.filter((placed) => !onTop.has(placed.id));
    const perched = standing.filter((placed) => onTop.has(placed.id));
    for (const placed of [...flat, ...loose, ...perched]) this.paintItem(ctx, z, placed, onTop.has(placed.id));
  }

  private paintItem(ctx: CanvasRenderingContext2D, z: number, placed: PlacedItem, perched = false): void {
    const def = item(placed.defId);
    if (!def) return;
    const box = footprint(def, placed.rot);
    const x = placed.x * z;
    const y = placed.y * z;
    const w = box.w * z;
    const h = box.h * z;
    const paint = COLOURS[def.look] ?? COLOURS.cabinet;
    // Something standing on furniture is drawn smaller and higher, which is
    // what "on the desk" looks like from above.
    const pad = def.flat ? 0 : perched ? z * 0.24 : Math.min(z * 0.08, 3);
    const lift = def.flat ? 0 : perched ? Math.max(3, z * 0.18) : Math.max(2, z * 0.1);

    if (!def.flat) {
      // The side, which is what makes the plan read as a room of objects
      // rather than as a set of coloured rectangles.
      ctx.fillStyle = paint.side;
      roundRect(ctx, x + pad, y + pad, w - pad * 2, h - pad * 2, Math.min(4, z * 0.14));
      ctx.fill();
    }
    ctx.fillStyle = def.flat ? withAlpha(paint.top, 0.4) : paint.top;
    roundRect(ctx, x + pad, y + pad - lift, w - pad * 2, h - pad * 2, Math.min(4, z * 0.14));
    ctx.fill();

    this.paintDetail(ctx, z, def, x + pad, y + pad - lift, w - pad * 2, h - pad * 2);

    if (placed.id === this.selectedId) {
      ctx.strokeStyle = PAINT.selected;
      ctx.lineWidth = Math.max(2, z * 0.08);
      roundRect(ctx, x + 1, y + 1 - lift, w - 2, h - 2, Math.min(5, z * 0.16));
      ctx.stroke();
    }
  }

  /**
   * The bit that makes an object recognisable.
   *
   * A screen on a desk, slats on a rack, leaves on a plant. Three or four
   * strokes each: enough that a floor of thirty objects reads at a glance, and
   * cheap enough that it repaints in a frame.
   */
  private paintDetail(ctx: CanvasRenderingContext2D, z: number, def: ItemDef, x: number, y: number, w: number, h: number): void {
    if (z < 14) return;
    ctx.save();
    switch (def.look) {
      case 'screen':
        ctx.fillStyle = '#9fd0ff';
        ctx.fillRect(x + w * 0.2, y + h * 0.18, w * 0.6, h * 0.42);
        break;
      case 'rack':
        ctx.strokeStyle = 'rgba(20, 16, 10, 0.5)';
        ctx.lineWidth = 1;
        for (let i = 1; i < 4; i += 1) {
          ctx.beginPath();
          ctx.moveTo(x, y + (h * i) / 4);
          ctx.lineTo(x + w, y + (h * i) / 4);
          ctx.stroke();
        }
        break;
      case 'plant':
        ctx.fillStyle = '#245c3b';
        ctx.beginPath();
        ctx.arc(x + w / 2, y + h / 2, Math.min(w, h) * 0.34, 0, Math.PI * 2);
        ctx.fill();
        break;
      case 'lamp':
        ctx.fillStyle = 'rgba(255, 236, 170, 0.5)';
        ctx.beginPath();
        ctx.arc(x + w / 2, y + h / 2, Math.min(w, h) * 0.45, 0, Math.PI * 2);
        ctx.fill();
        break;
      case 'plumbing':
        ctx.fillStyle = '#dfe9f2';
        ctx.fillRect(x + w * 0.22, y + h * 0.22, w * 0.24, h * 0.24);
        ctx.fillRect(x + w * 0.56, y + h * 0.22, w * 0.24, h * 0.24);
        break;
      case 'machine':
        ctx.fillStyle = 'rgba(15, 20, 30, 0.45)';
        ctx.fillRect(x + w * 0.16, y + h * 0.3, w * 0.68, h * 0.34);
        break;
      case 'table':
      case 'desk':
        ctx.strokeStyle = 'rgba(40, 26, 14, 0.35)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x + w * 0.08, y + h * 0.12, w * 0.84, h * 0.76);
        break;
      case 'board':
        ctx.strokeStyle = 'rgba(60, 70, 90, 0.5)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x + w * 0.1, y + h * 0.16, w * 0.8, h * 0.68);
        break;
      default:
        break;
    }
    ctx.restore();
  }

  /** The thing about to be placed, in green if it will go and red if it will not. */
  private paintPreview(ctx: CanvasRenderingContext2D, z: number): void {
    if (this.tool.kind === 'place' && this.hover) {
      const def = item(this.tool.defId);
      if (!def) return;
      const box = footprint(def, this.tool.rot);
      const ok = canPlace(this.layout, this.tool.defId, this.floor, this.hover.x, this.hover.y, this.tool.rot).ok;
      ctx.fillStyle = ok ? 'rgba(47, 191, 126, 0.28)' : 'rgba(239, 70, 87, 0.3)';
      ctx.strokeStyle = ok ? PAINT.good : PAINT.bad;
      ctx.lineWidth = 2;
      ctx.fillRect(this.hover.x * z, this.hover.y * z, box.w * z, box.h * z);
      ctx.strokeRect(this.hover.x * z + 1, this.hover.y * z + 1, box.w * z - 2, box.h * z - 2);
      return;
    }
    if (this.tool.kind === 'edge' && this.hoverEdge) {
      const thickness = Math.max(3, z * 0.16);
      ctx.fillStyle = 'rgba(91, 155, 255, 0.75)';
      const x = this.hoverEdge.x * z;
      const y = this.hoverEdge.y * z;
      if (this.hoverEdge.dir === 'h') ctx.fillRect(x, y - thickness / 2, z, thickness);
      else ctx.fillRect(x - thickness / 2, y, thickness, z);
      return;
    }
    if (this.tool.kind === 'erase' && this.hover) {
      const hit = this.itemAt(this.hover.x, this.hover.y);
      if (!hit) {
        if (this.hoverEdge && this.wallAt(this.hoverEdge)) {
          const thickness = Math.max(3, z * 0.16);
          ctx.fillStyle = 'rgba(239, 70, 87, 0.8)';
          const ex = this.hoverEdge.x * z;
          const ey = this.hoverEdge.y * z;
          if (this.hoverEdge.dir === 'h') ctx.fillRect(ex, ey - thickness / 2, z, thickness);
          else ctx.fillRect(ex - thickness / 2, ey, thickness, z);
        }
        return;
      }
      const def = item(hit.defId);
      if (!def) return;
      const box = footprint(def, hit.rot);
      ctx.fillStyle = 'rgba(239, 70, 87, 0.35)';
      ctx.fillRect(hit.x * z, hit.y * z, box.w * z, box.h * z);
    }
  }

  /** The outside walls, drawn last so nothing overlaps them. */
  private paintShell(ctx: CanvasRenderingContext2D, z: number, w: number, h: number): void {
    ctx.strokeStyle = PAINT.shell;
    ctx.lineWidth = Math.max(4, z * 0.2);
    ctx.strokeRect(0, 0, w * z, h * z);
  }
}

function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number): void {
  const radius = Math.max(0, Math.min(r, Math.min(w, h) / 2));
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function withAlpha(hex: string, alpha: number): string {
  const value = hex.replace('#', '');
  const r = parseInt(value.slice(0, 2), 16);
  const g = parseInt(value.slice(2, 4), 16);
  const b = parseInt(value.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
