import type { BusinessCategory, EmployeeRoleId } from '../sim/types';

/**
 * Everything that can be put inside a building.
 *
 * One table. A thing has a size in tiles, a price, and — this is the part that
 * matters — a `gives`, which is the only reason it exists. An item that gives
 * nothing is decoration, and decoration is allowed, but it has to say so rather
 * than pretending to be a system.
 *
 * Sizes are in tiles and are written for the unrotated object. A desk is two
 * tiles across and one deep; rotating it ninety degrees makes it one across and
 * two deep, and the placement code does that rather than a second definition.
 */

export type ItemCategory =
  | 'furniture'
  | 'workstation'
  | 'facility'
  | 'production'
  | 'storage'
  | 'decoration'
  | 'lighting';

/**
 * What a thing contributes, in the terms the rest of the game already uses.
 *
 * Deliberately a small, closed set. A room is worked out from what is standing
 * in it, so these are also the vocabulary rooms are recognised by.
 */
export interface ItemGives {
  /** A place one person can actually work. The headline number. */
  desk?: number;
  /** A desk is only a workstation once there is something on it to work with. */
  equips?: number;
  /** Seats at a table people meet around. */
  meeting?: number;
  /** Somewhere to learn. */
  training?: number;
  /** Somewhere to stop working for ten minutes. */
  rest?: number;
  /** Units of stock the racks hold. */
  storage?: number;
  /** Plumbing. A building above a certain size has to have some. */
  sanitary?: number;
  /** Where somebody is met when they walk in. */
  reception?: number;
  /** Where the company is run from. */
  management?: number;
  /** Output, for a building that makes things. */
  production?: number;
  /** How pleasant the place is to spend a day in, per item, with a ceiling. */
  comfort?: number;

  // ---- the capacity drivers, which are where one trade stops resembling
  // another. A till is the whole of a shop's throughput and means nothing to a
  // software firm; a server is the whole of a software firm's and means
  // nothing to a baker. Each of these is read by exactly one kind of business.

  /** Customers put through per hour. A shop's real ceiling. */
  checkout?: number;
  /** Covers a kitchen can send out per hour. */
  cooking?: number;
  /** People who can sit down at once. */
  seats?: number;
  /** Refrigerated storage, which is what stops perishable stock being binned. */
  cold?: number;
  /** Users a software business can carry. */
  server?: number;
  /** Calls or jobs that can be handled at once. */
  calls?: number;
  /** Vehicles that can be loaded at the same time. */
  bay?: number;
  /**
   * Places one customer can use a thing for a while: a treadmill, a cinema
   * seat, a lane, a spot on a dance floor. The capacity driver for anywhere
   * people come to *do* something rather than to buy something.
   */
  station?: number;
  /** Rooms a guest can sleep in. A hotel's entire business. */
  room?: number;
  /** Vehicles that can be shown to a customer at once. */
  display?: number;
}

export interface ItemDef {
  id: string;
  name: string;
  category: ItemCategory;
  /** Sub-heading in the build menu, so a long list stays readable. */
  group: string;
  /** Tiles across and deep, unrotated. */
  w: number;
  h: number;
  cost: number;
  /** One line, in the player's words. */
  detail: string;
  gives: ItemGives;
  /** What it costs to keep, per month, once it is standing there. */
  upkeep: number;
  /**
   * Condition lost per day in use.
   *
   * A chair wears out slowly and a production machine quickly, and that
   * difference is why maintenance is a decision in a factory and an
   * afterthought in an office.
   */
  wear: number;
  /** Who may be assigned to it, when it is somewhere a person works. */
  roles?: EmployeeRoleId[];
  /** What it becomes, and for how much. */
  upgradesTo?: string;
  /**
   * Other things it needs in order to work at all.
   *
   * A workstation without a computer is a desk. Named as the contributions
   * they must come from rather than as item ids, so any computer satisfies it.
   */
  dependsOn?: (keyof ItemGives)[];
  /** Drawn in this colour family. The renderer owns the actual painting. */
  look:
    | 'desk' | 'chair' | 'table' | 'soft' | 'cabinet' | 'screen' | 'machine'
    | 'rack' | 'plant' | 'lamp' | 'plumbing' | 'counter' | 'board';
  /** Something people walk on rather than round. */
  flat?: boolean;
  /** Only worth having in these kinds of business. Empty means anywhere. */
  suits?: BusinessCategory[];
}

