export const ITEM_BY_ID = new Map(ITEMS.map((def) => [def.id, def]));

export function item(id: string): ItemDef | undefined {
  return ITEM_BY_ID.get(id);
}

export function itemOrThrow(id: string): ItemDef {
  const found = ITEM_BY_ID.get(id);
  if (!found) throw new Error(`Unknown item: ${id}`);
  return found;
}

