import type { ItemDef } from '../data/buildingItems';
import type { PlacedItem } from '../sim/layout';
import { alpha, shade } from './sprites';
import { box, cylinder, faces, fillTile, glow, highlight, panel, project, shadow } from './iso';

/**
 * The things in a building, drawn as the things they are.
 *
 * This file is the answer to the complaint that a shop was a grid of coloured
 * rectangles. A shelf has bays with stock on them and empties as the stock
 * runs out; a fridge has a glass front and a cold light inside; a till has a
 * belt, a screen and a card reader; an oven has rings that glow when the
 * kitchen is working. None of it is decoration bolted on afterwards — every one
 * of these objects already had a job in the simulation, and this is that job
 * made visible.
 *
 * Each painter draws in tile space with the floor at z = 0, using only the
 * primitives in ./iso, so everything shares one light and one scale. Where an
 * object's state matters — worn out, unmanned, unstocked, in use — the painter
 * takes it and shows it, because a screen that looks the same whatever is
 * happening is the thing this replaces.
 */

export interface Paint {
  ctx: CanvasRenderingContext2D;
  /** Footprint in tiles, already rotated. */
  x: number;
  y: number;
  w: number;
  h: number;
  def: ItemDef;
  placed: PlacedItem;
  /** 0..1 — below about 0.6 things visibly stop working properly. */
  condition: number;
  /** Whether somebody is assigned to it and standing there. */
  manned: boolean;
  /** Whether it is doing its job this second. */
  busy: boolean;
  /** 0..1 of how full it is, for anything that holds stock. */
  stocked: number;
  /** Seconds, for anything that moves or blinks. */
  time: number;
  /** Highlighted because the player is pointing at it or has selected it. */
  focus: boolean;
}

// -------------------------------------------------------------- the palette

/**
 * One palette for the whole interior.
 *
 * Materials rather than item colours: a stainless oven and a stainless prep
 * bench are the same steel, and a pine shelf and a pine bench are the same
 * timber. That is what stops forty separately drawn objects looking like forty
 * different games.
 */
const M = {
  steel: '#9aa6b8',
  darkSteel: '#5a6577',
  timber: '#b0824e',
  paleTimber: '#c9a16a',
  laminate: '#e2e6ec',
  carcass: '#7d8798',
  black: '#2a3040',
  screen: '#1b2536',
  glass: '#bcd8e8',
  cold: '#8fd4e8',
  fabric: '#5d6b86',
  warmFabric: '#8c6f63',
  leaf: '#3f9a63',
  pot: '#8d5a45',
  paper: '#f0f2f6',
  brass: '#d7b46a',
  accent: '#2f7bff',
  hot: '#ff7a3d',
} as const;

/** Stock, food and product colours, so a shelf is not one flat slab. */
const GOODS = ['#d4634b', '#4f97d8', '#e0b23f', '#63b169', '#b478c8', '#e08a4b', '#7fbfd6'];

/**
 * The object inside its footprint.
 *
 * A four-cover table is allotted two tiles by two in the layout, because that
 * is the floor it takes up once people can get round it — but the table itself
 * is the middle of that, and drawing it edge to edge turns a restaurant into a
 * row of slabs with no gangway. So anything that occupies more floor than it is
 * made of gets pulled in, and the space it leaves is the space people walk in.
 */
function inner(p: Paint, margin: number): { x: number; y: number; w: number; h: number } {
  const mx = Math.min(margin, (p.w - 0.5) / 2);
  const my = Math.min(margin, (p.h - 0.5) / 2);
  return { x: p.x + mx, y: p.y + my, w: p.w - mx * 2, h: p.h - my * 2 };
}

// ------------------------------------------------------------------- entry

export function paintItem(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  shadow(ctx, x, y, w, h, p.def.flat ? 0.1 : 0.26);

  switch (p.def.id) {
    case 'shelving': return shelving(p);
    case 'racking': return racking(p);
    case 'fridge': return fridge(p);
    case 'coldroom': return coldroom(p);
    case 'till': return till(p);
    case 'till-self': return selfCheckout(p);
    case 'display-stand': return displayStand(p);
    case 'security-gate': return securityGate(p);
    case 'cooker': return cooker(p);
    case 'combi-oven': return combiOven(p);
    case 'prep-station': return prepStation(p);
    case 'dining-table': return diningTable(p);
    case 'booth': return booth(p);
    case 'small-table': return cafeTable(p);
    case 'meeting-table': return meetingTable(p);
    case 'desk':
    case 'desk-corner': return desk(p);
    case 'exec-desk': return execDesk(p);
    case 'reception-desk': return reception(p);
    case 'computer': return computer(p);
    case 'laptop': return laptop(p);
    case 'printer': return printer(p);
    case 'server-rack': return serverRack(p);
    case 'server-hall': return serverHall(p);
    case 'workbench':
    case 'workshop-bench': return workbench(p);
    case 'machine': return machine(p);
    case 'bookshelf': return bookshelf(p);
    case 'filing-cabinet': return filing(p);
    case 'chair': return loneChair(p);
    case 'sofa': return sofa(p);
    case 'plant': return plant(p, 0.9);
    case 'big-plant': return plant(p, 1.7);
    case 'rug': return rug(p);
    case 'artwork': return artwork(p);
    case 'ceiling-light': return ceilingLight(p);
    case 'floor-lamp': return floorLamp(p);
    case 'water-cooler': return waterCooler(p);
    case 'coffee-machine': return coffeeMachine(p);
    case 'kitchen': return kitchenette(p);
    case 'toilets': return toilets(p);
    case 'lockers': return lockers(p);
    case 'whiteboard': return whiteboard(p);
    case 'training-station': return trainingStation(p);
    case 'phone-station': return phoneStation(p);
    case 'pallets': return pallets(p);
    case 'loading-bay': return loadingBay(p);
    default: return generic(p);
  }
}

// ------------------------------------------------------------------ retail

/** A gondola unit: bays, shelves, and the stock that is actually on them. */
function shelving(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const long = w >= h;
  box(ctx, x, y, w, h, 0, 0.25, M.carcass, 0.12);
  box(ctx, x, y, w, h, 0.25, 2.5, shade(M.carcass, -0.06), 0.18);

  // Three shelves of goods, thinning out as the stock does.
  const bays = Math.max(2, Math.round((long ? w : h) * 2));
  for (let level = 0; level < 3; level += 1) {
    const z = 0.55 + level * 0.65;
    for (let bay = 0; bay < bays; bay += 1) {
      const t = (bay + 0.5) / bays;
      // The top shelf empties first, which is how a shop actually looks when
      // it is running out.
      const full = p.stocked * 1.2 - level * 0.18;
      if (full <= (bay % 3) * 0.2) continue;
      const gx = long ? x + 0.2 + t * (w - 0.4) : x + w / 2;
      const gy = long ? y + h / 2 : y + 0.2 + t * (h - 0.4);
      box(
        ctx,
        gx - 0.14, gy - 0.14, 0.28, 0.28,
        z, z + 0.42,
        GOODS[(bay + level * 3 + p.placed.x) % GOODS.length],
        0.02,
      );
    }
    highlight(ctx, x + 0.18, y + 0.18, w - 0.36, h - 0.36, z + 0.5, alpha('#ffffff', 0.12));
  }
  wearMarks(p, 2.5);
}

/** Warehouse racking: uprights, beams, pallets up high. */
function racking(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const uprights = Math.max(2, Math.round(w) + 1);
  for (let i = 0; i < uprights; i += 1) {
    const ux = x + (i / (uprights - 1)) * (w - 0.2) + 0.1;
    box(ctx, ux - 0.06, y + 0.1, 0.12, 0.12, 0, 4, M.darkSteel, 0);
    box(ctx, ux - 0.06, y + h - 0.22, 0.12, 0.12, 0, 4, M.darkSteel, 0);
  }
  for (const z of [1.4, 2.8]) {
    box(ctx, x + 0.08, y + 0.1, w - 0.16, 0.1, z, z + 0.14, shade(M.steel, -0.1), 0);
    box(ctx, x + 0.08, y + h - 0.22, w - 0.16, 0.1, z, z + 0.14, shade(M.steel, -0.1), 0);
  }
  // Pallets on the beams, as many as there is stock for.
  const slots = Math.max(1, Math.round(w));
  for (let level = 0; level < 2; level += 1) {
    for (let slot = 0; slot < slots; slot += 1) {
      if ((slot + level) / (slots * 2) > p.stocked) continue;
      const px = x + 0.15 + slot * ((w - 0.3) / slots);
      const pz = level === 0 ? 1.54 : 2.94;
      box(ctx, px, y + 0.2, (w - 0.3) / slots - 0.1, h - 0.4, pz, pz + 0.12, M.paleTimber, 0.02);
      box(ctx, px + 0.05, y + 0.28, (w - 0.3) / slots - 0.2, h - 0.56, pz + 0.12, pz + 0.85, GOODS[(slot + level) % GOODS.length], 0.02);
    }
  }
}

/** A glass-fronted chiller, lit from inside. */
function fridge(p: Paint): void {
  const { ctx } = p;
  const { x, y, w, h } = inner(p, 0.18);
  box(ctx, x, y, w, h, 0, 2.6, M.steel, 0.1);
  // The glass front, facing the viewer.
  const frontY = y + h - 0.1;
  panel(ctx, x + 0.12, frontY, w - 0.24, false, 0.35, 2.35, alpha(M.cold, 0.42));
  panel(ctx, x + 0.12, frontY, w - 0.24, false, 0.35, 2.35, alpha('#ffffff', 0.08));
  for (let level = 0; level < 3; level += 1) {
    const z = 0.6 + level * 0.6;
    panel(ctx, x + 0.14, frontY - 0.01, w - 0.28, false, z, z + 0.06, alpha('#ffffff', 0.25));
    const tins = Math.max(2, Math.round(w * 2));
    for (let i = 0; i < tins; i += 1) {
      if ((i + level) / (tins * 3) > p.stocked) continue;
      const gx = x + 0.2 + ((i + 0.5) / tins) * (w - 0.4);
      box(ctx, gx - 0.08, y + h / 2, 0.16, 0.16, z + 0.06, z + 0.42, GOODS[(i + level) % GOODS.length], 0.01);
    }
  }
  glow(ctx, x + w / 2, y + h / 2, 1.6, 42, M.cold);
  wearMarks(p, 2.6);
}

function coldroom(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 3.2, shade(M.steel, 0.05), 0.05);
  // A heavy door with a lever handle on the front face.
  panel(ctx, x + w * 0.25, y + h - 0.05, w * 0.5, false, 0.1, 2.4, shade(M.steel, -0.16));
  const handle = project(x + w * 0.68, y + h - 0.05, 1.2);
  ctx.fillStyle = M.darkSteel;
  ctx.fillRect(handle.x - 2, handle.y - 8, 4, 16);
  glow(ctx, x + w / 2, y + h - 0.2, 2.5, 26, M.cold);
}

/** A checkout: belt, till screen, card reader, and a light that says if it is open. */
function till(p: Paint): void {
  const { ctx } = p;
  // A checkout lane is a counter with room to stand at it, so the counter
  // itself takes the back of the bay and the front is where the queue goes.
  const t = inner(p, 0.22);
  const x = t.x;
  const y = t.y;
  const w = t.w;
  const h = Math.min(t.h, 1.1);
  box(ctx, x, y, w, h, 0, 0.95, M.laminate, 0.08);
  // The belt runs along the long side.
  const long = w >= h;
  if (long) box(ctx, x + 0.15, y + h * 0.22, w - 0.3, h * 0.3, 0.95, 1.02, shade(M.black, 0.1), 0);
  else box(ctx, x + w * 0.22, y + 0.15, w * 0.3, h - 0.3, 0.95, 1.02, shade(M.black, 0.1), 0);

  // The till itself: a post with a screen on it, facing the operator.
  const sx = x + w * 0.72;
  const sy = y + h * 0.3;
  box(ctx, sx - 0.06, sy - 0.06, 0.12, 0.12, 0.95, 1.5, M.darkSteel, 0);
  panel(ctx, sx - 0.22, sy + 0.1, 0.44, false, 1.5, 1.95, p.manned ? M.screen : shade(M.screen, -0.1));
  if (p.manned) {
    panel(ctx, sx - 0.19, sy + 0.09, 0.38, false, 1.58, 1.88, alpha(M.accent, p.busy ? 0.75 : 0.4));
    glow(ctx, sx, sy + 0.1, 1.75, 26, M.accent);
  }
  // Card reader on the customer side.
  box(ctx, x + w * 0.3, y + h * 0.75, 0.16, 0.14, 0.95, 1.18, M.black, 0);

  // The lane light: green when somebody is on it, dark when nobody is.
  const lamp = project(x + w * 0.5, y + h * 0.5, 2.9);
  ctx.fillStyle = p.manned ? '#2fbf7e' : '#5a6577';
  ctx.beginPath();
  ctx.arc(lamp.x, lamp.y, 3.2, 0, Math.PI * 2);
  ctx.fill();
  if (p.manned) glow(ctx, x + w * 0.5, y + h * 0.5, 2.9, 20, '#2fbf7e');
  wearMarks(p, 1);
}

function selfCheckout(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x + 0.1, y + 0.1, w - 0.2, h - 0.2, 0, 0.8, M.laminate, 0.05);
  box(ctx, x + w * 0.35, y + h * 0.35, 0.3, 0.3, 0.8, 1.7, M.darkSteel, 0);
  panel(ctx, x + w * 0.2, y + h * 0.7, w * 0.6, false, 1.2, 1.75, M.screen);
  panel(ctx, x + w * 0.24, y + h * 0.69, w * 0.52, false, 1.26, 1.69, alpha(M.accent, 0.5));
  glow(ctx, x + w / 2, y + h * 0.7, 1.5, 22, M.accent);
}

/** A promotional stack near the door. */
function displayStand(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 0.35, M.paleTimber, 0.12);
  const layers = 3;
  for (let i = 0; i < layers; i += 1) {
    const inset = 0.16 + i * 0.09;
    const z = 0.35 + i * 0.32;
    if (i / layers > p.stocked + 0.15) break;
    box(ctx, x + inset, y + inset, w - inset * 2, h - inset * 2, z, z + 0.3, GOODS[(i + p.placed.y) % GOODS.length], 0.02);
  }
}

function securityGate(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  for (const side of [0.12, 0.88]) {
    box(ctx, x + w * side - 0.07, y + h * 0.4, 0.14, h * 0.25, 0, 2.1, shade(M.laminate, -0.05), 0);
  }
}

// ------------------------------------------------------------------ kitchen

/** A range: hob rings on top that glow when the kitchen is working. */
function cooker(p: Paint): void {
  const { ctx } = p;
  const t = inner(p, 0.3);
  const x = t.x;
  const y = t.y;
  const w = t.w;
  const h = t.h;
  // The extraction canopy over it, which is what makes a kitchen read as a
  // kitchen from across the room. Kept to the size of the range and in bright
  // steel: drawn any larger or any darker it stops looking like a canopy and
  // starts looking like a slab hanging in mid-air.
  box(ctx, x + 0.04, y + 0.04, w - 0.08, h - 0.08, 2.35, 2.55, shade(M.steel, 0.1), 0.04);
  box(ctx, x + w / 2 - 0.05, y + h / 2 - 0.05, 0.1, 0.1, 2.55, 3.3, shade(M.steel, -0.05), 0);
  box(ctx, x, y, w, h, 0, 1.05, M.steel, 0.08);
  box(ctx, x + 0.1, y + 0.1, w - 0.2, h - 0.2, 1.05, 1.12, shade(M.darkSteel, -0.1), 0);
  // Four rings.
  for (let i = 0; i < 4; i += 1) {
    const rx = x + (i % 2 === 0 ? w * 0.32 : w * 0.68);
    const ry = y + (i < 2 ? h * 0.34 : h * 0.66);
    const ring = project(rx, ry, 1.13);
    ctx.fillStyle = p.busy ? M.hot : shade(M.black, 0.08);
    ctx.beginPath();
    ctx.ellipse(ring.x, ring.y, 6, 3, 0, 0, Math.PI * 2);
    ctx.fill();
    if (p.busy) glow(ctx, rx, ry, 1.13, 14, M.hot);
  }
  // The oven door below, with its handle and window.
  panel(ctx, x + 0.16, y + h - 0.08, w - 0.32, false, 0.18, 0.86, shade(M.darkSteel, 0.04));
  panel(ctx, x + 0.26, y + h - 0.09, w - 0.52, false, 0.3, 0.7, alpha(p.busy ? M.hot : M.black, 0.6));
  wearMarks(p, 1.05);
}

function combiOven(p: Paint): void {
  const { ctx } = p;
  const { x, y, w, h } = inner(p, 0.26);
  box(ctx, x, y, w, h, 0, 2.4, M.steel, 0.08);
  for (const z of [0.3, 1.1, 1.9]) {
    panel(ctx, x + 0.16, y + h - 0.08, w - 0.32, false, z, z + 0.6, shade(M.darkSteel, 0.02));
    panel(ctx, x + 0.26, y + h - 0.09, w - 0.52, false, z + 0.1, z + 0.5, alpha(p.busy ? M.hot : M.black, 0.55));
  }
  if (p.busy) glow(ctx, x + w / 2, y + h - 0.2, 1.2, 30, M.hot);
  wearMarks(p, 2.4);
}

/** Stainless prep bench with tubs and a shelf under it. */
function prepStation(p: Paint): void {
  const { ctx } = p;
  const t = inner(p, 0.2);
  const { x, y, w, h } = t;
  legs({ ...p, ...t }, 0.95, M.darkSteel);
  box(ctx, x, y, w, h, 0.95, 1.05, M.steel, 0.06);
  box(ctx, x + 0.12, y + 0.12, w - 0.24, h - 0.24, 0.42, 0.5, shade(M.steel, -0.16), 0);
  const tubs = Math.max(2, Math.round(w * 1.4));
  for (let i = 0; i < tubs; i += 1) {
    const tx = x + 0.2 + ((i + 0.5) / tubs) * (w - 0.4);
    box(ctx, tx - 0.12, y + h * 0.3, 0.24, 0.24, 1.05, 1.26, i % 2 ? shade(M.steel, -0.2) : GOODS[i % GOODS.length], 0.01);
  }
}

/** A table with chairs round it, and plates on it when somebody is eating. */
function diningTable(p: Paint): void {
  const { ctx } = p;
  const t = inner(p, 0.42);
  const top = { ...p, ...t };
  legs(top, 0.8, M.timber);
  box(ctx, t.x, t.y, t.w, t.h, 0.8, 0.92, M.paleTimber, 0.05);
  chairsAround(p, 0.8, 4);
  const { x, y, w, h } = t;
  if (p.busy) {
    for (const [dx, dy] of [[0.32, 0.5], [0.68, 0.5]] as const) {
      const plate = project(x + w * dx, y + h * dy, 0.94);
      ctx.fillStyle = M.paper;
      ctx.beginPath();
      ctx.ellipse(plate.x, plate.y, 7, 3.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = GOODS[2];
      ctx.beginPath();
      ctx.ellipse(plate.x, plate.y, 3.4, 1.7, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function booth(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const long = w >= h;
  // Two high-backed benches with the table between them.
  if (long) {
    box(ctx, x, y, w, h * 0.3, 0, 1.6, M.warmFabric, 0.06);
    box(ctx, x, y + h * 0.7, w, h * 0.3, 0, 1.6, M.warmFabric, 0.06);
    legs({ ...p, x: x + w * 0.2, w: w * 0.6, y: y + h * 0.32, h: h * 0.36 }, 0.78, M.darkSteel);
    box(ctx, x + w * 0.12, y + h * 0.32, w * 0.76, h * 0.36, 0.78, 0.9, M.paleTimber, 0.02);
  } else {
    box(ctx, x, y, w * 0.3, h, 0, 1.6, M.warmFabric, 0.06);
    box(ctx, x + w * 0.7, y, w * 0.3, h, 0, 1.6, M.warmFabric, 0.06);
    box(ctx, x + w * 0.32, y + h * 0.12, w * 0.36, h * 0.76, 0.78, 0.9, M.paleTimber, 0.02);
  }
}

function cafeTable(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const cx = x + w / 2;
  const cy = y + h / 2;
  cylinder(ctx, cx, cy, 0.07, 0, 0.74, M.darkSteel);
  cylinder(ctx, cx, cy, Math.min(w, h) * 0.38, 0.74, 0.82, M.paleTimber);
  chairsAround(p, 0.74, 2);
}

function meetingTable(p: Paint): void {
  const { ctx } = p;
  const t = inner(p, 0.34);
  legs({ ...p, ...t }, 0.78, M.darkSteel);
  box(ctx, t.x, t.y, t.w, t.h, 0.78, 0.9, M.laminate, 0.04);
  chairsAround(p, 0.78, 6);
  const { x, y, w, h } = t;
  if (p.busy) {
    // Papers and cups, because a meeting room in use looks used.
    for (let i = 0; i < 3; i += 1) {
      const px = x + w * (0.25 + i * 0.25);
      box(ctx, px - 0.1, y + h * 0.42, 0.2, 0.14, 0.9, 0.91, M.paper, 0);
    }
  }
}

// ------------------------------------------------------------------- office

function desk(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  legs(p, 0.74, M.darkSteel);
  box(ctx, x, y, w, h, 0.74, 0.84, M.laminate, 0.05);
  // A drawer pedestal under one end.
  box(ctx, x + 0.1, y + 0.16, Math.min(0.55, w * 0.4), h - 0.32, 0, 0.7, shade(M.carcass, 0.05), 0.02);
  deskKit(p, 0.84);
  chairsAround(p, 0.74, 1);
}

function execDesk(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x + 0.08, y + 0.1, w - 0.16, h - 0.2, 0, 0.72, M.timber, 0.04);
  box(ctx, x, y, w, h, 0.72, 0.86, shade(M.timber, 0.12), 0.03);
  deskKit(p, 0.86);
  chairsAround(p, 0.72, 1);
}

function reception(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  // A low working top with a raised counter facing the room.
  box(ctx, x, y, w, h, 0, 0.78, M.laminate, 0.06);
  box(ctx, x, y + h * 0.62, w, h * 0.38, 0, 1.18, shade(M.laminate, -0.12), 0.05);
  highlight(ctx, x + 0.06, y + h * 0.62, w - 0.12, 0, 1.18, alpha('#ffffff', 0.3));
  deskKit(p, 0.78, 0.35);
  if (p.manned) glow(ctx, x + w / 2, y + h * 0.3, 1.1, 24, M.accent);
}

/** Whatever is standing on a desk: a monitor, a keyboard, a mug. */
function deskKit(p: Paint, top: number, atX = 0.6): void {
  const { ctx, x, y, w, h } = p;
  const mx = x + w * atX;
  const my = y + h * 0.36;
  box(ctx, mx - 0.05, my - 0.04, 0.1, 0.08, top, top + 0.12, M.darkSteel, 0);
  panel(ctx, mx - 0.28, my + 0.06, 0.56, false, top + 0.12, top + 0.62, M.screen);
  panel(ctx, mx - 0.25, my + 0.05, 0.5, false, top + 0.16, top + 0.58, alpha(p.manned ? M.accent : '#39506e', p.manned ? 0.55 : 0.25));
  if (p.manned) glow(ctx, mx, my + 0.06, top + 0.38, 24, M.accent);
  // Keyboard.
  box(ctx, mx - 0.2, y + h * 0.62, 0.4, 0.14, top, top + 0.03, shade(M.laminate, -0.18), 0);
}

function computer(p: Paint): void {
  // A computer placed on its own tile is a machine on a desk return.
  const { ctx, x, y, w, h } = p;
  box(ctx, x + w * 0.3, y + h * 0.3, w * 0.4, h * 0.4, 0, 0.62, M.black, 0.02);
  panel(ctx, x + w * 0.2, y + h * 0.72, w * 0.6, false, 0.62, 1.12, M.screen);
  panel(ctx, x + w * 0.24, y + h * 0.71, w * 0.52, false, 0.66, 1.08, alpha(M.accent, 0.5));
  glow(ctx, x + w / 2, y + h * 0.7, 0.9, 22, M.accent);
}

function laptop(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x + w * 0.25, y + h * 0.4, w * 0.5, h * 0.35, 0, 0.04, M.steel, 0.01);
  panel(ctx, x + w * 0.25, y + h * 0.4, w * 0.5, false, 0.04, 0.4, shade(M.steel, -0.1));
  panel(ctx, x + w * 0.28, y + h * 0.39, w * 0.44, false, 0.08, 0.36, alpha(M.accent, 0.45));
}

function printer(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 0.62, shade(M.laminate, -0.08), 0.12);
  box(ctx, x + 0.16, y + 0.16, w - 0.32, h - 0.32, 0.62, 0.72, M.carcass, 0);
  // Paper in the out tray.
  box(ctx, x + 0.2, y + h * 0.55, w - 0.4, h * 0.3, 0.6, 0.63, M.paper, 0);
  const light = project(x + w * 0.22, y + h * 0.3, 0.64);
  ctx.fillStyle = p.condition < 0.6 ? '#ef4657' : '#2fbf7e';
  ctx.fillRect(light.x - 1.5, light.y - 1.5, 3, 3);
}

function serverRack(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 3.4, M.black, 0.1);
  // Units with status lights, blinking on their own rhythm.
  for (let unit = 0; unit < 8; unit += 1) {
    const z = 0.25 + unit * 0.38;
    panel(ctx, x + 0.14, y + h - 0.08, w - 0.28, false, z, z + 0.3, shade(M.black, 0.12));
    for (let led = 0; led < 3; led += 1) {
      const lx = x + 0.24 + led * 0.14;
      const on = ((Math.floor(p.time * 2) + unit * 3 + led) % 5) !== 0;
      const q = project(lx, y + h - 0.09, z + 0.16);
      ctx.fillStyle = on ? (led === 0 ? '#2fbf7e' : '#38bdf8') : '#1d2740';
      ctx.fillRect(q.x - 1.2, q.y - 1.2, 2.4, 2.4);
    }
  }
  glow(ctx, x + w / 2, y + h - 0.2, 1.6, 30, '#38bdf8');
}

function serverHall(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const rows = Math.max(2, Math.round(w));
  for (let i = 0; i < rows; i += 1) {
    const rx = x + (i * w) / rows;
    serverRack({ ...p, ctx, x: rx, y, w: w / rows, h });
  }
}

// --------------------------------------------------------------- workshop

function workbench(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  legs(p, 0.8, M.darkSteel);
  box(ctx, x, y, w, h, 0.8, 0.94, M.timber, 0.05);
  // A vice at one end and tools scattered along it.
  box(ctx, x + w * 0.12, y + h * 0.3, 0.2, 0.2, 0.94, 1.14, M.darkSteel, 0.01);
  for (let i = 0; i < 4; i += 1) {
    const tx = x + w * (0.35 + i * 0.15);
    box(ctx, tx, y + h * (0.35 + (i % 2) * 0.3), 0.18, 0.06, 0.94, 0.98, i % 2 ? M.brass : M.steel, 0);
  }
  // A pegboard behind it with more tools.
  panel(ctx, x + 0.1, y + 0.08, w - 0.2, false, 0.94, 2.1, shade(M.timber, -0.22));
  for (let i = 0; i < 5; i += 1) {
    const q = project(x + 0.3 + i * ((w - 0.6) / 4), y + 0.07, 1.65);
    ctx.fillStyle = alpha(M.steel, 0.8);
    ctx.fillRect(q.x - 1.5, q.y - 6, 3, 12);
  }
  wearMarks(p, 0.94);
}

/** A production machine: hopper, body, output chute, and a wheel that turns. */
function machine(p: Paint): void {
  const { ctx } = p;
  const { x, y, w, h } = inner(p, 0.22);
  box(ctx, x, y, w, h, 0, 1.9, M.carcass, 0.08);
  box(ctx, x + w * 0.2, y + h * 0.2, w * 0.6, h * 0.6, 1.9, 2.5, shade(M.darkSteel, 0.06), 0);
  // Hopper narrowing into the body.
  box(ctx, x + w * 0.28, y + h * 0.26, w * 0.44, h * 0.48, 2.5, 2.9, M.steel, 0);
  // Control panel on the front.
  panel(ctx, x + w * 0.18, y + h - 0.06, w * 0.34, false, 0.9, 1.5, M.screen);
  const state = p.condition < 0.5 ? '#ef4657' : p.busy ? '#2fbf7e' : '#f59e0b';
  const light = project(x + w * 0.35, y + h - 0.07, 1.6);
  ctx.fillStyle = state;
  ctx.beginPath();
  ctx.arc(light.x, light.y, 3, 0, Math.PI * 2);
  ctx.fill();
  glow(ctx, x + w * 0.35, y + h - 0.07, 1.6, 18, state);

  // A flywheel on the side that turns while it is running.
  const centre = project(x + w - 0.08, y + h * 0.4, 1.2);
  ctx.save();
  ctx.translate(centre.x, centre.y);
  ctx.strokeStyle = M.darkSteel;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(0, 0, 9, 9 * 0.62, 0, 0, Math.PI * 2);
  ctx.stroke();
  const spin = p.busy ? p.time * 3 : 0;
  for (let spoke = 0; spoke < 3; spoke += 1) {
    const angle = spin + (spoke * Math.PI * 2) / 3;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(angle) * 9, Math.sin(angle) * 9 * 0.62);
    ctx.stroke();
  }
  ctx.restore();
  wearMarks(p, 2.9);
}

function pallets(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const stacks = Math.max(1, Math.round(w));
  for (let i = 0; i < stacks; i += 1) {
    const px = x + (i * w) / stacks + 0.08;
    const pw = w / stacks - 0.16;
    box(ctx, px, y + 0.1, pw, h - 0.2, 0, 0.16, M.paleTimber, 0.02);
    const height = 0.5 + ((i + p.placed.x) % 3) * 0.35;
    box(ctx, px + 0.05, y + 0.16, pw - 0.1, h - 0.32, 0.16, 0.16 + height, GOODS[(i + 1) % GOODS.length], 0.02);
    // Strapping.
    highlight(ctx, px + 0.05, y + 0.16, pw - 0.1, 0, 0.16 + height * 0.6, alpha(M.black, 0.35), 2);
  }
}

function loadingBay(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  // The apron, marked out on the floor.
  fillTile(ctx, x, y, w, h, alpha('#f59e0b', 0.1));
  ctx.save();
  ctx.strokeStyle = alpha('#f59e0b', 0.5);
  ctx.setLineDash([7, 6]);
  ctx.lineWidth = 2;
  const a = project(x + 0.1, y + 0.1);
  const b = project(x + w - 0.1, y + 0.1);
  const c = project(x + w - 0.1, y + h - 0.1);
  const d = project(x + 0.1, y + h - 0.1);
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo(c.x, c.y);
  ctx.lineTo(d.x, d.y);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
  // The dock itself: a raised lip and a roller door behind it.
  box(ctx, x, y, w, 0.3, 0, 0.45, M.carcass, 0.04);
  panel(ctx, x + 0.2, y + 0.02, w - 0.4, false, 0.45, 2.8, shade(M.steel, -0.08));
  for (let i = 0; i < 6; i += 1) {
    highlight(ctx, x + 0.2, y + 0.02, w - 0.4, 0, 0.6 + i * 0.36, alpha(M.black, 0.2));
  }
}

// -------------------------------------------------------------- facilities

function kitchenette(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 0.9, M.carcass, 0.06);
  box(ctx, x, y, w, h, 0.9, 1.0, M.laminate, 0.04);
  // A sink sunk into the top, and a tap behind it.
  const sink = project(x + w * 0.3, y + h * 0.5, 1.0);
  ctx.fillStyle = shade(M.steel, -0.18);
  ctx.beginPath();
  ctx.ellipse(sink.x, sink.y, 11, 5.5, 0, 0, Math.PI * 2);
  ctx.fill();
  box(ctx, x + w * 0.3, y + h * 0.28, 0.06, 0.06, 1.0, 1.32, M.steel, 0);
  // Wall cupboards.
  panel(ctx, x + 0.12, y + 0.06, w - 0.24, false, 1.9, 2.8, shade(M.carcass, 0.08));
  coffeeOn(p, x + w * 0.72, y + h * 0.45, 1.0);
}

function coffeeMachine(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x + 0.12, y + 0.12, w - 0.24, h - 0.24, 0, 0.55, shade(M.carcass, 0.04), 0.02);
  coffeeOn(p, x + w / 2, y + h / 2, 0.55);
  void ctx;
}

function coffeeOn(p: Paint, cx: number, cy: number, z: number): void {
  const { ctx } = p;
  box(ctx, cx - 0.16, cy - 0.14, 0.32, 0.28, z, z + 0.52, M.black, 0.01);
  const light = project(cx, cy + 0.14, z + 0.3);
  ctx.fillStyle = '#ef4657';
  ctx.fillRect(light.x - 1.5, light.y - 1, 3, 2);
  // A cup under the spout.
  cylinder(ctx, cx, cy + 0.2, 0.05, z, z + 0.12, M.paper);
}

function waterCooler(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const cx = x + w / 2;
  const cy = y + h / 2;
  box(ctx, cx - 0.18, cy - 0.18, 0.36, 0.36, 0, 1.0, M.laminate, 0.02);
  cylinder(ctx, cx, cy, 0.16, 1.0, 1.55, alpha(M.cold, 0.75));
  glow(ctx, cx, cy, 1.3, 16, M.cold);
}

function toilets(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  // Cubicle walls with a gap at the bottom, a door, and a sign.
  box(ctx, x, y, w, h, 0, 0.05, shade(M.laminate, -0.06), 0.02);
  panel(ctx, x + 0.06, y + 0.06, w - 0.12, false, 0.2, 2.1, shade(M.laminate, -0.1));
  panel(ctx, x + 0.06, y + 0.06, h - 0.12, true, 0.2, 2.1, shade(M.laminate, -0.16));
  panel(ctx, x + w - 0.06, y + 0.06, h - 0.12, true, 0.2, 2.1, shade(M.laminate, -0.2));
  const sign = project(x + w * 0.5, y + 0.05, 1.6);
  ctx.fillStyle = alpha(M.accent, 0.8);
  ctx.beginPath();
  ctx.arc(sign.x, sign.y, 3.5, 0, Math.PI * 2);
  ctx.fill();
}

function lockers(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 2.1, shade(M.fabric, 0.06), 0.08);
  const doors = Math.max(2, Math.round(w * 2));
  for (let i = 0; i < doors; i += 1) {
    const dx = x + 0.12 + (i * (w - 0.24)) / doors;
    const dw = (w - 0.24) / doors - 0.04;
    panel(ctx, dx, y + h - 0.08, dw, false, 0.1, 1.0, shade(M.fabric, -0.04));
    panel(ctx, dx, y + h - 0.08, dw, false, 1.05, 1.95, shade(M.fabric, -0.08));
    const handle = project(dx + dw * 0.8, y + h - 0.09, 1.5);
    ctx.fillStyle = M.steel;
    ctx.fillRect(handle.x - 1, handle.y - 3, 2, 6);
  }
}

function trainingStation(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  legs(p, 0.74, M.darkSteel);
  box(ctx, x, y, w, h, 0.74, 0.84, M.laminate, 0.05);
  deskKit(p, 0.84, 0.35);
  deskKit(p, 0.84, 0.75);
  chairsAround(p, 0.74, 2);
}

function phoneStation(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  legs(p, 0.74, M.darkSteel);
  box(ctx, x, y, w, h, 0.74, 0.84, M.laminate, 0.05);
  // Acoustic screens round three sides, which is what a call desk looks like.
  panel(ctx, x + 0.04, y + 0.06, w - 0.08, false, 0.84, 1.5, shade(M.fabric, 0.05));
  panel(ctx, x + 0.04, y + 0.06, h - 0.12, true, 0.84, 1.5, shade(M.fabric, -0.02));
  deskKit(p, 0.84, 0.55);
  if (p.busy) glow(ctx, x + w / 2, y + h / 2, 1.3, 22, '#2fbf7e');
}

function whiteboard(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  panel(ctx, x + 0.06, y + h * 0.5, w - 0.12, false, 0.7, 2.2, M.paper);
  panel(ctx, x + 0.06, y + h * 0.5, w - 0.12, false, 0.64, 0.7, M.steel);
  // Something written on it, as marks rather than letters.
  ctx.strokeStyle = alpha(M.accent, 0.5);
  ctx.lineWidth = 1.5;
  for (let i = 0; i < 3; i += 1) {
    const a = project(x + 0.2, y + h * 0.49, 1.9 - i * 0.3);
    const b = project(x + w * (0.5 + i * 0.12), y + h * 0.49, 1.9 - i * 0.3);
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  }
}

// ------------------------------------------------------------------ comfort

function bookshelf(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 2.2, M.timber, 0.1);
  for (let level = 0; level < 4; level += 1) {
    const z = 0.2 + level * 0.5;
    panel(ctx, x + 0.14, y + h - 0.1, w - 0.28, false, z, z + 0.04, shade(M.timber, -0.2));
    const books = Math.max(4, Math.round(w * 5));
    for (let i = 0; i < books; i += 1) {
      const bx = x + 0.18 + (i * (w - 0.36)) / books;
      if ((i * 7 + level * 3) % 11 === 0) continue;
      panel(ctx, bx, y + h - 0.12, (w - 0.36) / books - 0.01, false, z + 0.04, z + 0.04 + 0.28 + ((i % 3) * 0.05), GOODS[(i + level) % GOODS.length]);
    }
  }
}

function filing(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  box(ctx, x, y, w, h, 0, 1.3, M.carcass, 0.1);
  for (let drawer = 0; drawer < 3; drawer += 1) {
    const z = 0.12 + drawer * 0.4;
    panel(ctx, x + 0.14, y + h - 0.09, w - 0.28, false, z, z + 0.34, shade(M.carcass, 0.06));
    const handle = project(x + w / 2, y + h - 0.1, z + 0.17);
    ctx.fillStyle = M.steel;
    ctx.fillRect(handle.x - 6, handle.y - 1, 12, 2);
  }
}

function loneChair(p: Paint): void {
  chair(p, p.x + p.w / 2, p.y + p.h / 2, 0);
}

function sofa(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const long = w >= h;
  box(ctx, x, y, w, h, 0, 0.5, M.fabric, 0.08);
  // Back and arms.
  if (long) {
    box(ctx, x, y, w, h * 0.32, 0.5, 1.15, shade(M.fabric, 0.06), 0.06);
    box(ctx, x, y, w * 0.12, h, 0.5, 0.85, shade(M.fabric, -0.04), 0.04);
    box(ctx, x + w * 0.88, y, w * 0.12, h, 0.5, 0.85, shade(M.fabric, -0.04), 0.04);
  } else {
    box(ctx, x, y, w * 0.32, h, 0.5, 1.15, shade(M.fabric, 0.06), 0.06);
    box(ctx, x, y, w, h * 0.12, 0.5, 0.85, shade(M.fabric, -0.04), 0.04);
  }
  // Cushions.
  const seats = Math.max(2, Math.round(Math.max(w, h)));
  for (let i = 0; i < seats; i += 1) {
    const cx = long ? x + 0.18 + (i * (w - 0.36)) / seats : x + w * 0.42;
    const cy = long ? y + h * 0.5 : y + 0.18 + (i * (h - 0.36)) / seats;
    box(ctx, cx, cy, long ? (w - 0.36) / seats - 0.06 : w * 0.5, long ? h * 0.42 : (h - 0.36) / seats - 0.06, 0.5, 0.6, shade(M.fabric, 0.12), 0.02);
  }
}

function plant(p: Paint, size: number): void {
  const { ctx, x, y, w, h } = p;
  const cx = x + w / 2;
  const cy = y + h / 2;
  cylinder(ctx, cx, cy, 0.17 * size, 0, 0.35 * size, M.pot);
  // Foliage as overlapping blobs, which reads as a plant rather than a cone.
  const leaves = 7;
  for (let i = 0; i < leaves; i += 1) {
    const angle = (i / leaves) * Math.PI * 2;
    const spread = 0.16 * size;
    const lift = 0.35 * size + (i % 3) * 0.22 * size;
    const q = project(cx + Math.cos(angle) * spread, cy + Math.sin(angle) * spread * 0.7, lift);
    ctx.fillStyle = i % 2 ? M.leaf : shade(M.leaf, -0.12);
    ctx.beginPath();
    ctx.ellipse(q.x, q.y, 9 * size, 6 * size, angle, 0, Math.PI * 2);
    ctx.fill();
  }
}

function rug(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  fillTile(ctx, x + 0.06, y + 0.06, w - 0.12, h - 0.12, shade(M.warmFabric, 0.06));
  fillTile(ctx, x + 0.2, y + 0.2, w - 0.4, h - 0.4, shade(M.warmFabric, -0.08));
}

function artwork(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  panel(ctx, x + 0.12, y + h * 0.5, w - 0.24, false, 1.1, 2.0, M.timber);
  panel(ctx, x + 0.2, y + h * 0.49, w - 0.4, false, 1.18, 1.92, GOODS[(p.placed.x + p.placed.y) % GOODS.length]);
}

function ceilingLight(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const cx = x + w / 2;
  const cy = y + h / 2;
  // The fitting hangs; the light itself is a pool on the floor beneath it.
  box(ctx, cx - 0.3, cy - 0.1, 0.6, 0.2, 3.5, 3.62, M.laminate, 0);
  glow(ctx, cx, cy, 3.4, 40, '#ffe9b8');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  fillTile(ctx, x - 0.9, y - 0.9, w + 1.8, h + 1.8, alpha('#ffe6ad', 0.07));
  ctx.restore();
}

function floorLamp(p: Paint): void {
  const { ctx, x, y, w, h } = p;
  const cx = x + w / 2;
  const cy = y + h / 2;
  cylinder(ctx, cx, cy, 0.14, 0, 0.06, M.darkSteel);
  box(ctx, cx - 0.025, cy - 0.025, 0.05, 0.05, 0.06, 1.7, M.darkSteel, 0);
  cylinder(ctx, cx, cy, 0.17, 1.7, 2.05, alpha('#ffe9b8', 0.8));
  glow(ctx, cx, cy, 1.9, 34, '#ffe9b8');
}

// ---------------------------------------------------------------- fallback

/**
 * Anything without its own painter.
 *
 * Still built from the same materials and the same light rather than being a
 * coloured rectangle, and it takes its shape from what the thing gives — a
 * storage item is a tall carcass, a seat is low and soft, a screen glows.
 */
function generic(p: Paint): void {
  const { ctx, x, y, w, h, def } = p;
  const material =
    def.look === 'machine' || def.look === 'counter' ? M.steel
      : def.look === 'rack' ? M.carcass
        : def.look === 'soft' ? M.fabric
          : def.look === 'screen' ? M.black
            : def.look === 'plant' ? M.leaf
              : def.look === 'table' || def.look === 'desk' ? M.laminate
                : M.timber;
  const tall = (def.gives.storage ?? 0) > 0 ? 2.1 : def.look === 'soft' ? 0.85 : 1.0;
  box(ctx, x, y, w, h, 0, tall, material, 0.1);
  if (def.look === 'screen') {
    panel(ctx, x + 0.16, y + h - 0.08, w - 0.32, false, tall * 0.4, tall * 0.9, alpha(M.accent, 0.45));
  }
  wearMarks(p, tall);
}

// --------------------------------------------------------------- the pieces

/** Four legs under a top. */
function legs(p: Paint, top: number, colour: string): void {
  const { ctx, x, y, w, h } = p;
  const inset = 0.16;
  for (const [lx, ly] of [
    [x + inset, y + inset],
    [x + w - inset - 0.08, y + inset],
    [x + inset, y + h - inset - 0.08],
    [x + w - inset - 0.08, y + h - inset - 0.08],
  ] as const) {
    box(ctx, lx, ly, 0.08, 0.08, 0, top, colour, 0);
  }
}

/** One chair, facing the middle of whatever it is pulled up to. */
function chair(p: Paint, cx: number, cy: number, facing: number): void {
  const { ctx } = p;
  box(ctx, cx - 0.2, cy - 0.2, 0.4, 0.4, 0.38, 0.48, shade(M.fabric, 0.08), 0.04);
  for (const [lx, ly] of [
    [-0.15, -0.15], [0.09, -0.15], [-0.15, 0.09], [0.09, 0.09],
  ] as const) {
    box(ctx, cx + lx, cy + ly, 0.06, 0.06, 0, 0.38, M.darkSteel, 0);
  }
  // The back, on the side away from the table.
  const bx = cx + Math.cos(facing) * 0.18;
  const by = cy + Math.sin(facing) * 0.18;
  box(ctx, bx - 0.19, by - 0.05, 0.38, 0.08, 0.48, 1.05, shade(M.fabric, 0.02), 0.02);
}

/** Chairs pulled up to a table, as many as it seats. */
function chairsAround(p: Paint, top: number, count = 4): void {
  const { x, y, w, h } = p;
  const spots: { x: number; y: number; facing: number }[] = [];
  const long = w >= h;
  const perSide = Math.max(1, Math.ceil(count / 2));
  // Tucked just inside the footprint. A chair drawn outside it sits in the
  // gangway and, worse, on top of whatever is in the next bay along.
  const edge = 0.28;
  for (let i = 0; i < perSide; i += 1) {
    const t = (i + 0.5) / perSide;
    if (long) {
      spots.push({ x: x + t * w, y: y + edge, facing: -Math.PI / 2 });
      spots.push({ x: x + t * w, y: y + h - edge, facing: Math.PI / 2 });
    } else {
      spots.push({ x: x + edge, y: y + t * h, facing: Math.PI });
      spots.push({ x: x + w - edge, y: y + t * h, facing: 0 });
    }
  }
  for (const spot of spots.slice(0, count)) chair(p, spot.x, spot.y, spot.facing);
  void top;
}

/**
 * What being worn out looks like.
 *
 * Not a number floating over the object: scuffs and, past the point where the
 * simulation says it has stopped doing its whole job, a warning strip. A player
 * should be able to walk round their own premises and see what needs money
 * spent on it.
 */
function wearMarks(p: Paint, top: number): void {
  if (p.condition > 0.75) return;
  const { ctx, x, y, w, h } = p;
  ctx.save();
  ctx.globalAlpha = (0.75 - p.condition) * 1.1;
  ctx.fillStyle = '#2a2016';
  for (let i = 0; i < 4; i += 1) {
    const q = project(x + 0.2 + ((i * 7) % 10) / 10 * (w - 0.4), y + h - 0.1, top * (0.2 + ((i * 3) % 7) / 10));
    ctx.fillRect(q.x, q.y, 3 + i, 1.5);
  }
  ctx.restore();

  if (p.condition < 0.6) {
    // Hazard tape: this one has stopped pulling its weight, and the capacity
    // maths already knows it.
    const tape = project(x + w / 2, y + h / 2, top + 0.25);
    ctx.save();
    ctx.translate(tape.x, tape.y);
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(7, 5);
    ctx.lineTo(-7, 5);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#1a1206';
    ctx.fillRect(-1, -3.5, 2, 5);
    ctx.fillRect(-1, 2.5, 2, 2);
    ctx.restore();
  }
}

export const MATERIALS = M;
export { faces as isoFaces };
