import type { GameState } from './state';
import { employeesOf, playerBusinesses } from './state';
import type { Business, Employee } from './types';
import { demandAt } from './demand';
import { isOffSick, perStaffHour } from './employees';
import { clamp, sum } from './util';

/**
 * Who is working, and when.
 *
 * Until now everybody on the payroll was simply present: hire five people and
 * five people were behind the counter from open to close, seven days a week,
 * for ever. That is a payroll, not a workforce. A workforce is a set of people
 * who are each available at different times, want different numbers of hours,
 * and have to be fitted against a business that is busier on a Friday evening
 * than a Tuesday morning.
 *
 * Three things are stored and everything else is worked out:
 *
 *   contract     what the company agreed to give them, in hours a week
 *   availability which days and hours they can actually work
 *   shifts       the rota the player (or the generator) has actually made
 *
 * The rota is not a display. The people on today's rota are the people the
 * shop has; anybody not rostered is not there, and a shift that nobody is
 * covering is a shop running short-handed at the busiest hour of the week.
 * That is the whole point of it, and it is why this had to go in underneath
 * the existing staffing rather than beside it.
 */

export const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] as const;
export type DayIndex = 0 | 1 | 2 | 3 | 4 | 5 | 6;

/** Which weekday a game day falls on. The calendar's own reckoning. */
export function weekdayOf(day: number): DayIndex {
  return (Math.max(0, Math.floor(day) - 1) % 7) as DayIndex;
}

// ------------------------------------------------------------- contracts

export type ContractKind = 'full' | 'part' | 'casual';

export interface ContractDef {
  id: ContractKind;
  name: string;
  /** The band the company has agreed to keep them within, per week. */
  min: number;
  max: number;
  /** What they would like, which is not always the same thing. */
  prefers: number;
  detail: string;
}

/**
 * The three kinds of agreement.
 *
 * Bands rather than fixed numbers, because the interesting part is the room
 * between them: a full-timer rostered for thirty hours is being short-changed
 * and knows it, and one rostered for forty-six is being worked into the ground.
 */
export const CONTRACTS: ContractDef[] = [
  {
    id: 'full', name: 'Full time', min: 32, max: 40, prefers: 38,
    detail: 'A proper job. They expect the hours, and they expect them to be roughly the same every week.',
  },
  {
    id: 'part', name: 'Part time', min: 8, max: 28, prefers: 20,
    detail: 'Fewer hours by agreement. Cheaper to carry, and they have a life arranged around the hours they were promised.',
  },
  {
    id: 'casual', name: 'Casual', min: 0, max: 24, prefers: 12,
    detail: 'No guaranteed hours either way. Flexible for you, precarious for them, and they will leave for anything steadier.',
  },
];

export function contractOf(employee: Employee): ContractDef {
  return CONTRACTS.find((c) => c.id === employee.contract) ?? CONTRACTS[0];
}

// ------------------------------------------------------------ availability

export interface Availability {
  /** Which days they can work at all. */
  days: boolean[];
  /** The earliest they can start and the latest they can finish. */
  from: number;
  to: number;
  /** Days they would rather not work, but will. */
  reluctant: boolean[];
}

export function fullyAvailable(): Availability {
  return { days: [true, true, true, true, true, true, true], from: 6, to: 23, reluctant: new Array(7).fill(false) };
}

/**
 * Whether somebody can work a given hour on a given day at all.
 *
 * A hard no. Being asked anyway is not a small unhappiness — it is a shift
 * that does not get covered, because they do not turn up to it.
 */
export function canWork(person: Employee, day: DayIndex, hour: number): boolean {
  const available = person.availability;
  if (!available) return true;
  if (!available.days[day]) return false;
  return hour >= available.from && hour < available.to;
}

/** Whether they can work it but would rather not. */
export function reluctantAbout(person: Employee, day: DayIndex): boolean {
  return Boolean(person.availability?.reluctant[day]);
}

// ----------------------------------------------------------------- shifts

export interface Shift {
  id: string;
  employeeId: string;
  businessId: string;
  day: DayIndex;
  /** Hours, inclusive of `from` and exclusive of `to`. */
  from: number;
  to: number;
}

export function hoursOf(shift: Shift): number {
  return Math.max(0, shift.to - shift.from);
}

export function shiftsFor(state: GameState, businessId: string, day?: DayIndex): Shift[] {
  return (state.shifts ?? []).filter(
    (shift) => shift.businessId === businessId && (day === undefined || shift.day === day),
  );
}

export function shiftsOfPerson(state: GameState, employeeId: string): Shift[] {
  return (state.shifts ?? []).filter((shift) => shift.employeeId === employeeId);
}

/** Hours somebody is rostered for across the week. */
export function weeklyHours(state: GameState, employeeId: string): number {
  return sum(shiftsOfPerson(state, employeeId), hoursOf);
}

export interface ShiftCheck {
  ok: boolean;
  reason: string;
  /** True when it is allowed but somebody will mind. */
  grumble?: string;
}

/**
 * Whether a shift can be worked.
 *
 * Refuses only the things that are actually impossible — the shop is shut,
 * they are already somewhere else, they are not available — and merely grumbles
 * about the things that are possible and unwelcome. That distinction is the
 * design: the player is allowed to work somebody every Saturday, and they are
 * allowed to find out what it costs.
 */
export function canWorkShift(
  state: GameState,
  employeeId: string,
  businessId: string,
  day: DayIndex,
  from: number,
  to: number,
  ignoreShiftId?: string,
): ShiftCheck {
  if (to <= from) return { ok: false, reason: 'A shift has to be longer than nothing.' };
  const person = state.employees.find((e) => e.id === employeeId);
  if (!person) return { ok: false, reason: 'Unknown employee.' };
  const business = state.businesses.find((b) => b.id === businessId);
  if (!business) return { ok: false, reason: 'Unknown business.' };

  // The shop has to be open. Rostering somebody into a closed shop is paying
  // them to stand outside it.
  const opens = business.openFrom;
  const closes = business.openTo > business.openFrom ? business.openTo : 24;
  if (from < opens || to > closes) {
    return { ok: false, reason: `${business.name} is open ${opens}:00 to ${closes}:00.` };
  }

  for (let hour = from; hour < to; hour += 1) {
    if (!canWork(person, day, hour)) {
      return { ok: false, reason: `${person.name} is not available then.` };
    }
  }

  // One person cannot be in two places.
  const clash = shiftsOfPerson(state, employeeId).find(
    (shift) => shift.id !== ignoreShiftId && shift.day === day && from < shift.to && to > shift.from,
  );
  if (clash) return { ok: false, reason: `${person.name} is already working ${clash.from}:00 to ${clash.to}:00 that day.` };

  // And the things that are allowed but will be noticed.
  const contract = contractOf(person);
  const already = sum(
    shiftsOfPerson(state, employeeId).filter((shift) => shift.id !== ignoreShiftId),
    hoursOf,
  );
  const after = already + (to - from);
  if (after > contract.max) {
    return { ok: true, reason: '', grumble: `That takes ${person.name} to ${after} hours — over the ${contract.max} their contract says.` };
  }
  if (reluctantAbout(person, day)) {
    return { ok: true, reason: '', grumble: `${person.name} would rather not work ${DAYS[day]}s.` };
  }
  return { ok: true, reason: '' };
}

export function addShift(
  state: GameState,
  employeeId: string,
  businessId: string,
  day: DayIndex,
  from: number,
  to: number,
): { ok: boolean; message: string; shift?: Shift } {
  const check = canWorkShift(state, employeeId, businessId, day, from, to);
  if (!check.ok) return { ok: false, message: check.reason };
  if (!state.shifts) state.shifts = [];
  const shift: Shift = { id: `sh_${state.shifts.length}_${Date.now().toString(36)}`, employeeId, businessId, day, from, to };
  state.shifts.push(shift);
  return { ok: true, message: check.grumble ?? '', shift };
}

export function removeShift(state: GameState, shiftId: string): boolean {
  const before = (state.shifts ?? []).length;
  state.shifts = (state.shifts ?? []).filter((shift) => shift.id !== shiftId);
  return state.shifts.length < before;
}

/**
 * Turn one hour of one person's day on or off.
 *
 * What a player does when they edit a rota by hand: they point at Thursday at
 * six and say yes or no. Everything else — whether that makes a new shift,
 * lengthens one, or cuts one in half — is bookkeeping, and bookkeeping is what
 * this is for.
 *
 * It goes through `addShift` like everything else does, so an edit cannot put
 * somebody somewhere the generator would have refused to.
 */
export function toggleHour(
  state: GameState,
  employeeId: string,
  businessId: string,
  day: DayIndex,
  hour: number,
): { ok: boolean; message: string } {
  const mine = shiftsOfPerson(state, employeeId).filter(
    (shift) => shift.businessId === businessId && shift.day === day,
  );
  const hours = new Set<number>();
  for (const shift of mine) for (let h = shift.from; h < shift.to; h += 1) hours.add(h);

  const turningOn = !hours.has(hour);
  if (turningOn) {
    // Check before touching anything, so a refusal leaves the rota as it was.
    const check = canWorkShift(state, employeeId, businessId, day, hour, hour + 1, mine[0]?.id);
    if (!check.ok) return { ok: false, message: check.reason };
    hours.add(hour);
  } else {
    hours.delete(hour);
  }

  for (const shift of mine) removeShift(state, shift.id);

  let grumble = '';
  for (const run of runsIn([...hours].sort((a, b) => a - b))) {
    const result = addShift(state, employeeId, businessId, day, run.from, run.to);
    if (result.message) grumble = result.message;
  }
  return { ok: true, message: grumble };
}

/** Sorted hours collapsed into the fewest continuous stretches. */
function runsIn(hours: number[]): { from: number; to: number }[] {
  const runs: { from: number; to: number }[] = [];
  for (const hour of hours) {
    const last = runs[runs.length - 1];
    if (last && last.to === hour) last.to = hour + 1;
    else runs.push({ from: hour, to: hour + 1 });
  }
  return runs;
}

export function clearRota(state: GameState, businessId: string): number {
  const before = (state.shifts ?? []).length;
  state.shifts = (state.shifts ?? []).filter((shift) => shift.businessId !== businessId);
  return before - (state.shifts ?? []).length;
}

// --------------------------------------------------------------- who is in

/**
 * Who is actually at work right now.
 *
 * The one function the rest of the game asks, and the reason the rota is not
 * decoration. A business with no rota at all falls back to everybody being in,
 * which is exactly how the game behaved before any of this existed — so an
 * existing save, or a player who never opens the planner, sees no change.
 */
export function onDuty(state: GameState, business: Business): Employee[] {
  const staff = employeesOf(state, business.id).filter((person) => !isOffSick(state, person));
  const rota = shiftsFor(state, business.id);
  if (rota.length === 0) return staff;

  const day = weekdayOf(state.day);
  const hour = state.hour;
  const working = new Set(
    rota
      .filter((shift) => shift.day === day && hour >= shift.from && hour < shift.to)
      .map((shift) => shift.employeeId),
  );
  return staff.filter((person) => working.has(person.id));
}

/** Whether this business is being run off a rota at all. */
export function hasRota(state: GameState, businessId: string): boolean {
  return shiftsFor(state, businessId).length > 0;
}

/**
 * What one person on a shift is worth, once there is a rota.
 *
 * This is the hinge between the rota and the money, and it exists because of
 * an arithmetic problem that would otherwise make the whole planner a trap.
 *
 * A business with no rota has everybody in, every hour it is open — six people
 * covering a seventy-hour week on six salaries. That is what the rest of the
 * economy was balanced against, and it quietly assumes each of them works
 * seventy hours. The moment a rota exists that stops being true: the same six
 * people are now in for the hours they are actually contracted, which is half
 * of that, and the business trades half as well for the same wage bill. A
 * player who pressed Generate would watch their profit fall and never press it
 * again, and a feature nobody presses is a feature that does not exist.
 *
 * So a rota moves labour around rather than destroying it. Somebody on a shift
 * is worth `open hours ÷ the hours their contract says` of what they were worth
 * under the old always-in model — because under that model their salary was
 * already buying the whole week. Roster your contracted hours sensibly across
 * the week and you trade exactly as you did before; stack everybody into Friday
 * evening and you can do better, up to a ceiling, because there is a limit to
 * what a crowded shop floor can serve; leave the place thin and you lose the
 * trade, which is the whole point of the coverage figure.
 */
export const ROTA_CEILING = 1.35;

export function rotaSpread(state: GameState, business: Business): { factor: number; ceiling: number } {
  if (!hasRota(state, business.id)) return { factor: 1, ceiling: Infinity };

  const staff = employeesOf(state, business.id);
  if (staff.length === 0) return { factor: 1, ceiling: Infinity };

  const opens = business.openFrom;
  const closes = business.openTo > business.openFrom ? business.openTo : 24;
  const openHours = Math.max(1, closes - opens) * 7;
  const contracted = sum(staff, (person) => contractOf(person).prefers);
  const average = Math.max(1, contracted / staff.length);

  return {
    // What one shift-hour is worth against the always-in baseline.
    factor: clamp(openHours / average, 1, 4),
    // And the most the business can do at once, however many people are in.
    ceiling: staff.length * ROTA_CEILING,
  };
}

// ---------------------------------------------------------------- coverage

export interface Coverage {
  /** 0..1, hours covered against hours wanted, across the week. */
  overall: number;
  /** Per weekday, so the gap can be found. */
  byDay: { day: DayIndex; wanted: number; covered: number }[];
  /** The worst single stretch, for the one line the planner shows. */
  worst: { day: DayIndex; hour: number; wanted: number; covered: number } | null;
  /** Hours rostered across the week, which is what the wage bill follows. */
  rostered: number;
}

/**
 * How many people this business wants on at a given hour.
 *
 * Driven by the demand it actually sees at that hour rather than by a flat
 * number, which is what makes a Friday evening a different problem from a
 * Tuesday morning. Read from the same hourly demand curve the trading code
 * uses, so the rota is being asked to cover the business that exists.
 */
export function wantedAt(state: GameState, business: Business, day: DayIndex, hour: number): number {
  const opens = business.openFrom;
  const closes = business.openTo > business.openFrom ? business.openTo : 24;
  if (hour < opens || hour >= closes) return 0;

  // The same curve the floor view spawns customers from, so covering an hour
  // on the rota means covering the people who actually walk through the door
  // in it — see ./demand.
  const customers = demandAt(business, day, hour);

  // What one of these people actually serves in an hour, asked of the team that
  // works here rather than assumed from the business type — see perStaffHour.
  // The rota's whole claim is that covering an hour means serving that hour's
  // customers, and that claim is only true if this is the engine's own figure.
  const canServe = Math.max(0.05, perStaffHour(state, business));
  return Math.max(1, Math.ceil(customers / canServe));
}

export function coverageOf(state: GameState, business: Business): Coverage {
  const rota = shiftsFor(state, business.id);
  const byDay: Coverage['byDay'] = [];
  let wantedTotal = 0;
  let coveredTotal = 0;
  let worst: Coverage['worst'] = null;

  for (let day = 0 as DayIndex; day < 7; day = (day + 1) as DayIndex) {
    let wanted = 0;
    let covered = 0;
    for (let hour = 0; hour < 24; hour += 1) {
      const want = wantedAt(state, business, day, hour);
      if (want === 0) continue;
      const on = rota.filter((shift) => shift.day === day && hour >= shift.from && hour < shift.to).length;
      wanted += want;
      covered += Math.min(on, want);
      const gap = want - on;
      if (gap > 0 && (!worst || gap > worst.wanted - worst.covered)) {
        worst = { day, hour, wanted: want, covered: on };
      }
    }
    byDay.push({ day, wanted, covered });
    wantedTotal += wanted;
    coveredTotal += covered;
  }

  return {
    overall: wantedTotal > 0 ? clamp(coveredTotal / wantedTotal, 0, 1) : 1,
    byDay,
    worst,
    rostered: sum(rota, hoursOf),
  };
}

/** Coverage across everything the player runs, for the planner's headline. */
export function companyCoverage(state: GameState): { overall: number; rostered: number; businesses: number } {
  const open = playerBusinesses(state).filter((b) => b.status === 'open' && hasRota(state, b.id));
  if (open.length === 0) return { overall: 1, rostered: 0, businesses: 0 };
  const parts = open.map((business) => coverageOf(state, business));
  return {
    overall: sum(parts, (c) => c.overall) / parts.length,
    rostered: sum(parts, (c) => c.rostered),
    businesses: open.length,
  };
}

// ------------------------------------------------------------- the grumbles

export interface RotaProblem {
  employeeId: string;
  name: string;
  kind: 'overworked' | 'underused' | 'unwilling' | 'nothing';
  detail: string;
}

/**
 * Where the rota and the people disagree.
 *
 * Only about things the player can act on, and always with the reason — a
 * planner that says somebody is unhappy without saying why is a planner that
 * gets ignored.
 */
export function rotaProblems(state: GameState): RotaProblem[] {
  const out: RotaProblem[] = [];
  for (const person of state.employees) {
    if (person.companyId !== state.playerCompanyId) continue;
    const business = state.businesses.find((b) => b.id === person.businessId);
    if (!business || !hasRota(state, business.id)) continue;

    const contract = contractOf(person);
    const hours = weeklyHours(state, person.id);
    const mine = shiftsOfPerson(state, person.id);

    if (hours === 0) {
      out.push({ employeeId: person.id, name: person.name, kind: 'nothing', detail: `${person.name} is on the payroll and not on the rota at all.` });
      continue;
    }
    if (hours > contract.max) {
      out.push({ employeeId: person.id, name: person.name, kind: 'overworked', detail: `${hours} hours against a contract of ${contract.max}.` });
      continue;
    }
    if (hours < contract.min) {
      out.push({ employeeId: person.id, name: person.name, kind: 'underused', detail: `${hours} hours against the ${contract.min} they were promised.` });
      continue;
    }
    const unwilling = mine.filter((shift) => reluctantAbout(person, shift.day)).length;
    if (unwilling > 1) {
      out.push({ employeeId: person.id, name: person.name, kind: 'unwilling', detail: `${unwilling} shifts on days they asked not to work.` });
    }
  }
  return out;
}

/**
 * What the rota is doing to how somebody feels, as morale points.
 *
 * Added to the morale already calculated every night rather than being a
 * second morale of its own. Bounded both ways: a rota that respects what
 * somebody agreed to is worth a few points, and one that ignores it costs
 * more than it is worth, because being messed about is remembered.
 */
export function rotaMorale(state: GameState, person: Employee): number {
  const business = state.businesses.find((b) => b.id === person.businessId);
  if (!business || !hasRota(state, business.id)) return 0;

  const contract = contractOf(person);
  const hours = weeklyHours(state, person.id);
  if (hours === 0) return -6;

  let points = 0;
  // Too many hours, or too few to live on. Both are broken promises.
  if (hours > contract.max) points -= Math.min(14, (hours - contract.max) * 1.6);
  else if (hours < contract.min) points -= Math.min(12, (contract.min - hours) * 0.9);
  else points += 3;

  // And getting roughly what they asked for is worth something on its own.
  const off = Math.abs(hours - contract.prefers);
  if (off <= 3) points += 2;

  const unwilling = shiftsOfPerson(state, person.id).filter((shift) => reluctantAbout(person, shift.day)).length;
  points -= unwilling * 2.5;

  return clamp(points, -16, 5);
}

// ---------------------------------------------------------------- the wages

/**
 * What share of a full week somebody is actually being paid for.
 *
 * A part-timer on twenty hours costs half of what they would full-time, and
 * that is the whole reason the contract matters to the player as well as to
 * the person. A business with no rota pays everybody in full, exactly as it
 * always did.
 */
export function payShare(state: GameState, person: Employee): number {
  const business = state.businesses.find((b) => b.id === person.businessId);
  if (!business || !hasRota(state, business.id)) return 1;
  const hours = weeklyHours(state, person.id);
  // Measured against a full week, so a full-timer on their contract is paid
  // what they were always paid and nobody's wages change by accident.
  return clamp(hours / CONTRACTS[0].prefers, 0, 1.35);
}
