import type { GameState } from './state';
import { buildingById, playerCompany } from './state';
import type { Building } from './types';
import type { ItemDef, ItemGives } from '../data/buildingItems';
import { DOOR_COST, WALL_COST, WINDOW_COST, item, itemOrThrow } from '../data/buildingItems';
import { post } from './finance';
import { money } from './format';
import { clamp, makeId, sum } from './util';

/**
 * What is physically inside a building.
 *
 * Until now a building was an address with a floor area and a rent, and what
 * happened inside it was an abstraction: a shop had "roughly one head per role
 * slot", a head office had however many desks its level said it had. Both of
 * those are fine until the player wants to be the one deciding, and this is the
 * layer where they get to.
 *
 * Three things are stored, and everything else is worked out from them:
 *
 *   items   what is standing where, at a real tile coordinate and a rotation
 *   walls   the lines between tiles, which are what make rooms exist at all
 *   floors  how many storeys have been fitted out
 *
 * There are no room objects. A room is not something the player picks off a
 * list and drops in — it is whatever space the walls happen to enclose, and
 * what kind of room it is depends entirely on what has been put inside it. Put
 * a conference table in a walled space and it is a meeting room; take the table
 * out and it is a room again. That is the whole model, and it is why the player
 * can build a ten-by-six personnel office or one enormous open floor and the
 * game understands both without being told which one they meant.
 *
 * Tiles are the unit throughout, and a tile is a little over a metre square —
 * fine enough that a desk is two tiles by one and comes out the size of a desk,
 * and coarse enough that a shop floor is a grid a person can actually arrange
 * rather than a spreadsheet.
 */

/**
 * Square metres of floor in one tile.
 *
 * About one and a quarter metres square, which is the unit that makes the
 * objects come out the right size: a desk is two tiles by one and therefore
 * a little over three square metres, which is a desk. Pick a coarser tile and
 * a desk becomes the size of a small bedroom.
 */
export const SQM_PER_TILE = 1.6;

/** The largest a single floor plate gets, whatever the building's area says. */
const MAX_SIDE = 44;
const MIN_SIDE = 8;

export type Rotation = 0 | 90 | 180 | 270;

export interface PlacedItem {
  id: string;
  defId: string;
  floor: number;
  /** Top-left tile of the footprint. */
  x: number;
  y: number;
  rot: Rotation;
  /**
   * Who works here.
   *
   * Only ever set on something that is somewhere a person works, and only ever
   * one person. The employee holds the other half of this — see `assign` — and
   * the two are kept in step by going through that one function.
   */
  employeeId?: string | null;
  /**
   * How worn out it is, 0..100.
   *
   * Absent means new. Everything loses condition at its own rate while it is
   * being used, and below about sixty per cent it stops doing the whole of its
   * job — which is what makes maintenance a decision rather than a screen.
   */
  condition?: number;
}

export type EdgeKind = 'wall' | 'door' | 'window';

/**
 * A wall runs along the edge of a tile, not through it.
 *
 * `h` is the top edge of tile (x, y); `v` is its left edge. Storing edges
 * rather than filled tiles is what lets a room be one tile wide and still be a
 * room, and it is why a door can sit in a wall without costing floor space.
 */
export interface WallSegment {
  floor: number;
  x: number;
  y: number;
  dir: 'h' | 'v';
  kind: EdgeKind;
}

export interface Layout {
  buildingId: string;
  /** Tiles across and deep, per floor. Every floor is the same plate. */
  w: number;
  h: number;
  /** How many storeys have been fitted out. At least one. */
  floors: number;
  items: PlacedItem[];
  walls: WallSegment[];
}

// --------------------------------------------------------------- the plate

/**
 * How big a floor plate a building gives you.
 *
 * Read from the building's own floor area, so a cramped unit is cramped in the
 * designer too and the address the player chose keeps mattering after they have
 * signed for it. Deliberately not square: a shop is a frontage and a depth.
 */
export function plateFor(building: Building): { w: number; h: number } {
  const tiles = Math.max(MIN_SIDE * MIN_SIDE, Math.round(building.size / SQM_PER_TILE));
  // Roughly three to two, which reads as a room rather than a corridor.
  const w = clamp(Math.round(Math.sqrt(tiles * 1.5)), MIN_SIDE, MAX_SIDE);
  const h = clamp(Math.round(tiles / w), MIN_SIDE, MAX_SIDE);
  return { w, h };
}

export function emptyLayout(building: Building): Layout {
  const plate = plateFor(building);
  return { buildingId: building.id, w: plate.w, h: plate.h, floors: 1, items: [], walls: [] };
}

export function layoutOf(state: GameState, buildingId: string): Layout | null {
  return state.layouts?.find((l) => l.buildingId === buildingId) ?? null;
}

/**
 * The layout for a building, created the first time anybody opens it.
 *
 * `desks` is how many places to work the building is already understood to
 * have — the figure the rest of the game was using before anybody drew a floor
 * plan. They are drawn in free, because the company already owned them, and
 * that is what makes opening this screen a no-op: the building carries on
 * holding exactly the number of people it held a moment ago, and from then on
 * the player is the one deciding.
 *
 * Without it, opening the designer for the first time would quietly cut a
 * working shop's capacity to whatever happened to be standing in an empty
 * room, which is nothing — and a screen that changes the game by being looked
 * at is a bug however well it draws.
 */
export function layoutFor(state: GameState, buildingId: string, kit: SeedItem[] = []): Layout | null {
  const existing = layoutOf(state, buildingId);
  if (existing) return existing;
  const building = buildingById(state, buildingId);
  if (!building) return null;
  if (!state.layouts) state.layouts = [];
  const fresh = emptyLayout(building);
  seedExisting(fresh, kit);
  state.layouts.push(fresh);
  return fresh;
}

/** One line of the kit a working building is already understood to have. */
export interface SeedItem {
  defId: string;
  count: number;
  /** Put a piece of equipment on it, for anything that needs one. */
  equip?: string;
}

/**
 * Drawing in what was already there.
 *
 * A shop that has been trading for a year has a counter and somewhere to put
 * the stock; nobody drew them, but the business has plainly been running on
 * them. So when a layout is created for a building already in use, the kit
 * that business was implicitly working with is drawn in free — because the
 * company already owned it, and because a screen that halves a shop's takings
 * by being opened is a bug however well it draws.
 *
 * Everything goes through the same placement check as anything the player
 * puts down, so a cramped unit simply gets fewer rather than producing a floor
 * plan that breaks its own rules.
 */
function seedExisting(layout: Layout, kit: SeedItem[]): void {
  let x = 1;
  let y = 1;
  for (const line of kit) {
    const def = item(line.defId);
    if (!def) continue;
    for (let n = 0; n < line.count; n += 1) {
      const spot = findSpot(layout, line.defId, x, y);
      if (!spot) break;
      layout.items.push({ id: makeId('it'), defId: line.defId, floor: 0, x: spot.x, y: spot.y, rot: 0 });
      if (line.equip) {
        // Equipment goes on top of the furniture, which is the one place a
        // second object is allowed to share a tile.
        layout.items.push({ id: makeId('it'), defId: line.equip, floor: 0, x: spot.x, y: spot.y, rot: 0 });
      }
      x = spot.x + def.w + 1;
      y = spot.y;
    }
    x = 1;
    y += 3;
  }
}

/** The first place something fits, searching right and then down. */
function findSpot(layout: Layout, defId: string, fromX: number, fromY: number): { x: number; y: number } | null {
  for (let y = fromY; y < layout.h; y += 1) {
    for (let x = y === fromY ? fromX : 1; x < layout.w; x += 1) {
      if (canPlace(layout, defId, 0, x, y, 0).ok) return { x, y };
    }
  }
  for (let y = 1; y < layout.h; y += 1) {
    for (let x = 1; x < layout.w; x += 1) {
      if (canPlace(layout, defId, 0, x, y, 0).ok) return { x, y };
    }
  }
  return null;
}

// ------------------------------------------------------------- footprints

/** What a thing occupies once it has been turned. */
export function footprint(def: ItemDef, rot: Rotation): { w: number; h: number } {
  return rot === 90 || rot === 270 ? { w: def.h, h: def.w } : { w: def.w, h: def.h };
}

export function tilesOf(placed: PlacedItem): { x: number; y: number }[] {
  const def = item(placed.defId);
  if (!def) return [];
  const box = footprint(def, placed.rot);
  const out: { x: number; y: number }[] = [];
  for (let dy = 0; dy < box.h; dy += 1) {
    for (let dx = 0; dx < box.w; dx += 1) out.push({ x: placed.x + dx, y: placed.y + dy });
  }
  return out;
}

/** Whether one thing is small enough to sit on top of another. */
function standsOn(def: ItemDef, under: ItemDef): boolean {
  const SURFACES = new Set(['desk', 'table', 'counter']);
  return def.w === 1 && def.h === 1 && SURFACES.has(under.look);
}

export interface PlacementCheck {
  ok: boolean;
  /** Why not, in the player's words. Empty when it is fine. */
  reason: string;
}

/**
 * Whether a thing can go there.
 *
 * Two rules and no others: it has to be inside the building, and it cannot
 * stand where something else is already standing. Flat things — a rug, a
 * ceiling light — are the exception, because you walk on one and the other is
 * above your head, and refusing to let a desk sit on a rug would be an
 * absurdity the player would have to work around rather than a rule.
 */
export function canPlace(
  layout: Layout,
  defId: string,
  floor: number,
  x: number,
  y: number,
  rot: Rotation,
  ignoreId: string | null = null,
): PlacementCheck {
  const def = item(defId);
  if (!def) return { ok: false, reason: 'Unknown item.' };
  if (floor < 0 || floor >= layout.floors) return { ok: false, reason: 'That floor does not exist.' };
  const box = footprint(def, rot);
  if (x < 0 || y < 0 || x + box.w > layout.w || y + box.h > layout.h) {
    return { ok: false, reason: 'That would hang outside the building.' };
  }
  if (def.flat) return { ok: true, reason: '' };

  const taken = new Set<string>();
  for (const placed of layout.items) {
    if (placed.floor !== floor || placed.id === ignoreId) continue;
    const other = item(placed.defId);
    if (!other || other.flat) continue;
    // A computer goes on a desk. That is not two things fighting over a tile,
    // it is the only way a workstation is ever actually assembled, so a small
    // thing is allowed to stand on a piece of furniture that has a surface.
    if (standsOn(def, other)) continue;
    for (const tile of tilesOf(placed)) taken.add(`${tile.x},${tile.y}`);
  }
  for (let dy = 0; dy < box.h; dy += 1) {
    for (let dx = 0; dx < box.w; dx += 1) {
      if (taken.has(`${x + dx},${y + dy}`)) {
        return { ok: false, reason: 'Something is already standing there.' };
      }
    }
  }
  return { ok: true, reason: '' };
}

// ------------------------------------------------------------ the actions
// Everything below charges the company and returns a message, exactly like
// renting a unit or buying a machine. There is no second currency and no free
// building mode: a desk costs what the desk costs.

export interface ActionResult {
  ok: boolean;
  message: string;
  /** The thing that was just placed, so the screen can select it. */
  placed?: PlacedItem;
}

export function place(
  state: GameState,
  layout: Layout,
  defId: string,
  floor: number,
  x: number,
  y: number,
  rot: Rotation = 0,
): ActionResult {
  const check = canPlace(layout, defId, floor, x, y, rot);
  if (!check.ok) return { ok: false, message: check.reason };
  const def = itemOrThrow(defId);
  const company = playerCompany(state);
  if (company.cash < def.cost) {
    return { ok: false, message: `A ${def.name.toLowerCase()} costs ${money(def.cost)} and you have ${money(company.cash)}.` };
  }
  const placed: PlacedItem = { id: makeId('it'), defId, floor, x, y, rot };
  layout.items.push(placed);
  post(state, company.id, 'equipment', `${def.name} — ${addressOf(state, layout)}`, -def.cost, null);
  return { ok: true, message: `${def.name} placed.`, placed };
}

/**
 * Moving something that is already yours.
 *
 * Free, because you already paid for it and carrying a desk across a room is
 * not a purchase. This is also what makes the editor usable: a player who is
 * charged every time they nudge something stops arranging and starts
 * tolerating.
 */
export function move(layout: Layout, itemId: string, x: number, y: number, floor?: number): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const onFloor = floor ?? placed.floor;
  const check = canPlace(layout, placed.defId, onFloor, x, y, placed.rot, placed.id);
  if (!check.ok) return { ok: false, message: check.reason };
  placed.x = x;
  placed.y = y;
  placed.floor = onFloor;
  return { ok: true, message: '', placed };
}

export function rotate(layout: Layout, itemId: string, by: 90 | -90): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const next = (((placed.rot + by) % 360) + 360) % 360 as Rotation;
  const check = canPlace(layout, placed.defId, placed.floor, placed.x, placed.y, next, placed.id);
  if (!check.ok) return { ok: false, message: `No room to turn it — ${check.reason.toLowerCase()}` };
  placed.rot = next;
  return { ok: true, message: '', placed };
}

/**
 * Selling something back.
 *
 * Half of what it cost, which is roughly what used office furniture is worth
 * and is low enough that ripping a floor out and starting again is a decision
 * rather than a free reset.
 */
export const RESALE = 0.5;

export function remove(state: GameState, layout: Layout, itemId: string): ActionResult {
  const index = layout.items.findIndex((p) => p.id === itemId);
  if (index < 0) return { ok: false, message: 'That is no longer there.' };
  const placed = layout.items[index];
  const def = item(placed.defId);
  layout.items.splice(index, 1);
  if (def) {
    const back = Math.round(def.cost * RESALE);
    if (back > 0) post(state, state.playerCompanyId, 'equipment', `Sold — ${def.name}`, back, null);
    return { ok: true, message: `${def.name} removed, ${money(back)} back.` };
  }
  return { ok: true, message: 'Removed.' };
}

export function duplicate(state: GameState, layout: Layout, itemId: string): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const def = itemOrThrow(placed.defId);
  const box = footprint(def, placed.rot);
  // Somewhere near the original, looked for outwards rather than dropped on top
  // of it — the player asked for another one, not for a puzzle.
  for (let ring = 1; ring < Math.max(layout.w, layout.h); ring += 1) {
    for (const [dx, dy] of [[box.w * ring, 0], [0, box.h * ring], [-box.w * ring, 0], [0, -box.h * ring]]) {
      const x = placed.x + dx;
      const y = placed.y + dy;
      if (canPlace(layout, placed.defId, placed.floor, x, y, placed.rot).ok) {
        return place(state, layout, placed.defId, placed.floor, x, y, placed.rot);
      }
    }
  }
  return { ok: false, message: 'Nowhere to put another one on this floor.' };
}

// ------------------------------------------------------------------ walls

function sameEdge(a: WallSegment, b: { floor: number; x: number; y: number; dir: 'h' | 'v' }): boolean {
  return a.floor === b.floor && a.x === b.x && a.y === b.y && a.dir === b.dir;
}

export function edgeCost(kind: EdgeKind): number {
  return kind === 'door' ? DOOR_COST : kind === 'window' ? WINDOW_COST : WALL_COST;
}

/**
 * Putting up a wall, or cutting a door or a window into one.
 *
 * An edge holds one thing at a time, so placing a door where a wall already
 * runs replaces it rather than stacking — which is exactly what a player means
 * when they click "door" on a wall they have just built.
 */
export function setEdge(
  state: GameState,
  layout: Layout,
  floor: number,
  x: number,
  y: number,
  dir: 'h' | 'v',
  kind: EdgeKind,
): ActionResult {
  if (floor < 0 || floor >= layout.floors) return { ok: false, message: 'That floor does not exist.' };
  // An edge has to border the plate: the far edges are the outside walls.
  if (x < 0 || y < 0 || x > layout.w || y > layout.h) return { ok: false, message: 'That is outside the building.' };
  if (dir === 'h' && x >= layout.w) return { ok: false, message: 'That is outside the building.' };
  if (dir === 'v' && y >= layout.h) return { ok: false, message: 'That is outside the building.' };

  const existing = layout.walls.find((w) => sameEdge(w, { floor, x, y, dir }));
  if (existing?.kind === kind) return { ok: false, message: 'That is already there.' };

  const cost = edgeCost(kind) - (existing ? Math.round(edgeCost(existing.kind) * RESALE) : 0);
  const company = playerCompany(state);
  if (cost > 0 && company.cash < cost) {
    return { ok: false, message: `That costs ${money(cost)} and you have ${money(company.cash)}.` };
  }
  if (existing) existing.kind = kind;
  else layout.walls.push({ floor, x, y, dir, kind });
  if (cost !== 0) {
    post(state, company.id, 'renovation', `${label(kind)} — ${addressOf(state, layout)}`, -cost, null);
  }
  return { ok: true, message: `${label(kind)} up.` };
}

export function clearEdge(state: GameState, layout: Layout, floor: number, x: number, y: number, dir: 'h' | 'v'): ActionResult {
  const index = layout.walls.findIndex((w) => sameEdge(w, { floor, x, y, dir }));
  if (index < 0) return { ok: false, message: 'There is nothing there.' };
  const gone = layout.walls[index];
  layout.walls.splice(index, 1);
  const back = Math.round(edgeCost(gone.kind) * RESALE * 0.4);
  if (back > 0) post(state, state.playerCompanyId, 'renovation', `Knocked through — ${addressOf(state, layout)}`, back, null);
  return { ok: true, message: `${label(gone.kind)} taken out.` };
}

function label(kind: EdgeKind): string {
  return kind === 'door' ? 'Door' : kind === 'window' ? 'Window' : 'Wall';
}

function addressOf(state: GameState, layout: Layout): string {
  return buildingById(state, layout.buildingId)?.address ?? 'the building';
}

// ------------------------------------------------- condition and equipment

/**
 * How worn a thing is, 0..100. Anything that has never been touched is new.
 */
export function conditionOf(placed: PlacedItem): number {
  return clamp(placed.condition ?? 100, 0, 100);
}

/**
 * What condition does to what something is worth having.
 *
 * Full value down to eighty, then a straight slide to a third of its value at
 * zero. Nothing ever stops working altogether — a worn-out till is a slow till,
 * not a closed shop — because a cliff edge turns one missed maintenance bill
 * into a business that cannot trade, and that is a punishment rather than a
 * decision.
 */
export function conditionFactor(placed: PlacedItem): number {
  const condition = conditionOf(placed);
  if (condition >= 80) return 1;
  return clamp(0.34 + (condition / 80) * 0.66, 0.34, 1);
}

/**
 * Whether the things this one depends on are actually here.
 *
 * A developer's workstation is a desk, a machine and something to run on it.
 * The dependency is written as the contribution it has to come from rather than
 * as a particular item, so any computer satisfies any desk — and the check is
 * done over the room, because that is the unit a person works in.
 */
export function dependenciesMet(layout: Layout, placed: PlacedItem): boolean {
  const def = item(placed.defId);
  if (!def?.dependsOn || def.dependsOn.length === 0) return true;
  const room = roomsOn(layout, placed.floor).find((r) =>
    r.items.some((other) => other.id === placed.id),
  );
  if (!room) return false;
  return def.dependsOn.every((key) => (room.gives[key] ?? 0) > 0);
}

/**
 * What one thing contributes before anybody asks what else is in the room.
 *
 * Its own figures, worn down by its condition. Deliberately knows nothing about
 * dependencies: what a room holds has to be worked out before it is possible to
 * say whether anything in it has what it needs, and a single function that
 * asked both questions called itself until the stack ran out. That actually
 * happened, and this split is the fix.
 */
function rawGivesOf(placed: PlacedItem): Required<ItemGives> {
  const out = EMPTY_GIVES();
  const def = item(placed.defId);
  if (!def) return out;
  const factor = conditionFactor(placed);
  for (const key of Object.keys(out) as (keyof ItemGives)[]) {
    const base = def.gives[key] ?? 0;
    if (base === 0) continue;
    out[key] = STRUCTURAL.includes(key) ? base : base * factor;
  }
  return out;
}

/** What something manages, short of its job, for want of what it needs. */
const WITHOUT = 0.4;

/**
 * Contributions that are facts about the object being there at all.
 *
 * A shabby sofa is still somewhere to sit, a worn shelf still holds stock, and
 * a desk with nothing on it is still a desk — it is simply not yet a job, which
 * is a different thing the workstation count already says. So neither wear nor
 * a missing dependency reduces any of these; they only ever reduce output.
 */
const STRUCTURAL: (keyof ItemGives)[] = ['storage', 'comfort', 'seats', 'desk'];

/**
 * What one thing actually contributes right now.
 *
 * Its own figures worn down by condition, cut to a fraction of themselves on
 * anything that cannot do its job without something it has not got. This is
 * what the interface reads for a single object; the room totals do the same
 * work in two passes over the whole room.
 */
export function givesOf(layout: Layout, placed: PlacedItem): Required<ItemGives> {
  const raw = rawGivesOf(placed);
  if (dependenciesMet(layout, placed)) return raw;
  const out = EMPTY_GIVES();
  for (const key of Object.keys(out) as (keyof ItemGives)[]) {
    out[key] = STRUCTURAL.includes(key) ? raw[key] : raw[key] * WITHOUT;
  }
  return out;
}

export type ItemStatus = 'operational' | 'partial' | 'worn' | 'unassigned';

/** What state a thing is in, in the one word the screen shows. */
export function statusOf(layout: Layout, placed: PlacedItem): ItemStatus {
  if (!dependenciesMet(layout, placed)) return 'partial';
  if (conditionOf(placed) < 60) return 'worn';
  const def = item(placed.defId);
  if (def && (def.gives.desk ?? 0) > 0 && !placed.employeeId) return 'unassigned';
  return 'operational';
}

// ---------------------------------------------------------- wear and repair

/** What everything in a building costs to keep, per month. */
export function upkeepOf(layout: Layout): number {
  return sum(layout.items, (placed) => item(placed.defId)?.upkeep ?? 0);
}

/**
 * A day of use.
 *
 * Only what is actually being used wears out: a desk nobody sits at does not
 * wear, and neither does a machine in a business that is closed. That is the
 * difference between maintenance as a cost of trading and maintenance as a
 * tax on owning things.
 */
export function wearDaily(layout: Layout, inUse: boolean): void {
  if (!inUse) return;
  for (const placed of layout.items) {
    const def = item(placed.defId);
    if (!def || def.wear <= 0) continue;
    // Somewhere a person works only wears while somebody is working there.
    if ((def.gives.desk ?? 0) > 0 && !placed.employeeId) continue;
    placed.condition = clamp(conditionOf(placed) - def.wear, 0, 100);
  }
}

/** What putting one thing back into good order costs. */
export function repairCost(placed: PlacedItem): number {
  const def = item(placed.defId);
  if (!def) return 0;
  const missing = (100 - conditionOf(placed)) / 100;
  // Repair is dearer per point than replacement is per point, which is what
  // makes running something into the ground a real choice rather than always
  // the wrong one.
  return Math.round(def.cost * missing * 0.55);
}

export function repair(state: GameState, layout: Layout, itemId: string): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const def = item(placed.defId);
  if (!def) return { ok: false, message: 'Unknown item.' };
  if (conditionOf(placed) >= 99.5) return { ok: false, message: `The ${def.name.toLowerCase()} is in good order.` };
  const cost = repairCost(placed);
  const company = playerCompany(state);
  if (company.cash < cost) return { ok: false, message: `Putting it right costs ${money(cost)}.` };
  placed.condition = 100;
  post(state, company.id, 'renovation', `Repaired — ${def.name}`, -cost, null);
  return { ok: true, message: `${def.name} back to full condition for ${money(cost)}.`, placed };
}

/** Everything in a building that is worth putting right, worst first. */
export function needsRepair(layout: Layout, below = 70): PlacedItem[] {
  return layout.items
    .filter((placed) => conditionOf(placed) < below)
    .sort((a, b) => conditionOf(a) - conditionOf(b));
}

// -------------------------------------------------------------- upgrading

/**
 * What a better one costs.
 *
 * The difference in list price plus a fitting charge, less whatever the old one
 * is still worth. Running something into the ground and then upgrading is
 * therefore dearer than upgrading while it still has life in it, which is the
 * right way round.
 */
export function upgradeCost(placed: PlacedItem): number {
  const def = item(placed.defId);
  const next = def?.upgradesTo ? item(def.upgradesTo) : undefined;
  if (!def || !next) return 0;
  const tradeIn = Math.round(def.cost * RESALE * (conditionOf(placed) / 100));
  return Math.max(0, Math.round(next.cost * 1.08) - tradeIn);
}

export function upgrade(state: GameState, layout: Layout, itemId: string): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const def = item(placed.defId);
  const nextId = def?.upgradesTo;
  const next = nextId ? item(nextId) : undefined;
  if (!def || !next || !nextId) return { ok: false, message: 'There is nothing better than this one.' };

  // The better one is usually bigger, so there has to be room for it.
  const check = canPlace(layout, nextId, placed.floor, placed.x, placed.y, placed.rot, placed.id);
  if (!check.ok) return { ok: false, message: `A ${next.name.toLowerCase()} is bigger — ${check.reason.toLowerCase()}` };

  const cost = upgradeCost(placed);
  const company = playerCompany(state);
  if (company.cash < cost) return { ok: false, message: `A ${next.name.toLowerCase()} costs ${money(cost)} to fit.` };

  placed.defId = nextId;
  placed.condition = 100;
  post(state, company.id, 'equipment', `${next.name} — replacing ${def.name.toLowerCase()}`, -cost, null);
  return {
    ok: true,
    message: `${def.name} replaced with a ${next.name.toLowerCase()} for ${money(cost)}.`,
    placed,
  };
}

// ------------------------------------------------------------- assignment

/**
 * Putting somebody at a particular place of work.
 *
 * The two halves of this relationship — the person's workplace and the
 * workplace's person — are only ever changed here, together, which is what
 * keeps them from drifting apart. Everything this refuses is a thing that
 * would otherwise leave the pair inconsistent or nonsensical.
 */
export function canAssign(
  state: GameState,
  layout: Layout,
  itemId: string,
  employeeId: string,
): PlacementCheck {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, reason: 'That is no longer there.' };
  const def = item(placed.defId);
  if (!def) return { ok: false, reason: 'Unknown item.' };
  if ((def.gives.desk ?? 0) <= 0) {
    return { ok: false, reason: `A ${def.name.toLowerCase()} is not somewhere a person works.` };
  }
  const person = state.employees.find((e) => e.id === employeeId);
  if (!person) return { ok: false, reason: 'Unknown employee.' };
  if (person.companyId !== state.playerCompanyId) return { ok: false, reason: 'They do not work for you.' };

  // They have to work in this building. Sending somebody to a desk in another
  // shop is not an assignment, it is a transfer, and that is a different act.
  const business = state.businesses.find((b) => b.id === person.businessId);
  const worksHere = business
    ? business.buildingId === layout.buildingId
    : state.headOffice?.buildingId === layout.buildingId
      && state.headOffice.employeeIds.includes(person.id);
  if (!worksHere) return { ok: false, reason: `${person.name} does not work in this building.` };

  if (placed.employeeId && placed.employeeId !== employeeId) {
    const sitting = state.employees.find((e) => e.id === placed.employeeId);
    return { ok: false, reason: `${sitting?.name ?? 'Somebody'} works there.` };
  }
  if (def.roles && def.roles.length > 0 && !def.roles.includes(person.role)) {
    return {
      ok: false,
      reason: `A ${def.name.toLowerCase()} is for ${def.roles.join(' or ')}, and ${person.name} is a ${person.role}.`,
    };
  }
  return { ok: true, reason: '' };
}

export function assign(state: GameState, layout: Layout, itemId: string, employeeId: string): ActionResult {
  const check = canAssign(state, layout, itemId, employeeId);
  if (!check.ok) return { ok: false, message: check.reason };
  const placed = layout.items.find((p) => p.id === itemId)!;

  // One person, one place. Wherever they were before is now free — including
  // in another building, which is how a transfer tidies up after itself.
  for (const other of state.layouts ?? []) {
    for (const spot of other.items) {
      if (spot.employeeId === employeeId) spot.employeeId = null;
    }
  }
  placed.employeeId = employeeId;
  const person = state.employees.find((e) => e.id === employeeId);
  if (person) person.workplaceId = itemId;
  return { ok: true, message: `${person?.name ?? 'Assigned'} works at that ${item(placed.defId)?.name.toLowerCase() ?? 'workplace'}.`, placed };
}

export function unassign(state: GameState, layout: Layout, itemId: string): ActionResult {
  const placed = layout.items.find((p) => p.id === itemId);
  if (!placed) return { ok: false, message: 'That is no longer there.' };
  const person = state.employees.find((e) => e.id === placed.employeeId);
  placed.employeeId = null;
  if (person) person.workplaceId = null;
  return { ok: true, message: person ? `${person.name} has nowhere to work now.` : 'Freed up.', placed };
}

/** Where somebody works, wherever in the company that is. */
export function workplaceOf(state: GameState, employeeId: string): { layout: Layout; placed: PlacedItem } | null {
  for (const layout of state.layouts ?? []) {
    const placed = layout.items.find((p) => p.employeeId === employeeId);
    if (placed) return { layout, placed };
  }
  return null;
}

/**
 * Sitting everybody down.
 *
 * Best fit first: the most particular workplaces are filled before the general
 * ones, so a kitchen range goes to a cook rather than being taken by whoever
 * was first in the list and leaving the cook at a desk.
 */
export function autoAssign(state: GameState, layout: Layout): { seated: number; left: number } {
  const here = state.employees.filter((person) => {
    if (person.companyId !== state.playerCompanyId) return false;
    const business = state.businesses.find((b) => b.id === person.businessId);
    if (business) return business.buildingId === layout.buildingId;
    return state.headOffice?.buildingId === layout.buildingId
      && state.headOffice.employeeIds.includes(person.id);
  });

  const spots = layout.items
    .filter((placed) => (item(placed.defId)?.gives.desk ?? 0) > 0)
    .sort((a, b) => (item(b.defId)?.roles?.length ?? 99) - (item(a.defId)?.roles?.length ?? 99));

  for (const placed of spots) placed.employeeId = null;
  for (const person of here) person.workplaceId = null;

  let seated = 0;
  // Two passes: the ones that only certain people can use, then the rest.
  for (const pass of ['specific', 'general'] as const) {
    for (const placed of spots) {
      if (placed.employeeId) continue;
      const def = item(placed.defId);
      const particular = (def?.roles?.length ?? 0) > 0;
      if (pass === 'specific' ? !particular : particular) continue;
      const taker = here.find((person) => !person.workplaceId && canAssign(state, layout, placed.id, person.id).ok);
      if (!taker) continue;
      placed.employeeId = taker.id;
      taker.workplaceId = placed.id;
      seated += 1;
    }
  }
  return { seated, left: here.length - seated };
}

// ------------------------------------------------------------------ rooms

export type RoomKind =
  | 'work' | 'meeting' | 'training' | 'break' | 'storage'
  | 'reception' | 'sanitary' | 'management' | 'production' | 'empty';

export interface Room {
  id: string;
  floor: number;
  tiles: { x: number; y: number }[];
  /** Everything standing inside it. */
  items: PlacedItem[];
  /** What the room adds up to, from what is in it. */
  kind: RoomKind;
  name: string;
  /** Totals of everything the contents give. */
  gives: Required<ItemGives>;
  /** Tiles, and the box they sit in, for the screen. */
  area: number;
  bounds: { x: number; y: number; w: number; h: number };
  /** Whether it does the job its contents claim. */
  complete: boolean;
  missing: string;
}

const EMPTY_GIVES = (): Required<ItemGives> => ({
  desk: 0, equips: 0, meeting: 0, training: 0, rest: 0, storage: 0,
  sanitary: 0, reception: 0, management: 0, production: 0, comfort: 0,
  checkout: 0, cooking: 0, seats: 0, cold: 0, server: 0, calls: 0, bay: 0,
  station: 0, room: 0, display: 0,
});

function blocked(walls: WallSegment[], floor: number, x: number, y: number, dir: 'h' | 'v'): boolean {
  return walls.some((w) => w.floor === floor && w.x === x && w.y === y && w.dir === dir);
}

/**
 * The rooms on a floor, worked out from the walls.
 *
 * A flood fill across tiles that cannot step over a wall. Doors and windows
 * count as walls here, because a doorway between two rooms still leaves two
 * rooms — a door is how you get in, not what makes it one space.
 *
 * Whatever the fill encloses is a room. If the player has built no walls at
 * all, the whole floor is one room, which is correct: that is an open-plan
 * office, and it behaves like one.
 */
export function roomsOn(layout: Layout, floor: number): Room[] {
  const seen: boolean[] = new Array(layout.w * layout.h).fill(false);
  const rooms: Room[] = [];
  const at = (x: number, y: number): number => y * layout.w + x;

  for (let y0 = 0; y0 < layout.h; y0 += 1) {
    for (let x0 = 0; x0 < layout.w; x0 += 1) {
      if (seen[at(x0, y0)]) continue;
      const tiles: { x: number; y: number }[] = [];
      const queue = [{ x: x0, y: y0 }];
      seen[at(x0, y0)] = true;
      while (queue.length > 0) {
        const tile = queue.pop()!;
        tiles.push(tile);
        const { x, y } = tile;
        // North: the tile's own top edge. South: the next tile's top edge.
        if (y > 0 && !blocked(layout.walls, floor, x, y, 'h') && !seen[at(x, y - 1)]) {
          seen[at(x, y - 1)] = true;
          queue.push({ x, y: y - 1 });
        }
        if (y + 1 < layout.h && !blocked(layout.walls, floor, x, y + 1, 'h') && !seen[at(x, y + 1)]) {
          seen[at(x, y + 1)] = true;
          queue.push({ x, y: y + 1 });
        }
        if (x > 0 && !blocked(layout.walls, floor, x, y, 'v') && !seen[at(x - 1, y)]) {
          seen[at(x - 1, y)] = true;
          queue.push({ x: x - 1, y });
        }
        if (x + 1 < layout.w && !blocked(layout.walls, floor, x + 1, y, 'v') && !seen[at(x + 1, y)]) {
          seen[at(x + 1, y)] = true;
          queue.push({ x: x + 1, y });
        }
      }
      rooms.push(describe(layout, floor, tiles, rooms.length));
    }
  }
  return rooms;
}

function describe(layout: Layout, floor: number, tiles: { x: number; y: number }[], index: number): Room {
  const inside = new Set(tiles.map((t) => `${t.x},${t.y}`));
  // By the object's own corner rather than by any tile it covers: something
  // that straddles a wall belongs to one room, not to both, or the totals
  // would count it twice.
  const items = layout.items.filter(
    (placed) => placed.floor === floor && inside.has(`${placed.x},${placed.y}`),
  );

  // Two passes. The first says what is in the room; the second asks which of
  // it can actually do its job given what the first pass found — a question
  // that cannot be answered until the room's contents are known, which is why
  // this is two loops rather than one call to givesOf().
  const raw = EMPTY_GIVES();
  for (const placed of items) {
    const contributed = rawGivesOf(placed);
    for (const key of Object.keys(raw) as (keyof ItemGives)[]) raw[key] += contributed[key];
  }
  const gives = EMPTY_GIVES();
  for (const placed of items) {
    const def = item(placed.defId);
    const met = !def?.dependsOn || def.dependsOn.every((key) => raw[key] > 0);
    const contributed = rawGivesOf(placed);
    for (const key of Object.keys(gives) as (keyof ItemGives)[]) {
      const penalised = met || STRUCTURAL.includes(key) ? 1 : WITHOUT;
      gives[key] += contributed[key] * penalised;
    }
  }

  const xs = tiles.map((t) => t.x);
  const ys = tiles.map((t) => t.y);
  const bounds = {
    x: Math.min(...xs),
    y: Math.min(...ys),
    w: Math.max(...xs) - Math.min(...xs) + 1,
    h: Math.max(...ys) - Math.min(...ys) + 1,
  };

  // What the room is, decided by what is standing in it. Ordered so the more
  // particular kinds win: a training room with a desk in it is still a training
  // room, and a room whose defining feature is a lavatory is not an office.
  let kind: RoomKind = 'empty';
  if (gives.training > 0) kind = 'training';
  else if (gives.production > 0) kind = 'production';
  else if (gives.reception > 0) kind = 'reception';
  else if (gives.meeting >= 4) kind = 'meeting';
  else if (gives.management > 0) kind = 'management';
  else if (gives.desk > 0) kind = 'work';
  else if (gives.rest >= 3) kind = 'break';
  else if (gives.storage >= 60) kind = 'storage';
  // Last, because plumbing in the corner of a room that is plainly something
  // else does not make the room a lavatory. A room whose only feature is the
  // plumbing, on the other hand, is exactly that.
  else if (gives.sanitary > 0) kind = 'sanitary';

  // Whether it actually does the job. This is the only place a room can be
  // wrong, and it is always for a reason the player can see and fix.
  let complete = true;
  let missing = '';
  if (kind === 'work' && gives.equips < gives.desk) {
    const bare = gives.desk - gives.equips;
    complete = false;
    missing = bare === 1 ? 'a desk with nothing on it' : `${bare} desks with nothing on them`;
  }
  if (kind === 'training' && tiles.length < 12) {
    complete = false;
    missing = 'not enough room to teach anybody in';
  }
  if (kind === 'meeting' && gives.meeting < 4) {
    complete = false;
    missing = 'nowhere for people to sit round';
  }

  return {
    id: `${floor}:${index}`,
    floor,
    tiles,
    items,
    kind,
    name: ROOM_NAMES[kind],
    gives,
    area: tiles.length,
    bounds,
    complete,
    missing,
  };
}

export const ROOM_NAMES: Record<RoomKind, string> = {
  work: 'Work area',
  meeting: 'Meeting room',
  training: 'Training room',
  break: 'Break room',
  storage: 'Storage',
  reception: 'Reception',
  sanitary: 'Toilets',
  management: 'Management office',
  production: 'Production',
  empty: 'Empty space',
};

/** Every room in the building, on every floor. */
export function rooms(layout: Layout): Room[] {
  const all: Room[] = [];
  for (let floor = 0; floor < layout.floors; floor += 1) all.push(...roomsOn(layout, floor));
  return all;
}

// ---------------------------------------------------------------- the sums
// What the building adds up to. Everything the rest of the game reads about a
// designed building comes through one of these.

export interface BuildingTotals {
  /** Tiles of floor, over every storey. */
  area: number;
  /** Tiles with something standing on them. */
  used: number;
  /** Desks with something on them to work with. The real capacity figure. */
  workstations: number;
  /** Desks that are not yet a job. */
  bareDesks: number;
  storage: number;
  training: number;
  meeting: number;
  rest: number;
  sanitary: number;
  management: number;
  production: number;
  comfort: number;
  /** The capacity drivers, which differ by trade. See sim/needs.ts. */
  checkout: number;
  cooking: number;
  seats: number;
  cold: number;
  server: number;
  calls: number;
  bay: number;
  /** Places a customer uses for a while: a treadmill, a cinema seat, a lane. */
  station: number;
  /** Rooms a guest can sleep in. */
  room: number;
  /** Vehicles standing where somebody can walk round them. */
  display: number;
  rooms: Room[];
}

export function totals(layout: Layout): BuildingTotals {
  const all = rooms(layout);
  // Summed from the rooms rather than from the items: the rooms partition the
  // floor, they have already worked out what can do its job and what cannot,
  // and doing it per item here would repeat that whole calculation once for
  // every object in a building that may hold hundreds.
  const gives = EMPTY_GIVES();
  for (const room of all) {
    for (const key of Object.keys(gives) as (keyof ItemGives)[]) gives[key] += room.gives[key];
  }
  const used = new Set<string>();
  for (const placed of layout.items) {
    const def = item(placed.defId);
    if (!def || def.flat) continue;
    for (const tile of tilesOf(placed)) used.add(`${placed.floor}:${tile.x},${tile.y}`);
  }
  // A place to work is either complete in itself or half of one.
  //
  // A workshop bench, a till and a range are whole workplaces: somebody stands
  // at them and does the job. An office desk is not — it is a surface, and it
  // becomes a job when there is something on it to work with. Counting both
  // the same way meant a repair shop full of benches reported nobody could
  // work there, which was nonsense and read as a broken game.
  let selfContained = 0;
  let needsKit = 0;
  for (const placed of layout.items) {
    const def = item(placed.defId);
    if (!def || (def.gives.desk ?? 0) <= 0) continue;
    if (def.dependsOn?.includes('equips')) needsKit += def.gives.desk ?? 0;
    else selfContained += def.gives.desk ?? 0;
  }
  // Equipment beyond the number of bare desks is spare, not an extra job.
  const workstations = selfContained + Math.min(needsKit, gives.equips);
  const bareDesks = Math.max(0, needsKit - gives.equips);
  return {
    area: layout.w * layout.h * layout.floors,
    used: used.size,
    workstations,
    bareDesks,
    storage: gives.storage,
    training: gives.training,
    meeting: gives.meeting,
    rest: gives.rest,
    sanitary: gives.sanitary,
    management: gives.management,
    production: gives.production,
    comfort: gives.comfort,
    checkout: gives.checkout,
    cooking: gives.cooking,
    seats: gives.seats,
    cold: gives.cold,
    server: gives.server,
    calls: gives.calls,
    bay: gives.bay,
    station: gives.station,
    room: gives.room,
    display: gives.display,
    rooms: all,
  };
}

// ----------------------------------------------------------------- storeys

/** What fitting out another storey costs, which rises with the plate. */
export function floorCost(layout: Layout): number {
  return Math.round(layout.w * layout.h * 260);
}

export function addFloor(state: GameState, layout: Layout): ActionResult {
  const building = buildingById(state, layout.buildingId);
  if (!building) return { ok: false, message: 'Unknown building.' };
  if (layout.floors >= building.floors) {
    return { ok: false, message: `${building.address} has ${building.floors} storey${building.floors === 1 ? '' : 's'}. There is nothing above this one.` };
  }
  const cost = floorCost(layout);
  const company = playerCompany(state);
  if (company.cash < cost) return { ok: false, message: `Fitting out another floor costs ${money(cost)}.` };
  layout.floors += 1;
  post(state, company.id, 'renovation', `Fitted out floor ${layout.floors} — ${building.address}`, -cost, null);
  return { ok: true, message: `Floor ${layout.floors} is open.` };
}

// ------------------------------------------------------------------- reset

/** Everything out, at the usual resale. Used by "clear the floor". */
export function clearFloor(state: GameState, layout: Layout, floor: number): ActionResult {
  const going = layout.items.filter((placed) => placed.floor === floor);
  if (going.length === 0 && !layout.walls.some((w) => w.floor === floor)) {
    return { ok: false, message: 'That floor is already empty.' };
  }
  const back = Math.round(sum(going, (placed) => item(placed.defId)?.cost ?? 0) * RESALE);
  layout.items = layout.items.filter((placed) => placed.floor !== floor);
  layout.walls = layout.walls.filter((w) => w.floor !== floor);
  if (back > 0) post(state, state.playerCompanyId, 'equipment', `Cleared a floor — ${addressOf(state, layout)}`, back, null);
  return { ok: true, message: `Floor cleared, ${money(back)} back.` };
}
