import type { GameState } from './state';
import { employeesOf } from './state';
import type { Business, Employee } from './types';
import { item } from '../data/buildingItems';
import { layoutOf } from './layout';
import {
  CONTRACTS,
  DAYS,
  type DayIndex,
  addShift,
  canWorkShift,
  clearRota,
  contractOf,
  coverageOf,
  reluctantAbout,
  wantedAt,
  weeklyHours,
} from './rota';
import { performanceOf } from './skills';
import { sum } from './util';

/**
 * Building the rota.
 *
 * Writing a week's shifts by hand for fifteen people is the kind of work a
 * computer should do, and the kind a player should be able to check. So this
 * does two things and they are equally important: it produces a rota, and it
 * tells you what it could not do and why.
 *
 * The second half matters more than it sounds. A generator that silently
 * produces a rota with Friday evening uncovered has told the player nothing;
 * one that says "Friday 18:00 is two people short, because everybody who could
 * work it is already at their contracted hours" has told them to hire somebody,
 * and told them what kind of somebody.
 *
 * It is deliberately not clever. It fills the busiest hours first with the
 * people who are cheapest to use and most willing, stops when a constraint says
 * stop, and reports. An optimal roster is a research problem; a roster a person
 * would recognise as sensible, and can then fix by hand, is the job.
 */

export interface SchedulerSettings {
  /** Never take anybody past the hours their contract says. */
  respectContracts: boolean;
  /** Avoid days people asked not to work, where there is any alternative. */
  respectPreferences: boolean;
  /** Prefer the cheaper person when two would do. */
  watchCost: boolean;
  /** Prefer the better person for the busiest hours. */
  preferSkilled: boolean;
  /** Leave somewhere unstaffed rather than put one person on alone. */
  neverAlone: boolean;
}

export function defaultSettings(): SchedulerSettings {
  return {
    respectContracts: true,
    respectPreferences: true,
    watchCost: true,
    preferSkilled: false,
    neverAlone: false,
  };
}

export interface ScheduleReport {
  /** Shifts written. */
  shifts: number;
  hours: number;
  /** 0..1 of the hours the business wanted covered. */
  coverage: number;
  /** Everything it managed, in the player's words. */
  good: string[];
  /** Everything it could not, each with the reason. */
  problems: string[];
  /** What to do about it, when there is something. */
  advice: string | null;
}

/** One hour of one day that still wants somebody. */
interface Gap {
  day: DayIndex;
  hour: number;
  /** How many the hour wants in total. */
  short: number;
  /** Which of those this slot is — the first person on, the second, the third. */
  rank: number;
}

/**
 * Writes a week's rota for one business.
 *
 * Clears whatever was there first: a generator that adds to an existing rota
 * produces something neither the player nor the generator understands, and
 * "regenerate" is the button people actually press.
 */
export function generateRota(
  state: GameState,
  business: Business,
  settings: SchedulerSettings = defaultSettings(),
): ScheduleReport {
  clearRota(state, business.id);

  const staff = employeesOf(state, business.id);
  if (staff.length === 0) {
    return {
      shifts: 0, hours: 0, coverage: 0,
      good: [],
      problems: [`${business.name} has nobody working at it.`],
      advice: 'Take somebody on before there is a rota to write.',
    };
  }

  // Every hour the business wants somebody, in the order a manager would
  // actually fill them.
  //
  // Not simply busiest-first, which is the obvious answer and the wrong one: it
  // puts four people on Friday evening and leaves Tuesday at ten with nobody at
  // all, and a shop that is open with nobody in it does no trade whatsoever.
  // The first person on any open hour is worth more than the third person on
  // the busiest one. So the hours are filled in passes — everywhere covered
  // once, then everywhere covered twice — and within a pass the busiest hour
  // gets the pick of the staff.
  const gaps: Gap[] = [];
  for (let day = 0 as DayIndex; day < 7; day = (day + 1) as DayIndex) {
    for (let hour = 0; hour < 24; hour += 1) {
      const want = wantedAt(state, business, day, hour);
      for (let rank = 0; rank < want; rank += 1) gaps.push({ day, hour, short: want, rank });
    }
  }
  gaps.sort((a, b) => (a.rank - b.rank) || (b.short - a.short));

  // Shifts are built up as runs rather than hour by hour, because nobody is
  // employed for one hour at a time and a rota full of single hours is not a
  // rota anybody would work.
  const filled = new Map<string, number[]>();
  const shortfalls: Gap[] = [];

  for (const gap of gaps) {
    // The pass this slot belongs to may already have been covered by a longer
    // shift somebody was given for a neighbouring hour.
    if (countOn(filled, gap.day, gap.hour) > gap.rank) continue;
    const taker = pickFor(state, business, staff, gap, settings, filled);
    if (!taker) {
      shortfalls.push({ ...gap, short: gap.short - countOn(filled, gap.day, gap.hour) });
      continue;
    }
    mark(filled, taker.id, gap.day, gap.hour);
  }

  // Nobody on their own, if that is what was asked for.
  //
  // Done as a pass at the end rather than as a rule while filling, because
  // whether somebody is alone is only knowable once everybody else has been
  // placed. An hour with one person on gets a second if one can be found, and
  // loses the one if not — which is what the setting says, and it costs
  // coverage, which is what the report is for.
  if (settings.neverAlone) {
    for (let day = 0 as DayIndex; day < 7; day = (day + 1) as DayIndex) {
      for (let hour = 0; hour < 24; hour += 1) {
        if (countOn(filled, day, hour) !== 1) continue;
        const gap: Gap = { day, hour, short: wantedAt(state, business, day, hour), rank: 1 };
        const second = pickFor(state, business, staff, gap, settings, filled);
        if (second) {
          mark(filled, second.id, day, hour);
        } else {
          for (const [employeeId, marks] of filled) {
            const slot = marks.indexOf(day * 24 + hour);
            if (slot >= 0) marks.splice(slot, 1);
            filled.set(employeeId, marks);
          }
          shortfalls.push({ day, hour, short: gap.short, rank: 0 });
        }
      }
    }
  }

  // Turn the marked hours into runs, close up the gaps nobody would work
  // around, and write them.
  let written = 0;
  let hours = 0;
  for (const [employeeId, marks] of filled) {
    const person = staff.find((p) => p.id === employeeId);
    const runs = person ? joinUp(runsOf(marks), contractOf(person).max - markedHours(filled, employeeId)) : runsOf(marks);
    for (const run of runs) {
      const result = addShift(state, employeeId, business.id, run.day, run.from, run.to);
      if (result.ok) {
        written += 1;
        hours += run.to - run.from;
      }
    }
  }

  return report(state, business, staff, written, hours, shortfalls, settings);
}

// ------------------------------------------------------------- the choosing

/** A key for one person's marked hours. `day * 24 + hour`. */
function mark(filled: Map<string, number[]>, employeeId: string, day: DayIndex, hour: number): void {
  const marks = filled.get(employeeId) ?? [];
  marks.push(day * 24 + hour);
  filled.set(employeeId, marks);
}

function countOn(filled: Map<string, number[]>, day: DayIndex, hour: number): number {
  const slot = day * 24 + hour;
  let count = 0;
  for (const marks of filled.values()) if (marks.includes(slot)) count += 1;
  return count;
}

function markedHours(filled: Map<string, number[]>, employeeId: string): number {
  return (filled.get(employeeId) ?? []).length;
}

/**
 * Who should cover a given hour.
 *
 * Scored rather than sorted, because the considerations pull against each
 * other: the cheapest person may be the one who asked not to work Saturdays,
 * and the best person may already be at their hours. Every term here is one of
 * the settings the player can turn off, so the scoring is theirs rather than
 * mine.
 */
function pickFor(
  state: GameState,
  business: Business,
  staff: Employee[],
  gap: Gap,
  settings: SchedulerSettings,
  filled: Map<string, number[]>,
): Employee | null {
  let best: { person: Employee; score: number } | null = null;

  for (const person of staff) {
    // Already on at that hour.
    if ((filled.get(person.id) ?? []).includes(gap.day * 24 + gap.hour)) continue;

    // Can they work it at all? This is the hard constraint, and it is the
    // rota's own rule rather than a second copy of it.
    const check = canWorkShift(state, person.id, business.id, gap.day, gap.hour, gap.hour + 1);
    if (!check.ok) continue;

    const contract = contractOf(person);
    const planned = markedHours(filled, person.id) + weeklyHours(state, person.id);
    if (settings.respectContracts && planned >= contract.max) continue;

    let score = 100;
    // Somebody short of the hours they were promised is the right person to
    // give an hour to, and that outranks everything else here.
    if (planned < contract.min) score += 40;
    else if (planned < contract.prefers) score += 14;
    // Past the hours they actually asked for, they are the last resort rather
    // than the obvious choice — otherwise the generator works four people to
    // their contractual ceiling and leaves the fifth on nothing, which is
    // legal, cheap to compute and exactly what a bad manager does.
    else score -= 18;

    if (settings.respectPreferences && reluctantAbout(person, gap.day)) score -= 35;
    if (settings.watchCost) score -= (person.salary / 400);
    if (settings.preferSkilled) score += performanceOf(person) * 0.25;

    // Somebody who has nowhere to work is worth less on the floor than
    // somebody who has — they are still useful, but not as useful.
    if (!person.workplaceId) score -= 8;
    // And a run is better than a scatter: being already on either side of this
    // hour makes a longer, more workable shift.
    const marks = filled.get(person.id) ?? [];
    if (marks.includes(gap.day * 24 + gap.hour - 1) || marks.includes(gap.day * 24 + gap.hour + 1)) score += 22;

    if (!best || score > best.score) best = { person, score };
  }

  return best?.person ?? null;
}

interface Run {
  day: DayIndex;
  from: number;
  to: number;
}

/** How long a hole in somebody's day can be before it is worth going home. */
const WORTH_GOING_HOME = 3;

/**
 * Closing up the holes.
 *
 * Filling the busy hours first leaves people with ten till twelve, three till
 * six and an afternoon in between — which is arithmetically fine and not a
 * shift any person would accept. A manager writing this by hand would keep them
 * on through the quiet bit rather than send them away for two hours, so that is
 * what this does: two stretches of the same day with a short gap between them
 * become one shift, as long as there are hours left in the contract to pay for
 * the middle. A genuinely long break stays a genuinely long break, because a
 * split shift over a lunchtime lull is a real thing rather than an artefact.
 */
function joinUp(runs: Run[], spare: number): Run[] {
  const out: Run[] = [];
  let budget = spare;
  for (const run of runs) {
    const last = out[out.length - 1];
    const gap = last && last.day === run.day ? run.from - last.to : Infinity;
    if (last && gap > 0 && gap < WORTH_GOING_HOME && gap <= budget) {
      budget -= gap;
      last.to = run.to;
      continue;
    }
    out.push({ ...run });
  }
  return out;
}

/** Marked hours turned into the fewest continuous shifts that cover them. */
function runsOf(marks: number[]): Run[] {
  const sorted = [...marks].sort((a, b) => a - b);
  const runs: Run[] = [];
  let start: number | null = null;
  let previous: number | null = null;

  for (const slot of sorted) {
    if (start === null || previous === null) {
      start = slot;
      previous = slot;
      continue;
    }
    const sameDay = Math.floor(slot / 24) === Math.floor(previous / 24);
    if (sameDay && slot === previous + 1) {
      previous = slot;
      continue;
    }
    runs.push({ day: Math.floor(start / 24) as DayIndex, from: start % 24, to: (previous % 24) + 1 });
    start = slot;
    previous = slot;
  }
  if (start !== null && previous !== null) {
    runs.push({ day: Math.floor(start / 24) as DayIndex, from: start % 24, to: (previous % 24) + 1 });
  }
  return runs;
}

// -------------------------------------------------------------- explaining

/**
 * Saying what happened.
 *
 * The part of this file that earns its place. Every problem names the hour, the
 * number of people missing and the reason nobody could be put there — and the
 * reason is worked out by asking the same questions the scheduler asked, so it
 * cannot claim something the generator did not actually run into.
 */
function report(
  state: GameState,
  business: Business,
  staff: Employee[],
  written: number,
  hours: number,
  shortfalls: Gap[],
  settings: SchedulerSettings,
): ScheduleReport {
  const coverage = coverageOf(state, business);
  const good: string[] = [];
  const problems: string[] = [];

  good.push(`${Math.round(coverage.overall * 100)}% of the hours ${business.name} wanted covered.`);
  good.push(`${written} shift${written === 1 ? '' : 's'}, ${hours} hours across the week.`);

  const overworked = staff.filter((person) => weeklyHours(state, person.id) > contractOf(person).max);
  if (overworked.length === 0 && settings.respectContracts) {
    good.push('Nobody is over the hours their contract says.');
  } else if (overworked.length > 0) {
    problems.push(`${overworked.map((p) => p.name).join(', ')} ${overworked.length === 1 ? 'is' : 'are'} over contracted hours.`);
  }

  const short = staff.filter((person) => weeklyHours(state, person.id) < contractOf(person).min);
  if (short.length > 0) {
    problems.push(
      `${short.map((p) => `${p.name} (${weeklyHours(state, p.id)}h of ${contractOf(p).min})`).join(', ')} ${short.length === 1 ? 'is' : 'are'} under the hours they were promised.`,
    );
  }

  const unwilling = staff.filter(
    (person) => shiftDays(state, person.id).some((day) => reluctantAbout(person, day)),
  );
  if (unwilling.length === 0 && settings.respectPreferences) {
    good.push('Nobody is working a day they asked to keep.');
  } else if (unwilling.length > 0) {
    problems.push(`${unwilling.map((p) => p.name).join(', ')} ${unwilling.length === 1 ? 'is' : 'are'} on a day they asked to keep.`);
  }

  // The gaps. Counted as hours rather than as unfilled places, because an hour
  // that wanted four people and got one is one hour the player has to fix, and
  // saying "three" there would be counting the same problem three times.
  if (shortfalls.length > 0) {
    const worst = [...shortfalls].sort((a, b) => b.short - a.short)[0];
    const hours = new Set(shortfalls.map((gap) => gap.day * 24 + gap.hour)).size;
    problems.push(
      `${DAYS[worst.day]} ${String(worst.hour).padStart(2, '0')}:00 is ${worst.short} short, and ${hours} hour${hours === 1 ? '' : 's'} across the week ${hours === 1 ? 'is' : 'are'} not fully covered.`,
    );
  }

  return {
    shifts: written,
    hours,
    coverage: coverage.overall,
    good,
    problems,
    advice: adviceFor(state, business, staff, shortfalls, settings),
  };
}

function shiftDays(state: GameState, employeeId: string): DayIndex[] {
  return (state.shifts ?? []).filter((shift) => shift.employeeId === employeeId).map((shift) => shift.day);
}

/**
 * What to do about it.
 *
 * One sentence, and only when there is a real answer. The reason is worked out
 * from which constraint actually bound: if everybody was available and simply
 * at their hours, the answer is another pair of hands; if nobody could work the
 * hour at all, the answer is somebody with different availability; and if there
 * is nowhere for them to work, the answer is not a person at all.
 */
function adviceFor(
  state: GameState,
  business: Business,
  staff: Employee[],
  shortfalls: Gap[],
  settings: SchedulerSettings,
): string | null {
  if (shortfalls.length === 0) return null;
  const worst = [...shortfalls].sort((a, b) => b.short - a.short)[0];

  // Could anybody have worked it, if the contracts had allowed it?
  const couldIfAllowed = staff.filter(
    (person) => canWorkShift(state, person.id, business.id, worst.day, worst.hour, worst.hour + 1).ok,
  );
  const atTheirLimit = couldIfAllowed.filter(
    (person) => weeklyHours(state, person.id) >= contractOf(person).max,
  );

  // And is there even anywhere for another person to stand?
  const layout = layoutOf(state, business.buildingId);
  if (layout) {
    const spots = layout.items.filter((placed) => (item(placed.defId)?.gives.desk ?? 0) > 0).length;
    if (spots <= staff.length) {
      return `Another pair of hands would not help until there is somewhere for them to work — ${business.name} has ${spots} place${spots === 1 ? '' : 's'} to work and ${staff.length} people.`;
    }
  }

  if (couldIfAllowed.length === 0) {
    return `Nobody at ${business.name} is available ${DAYS[worst.day]} at ${String(worst.hour).padStart(2, '0')}:00. Somebody who can work evenings or weekends would cover it.`;
  }
  if (atTheirLimit.length === couldIfAllowed.length && settings.respectContracts) {
    const kind = CONTRACTS.find((c) => c.id === 'part') ?? CONTRACTS[1];
    return `Everybody who could work ${DAYS[worst.day]} ${String(worst.hour).padStart(2, '0')}:00 is already at their contracted hours. One more ${kind.name.toLowerCase()} person would cover it.`;
  }
  return `${DAYS[worst.day]} ${String(worst.hour).padStart(2, '0')}:00 is the hour to look at.`;
}

// ------------------------------------------------------- the whole company

export interface PlannerRow {
  business: Business;
  coverage: number;
  rostered: number;
  people: number;
  /** Hours the rota costs a week, at what those people are paid. */
  cost: number;
  hasRota: boolean;
}

/** Every business the player runs, for the workforce planner. */
export function plannerRows(state: GameState): PlannerRow[] {
  return state.businesses
    .filter((business) => business.companyId === state.playerCompanyId && business.status === 'open')
    .map((business) => {
      const staff = employeesOf(state, business.id);
      const coverage = coverageOf(state, business);
      const rota = (state.shifts ?? []).filter((shift) => shift.businessId === business.id);
      return {
        business,
        coverage: coverage.overall,
        rostered: coverage.rostered,
        people: staff.length,
        // What the rostered hours actually cost, from what each person is paid.
        cost: Math.round(
          sum(rota, (shift) => {
            const person = staff.find((p) => p.id === shift.employeeId);
            if (!person) return 0;
            return ((shift.to - shift.from) * person.salary) / (CONTRACTS[0].prefers * 4.33);
          }),
        ),
        hasRota: rota.length > 0,
      };
    });
}
