import { alpha, shade } from './sprites';

/**
 * The isometric view.
 *
 * Everything the player looks at inside a building is drawn through here, and
 * it is deliberately small: a projection, a cuboid, a few shapes built out of
 * cuboids, and the shading rules that make them read as solid. The objects
 * themselves live in ./isoArt, and they are made of these pieces rather than of
 * raw canvas calls, so a shelf and a fridge and an oven sit on the floor the
 * same way and catch the light from the same direction.
 *
 * The projection is the ordinary two-to-one isometric: a tile is twice as wide
 * as it is deep, which keeps every diagonal on a clean half-pixel slope and
 * means a wall drawn as a rectangle is a wall rather than a smear. One tile is
 * a metre and a half of floor — the same `SQM_PER_TILE` the layout works in —
 * so a desk that is two tiles across is a desk you could sit at.
 */

/** Half the width and half the depth of one floor tile, in pixels at 1× zoom. */
export const TILE_W = 34;
export const TILE_H = 17;
/** How tall one "level" of an object is. A worktop is about one of these. */
export const LEVEL = 15;

export interface Point {
  x: number;
  y: number;
}

/** Tile coordinates, and a height off the floor, to a point on the canvas. */
export function project(tx: number, ty: number, tz = 0): Point {
  return {
    x: (tx - ty) * TILE_W,
    y: (tx + ty) * TILE_H - tz * LEVEL,
  };
}

/** The inverse, for working out which tile the pointer is over. */
export function unproject(x: number, y: number): Point {
  return {
    x: (x / TILE_W + y / TILE_H) / 2,
    y: (y / TILE_H - x / TILE_W) / 2,
  };
}

/**
 * The light.
 *
 * One direction for the whole game, from the upper left, which is what lets a
 * hundred separately drawn objects look like they are in the same room. The top
 * of a thing is brightest, the left face catches some of it and the right face
 * is in shadow — and every object gets these three from one base colour rather
 * than picking its own, so nothing can drift out of the scheme.
 */
export interface Faces {
  top: string;
  left: string;
  right: string;
}

export function faces(base: string, lift = 0): Faces {
  return {
    top: shade(base, 0.16 + lift),
    left: shade(base, -0.02 + lift),
    right: shade(base, -0.2 + lift),
  };
}

// ------------------------------------------------------------------- shapes

/** The rhombus one tile makes on screen. */
export function tilePath(ctx: CanvasRenderingContext2D, tx: number, ty: number, w = 1, h = 1, tz = 0): void {
  const a = project(tx, ty, tz);
  const b = project(tx + w, ty, tz);
  const c = project(tx + w, ty + h, tz);
  const d = project(tx, ty + h, tz);
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo(c.x, c.y);
  ctx.lineTo(d.x, d.y);
  ctx.closePath();
}

export function fillTile(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  w: number,
  h: number,
  fill: string,
  tz = 0,
): void {
  tilePath(ctx, tx, ty, w, h, tz);
  ctx.fillStyle = fill;
  ctx.fill();
}

/**
 * A box standing on the floor: the thing nearly everything is made of.
 *
 * Takes the footprint in tiles and the height in levels, and draws the three
 * faces you can see. `inset` pulls the box in from the edges of its tiles,
 * which is what stops a room of furniture looking like a solid block — real
 * things do not fill their footprint to the millimetre.
 */
export function box(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  w: number,
  h: number,
  z0: number,
  z1: number,
  colour: string | Faces,
  inset = 0.08,
): void {
  const f = typeof colour === 'string' ? faces(colour) : colour;
  const x0 = tx + inset;
  const y0 = ty + inset;
  const x1 = tx + w - inset;
  const y1 = ty + h - inset;

  const topA = project(x0, y0, z1);
  const topB = project(x1, y0, z1);
  const topC = project(x1, y1, z1);
  const topD = project(x0, y1, z1);
  const botD = project(x0, y1, z0);
  const botC = project(x1, y1, z0);
  const botB = project(x1, y0, z0);

  // Left face: the one facing down-left, towards the viewer.
  ctx.fillStyle = f.left;
  ctx.beginPath();
  ctx.moveTo(topD.x, topD.y);
  ctx.lineTo(topC.x, topC.y);
  ctx.lineTo(botC.x, botC.y);
  ctx.lineTo(botD.x, botD.y);
  ctx.closePath();
  ctx.fill();

  // Right face: down-right, away from the light.
  ctx.fillStyle = f.right;
  ctx.beginPath();
  ctx.moveTo(topC.x, topC.y);
  ctx.lineTo(topB.x, topB.y);
  ctx.lineTo(botB.x, botB.y);
  ctx.lineTo(botC.x, botC.y);
  ctx.closePath();
  ctx.fill();

  // Top.
  ctx.fillStyle = f.top;
  ctx.beginPath();
  ctx.moveTo(topA.x, topA.y);
  ctx.lineTo(topB.x, topB.y);
  ctx.lineTo(topC.x, topC.y);
  ctx.lineTo(topD.x, topD.y);
  ctx.closePath();
  ctx.fill();
}

/** A flat panel standing upright, for doors, screens, signs and glass. */
export function panel(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  along: number,
  vertical: boolean,
  z0: number,
  z1: number,
  fill: string,
): void {
  const a = vertical ? project(tx, ty, z1) : project(tx, ty, z1);
  const b = vertical ? project(tx, ty + along, z1) : project(tx + along, ty, z1);
  const c = vertical ? project(tx, ty + along, z0) : project(tx + along, ty, z0);
  const d = vertical ? project(tx, ty, z0) : project(tx, ty, z0);
  ctx.fillStyle = fill;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo(c.x, c.y);
  ctx.lineTo(d.x, d.y);
  ctx.closePath();
  ctx.fill();
}

/** Something round — a bin, a stool, a plant pot, a person. */
export function cylinder(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  radius: number,
  z0: number,
  z1: number,
  colour: string,
): void {
  const f = faces(colour);
  const bottom = project(tx, ty, z0);
  const top = project(tx, ty, z1);
  const rx = radius * TILE_W;
  const ry = radius * TILE_H;

  // The side, as the shape swept between the two ellipses.
  ctx.fillStyle = f.left;
  ctx.beginPath();
  ctx.moveTo(top.x - rx, top.y);
  ctx.lineTo(bottom.x - rx, bottom.y);
  ctx.ellipse(bottom.x, bottom.y, rx, ry, 0, Math.PI, 0, true);
  ctx.lineTo(top.x + rx, top.y);
  ctx.ellipse(top.x, top.y, rx, ry, 0, 0, Math.PI, false);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = f.top;
  ctx.beginPath();
  ctx.ellipse(top.x, top.y, rx, ry, 0, 0, Math.PI * 2);
  ctx.fill();
}

/** The soft patch under a thing, so it sits on the floor rather than over it. */
export function shadow(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  w: number,
  h: number,
  strength = 0.24,
): void {
  const centre = project(tx + w / 2, ty + h / 2, 0);
  ctx.save();
  ctx.translate(centre.x, centre.y);
  ctx.scale(1, TILE_H / TILE_W);
  const radius = Math.max(w, h) * TILE_W * 0.62;
  const glow = ctx.createRadialGradient(0, 0, radius * 0.2, 0, 0, radius);
  glow.addColorStop(0, `rgba(0,0,0,${strength})`);
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

/** A thin bright line along the top edge of something, to catch the light. */
export function highlight(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  w: number,
  h: number,
  z: number,
  colour: string,
  width = 1,
): void {
  const a = project(tx, ty, z);
  const b = project(tx + w, ty, z);
  ctx.strokeStyle = colour;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.stroke();
  void h;
}

/** A small glowing patch: a screen, a hob ring, a lamp. */
export function glow(
  ctx: CanvasRenderingContext2D,
  tx: number,
  ty: number,
  tz: number,
  radius: number,
  colour: string,
): void {
  const p = project(tx, ty, tz);
  const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, radius);
  g.addColorStop(0, alpha(colour, 0.55));
  g.addColorStop(1, alpha(colour, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * How far back in the room something is, for the drawing order.
 *
 * Painter's algorithm: everything is sorted by how close the back corner of its
 * footprint is to the viewer, and drawn from the back forwards. It is the whole
 * of the depth handling, and it is enough because nothing in a shop floats.
 */
export function depthOf(tx: number, ty: number, w = 1, h = 1): number {
  return tx + w + (ty + h);
}
