import type { GameState } from '../sim/state';
import type { Business } from '../sim/types';
import type { Agent, FloorWorld } from '../sim/floor';
import { stepFloor } from '../sim/floor';
import type { Layout } from '../sim/layout';
import { canPlace, conditionOf, dependenciesMet, footprint, layoutOf } from '../sim/layout';
import { item } from '../data/buildingItems';
import { storageFree, storageUsed } from '../sim/business';
import { clamp } from '../sim/util';
import { playerCompany } from '../sim/state';
import { alpha, shade } from './sprites';
import { LEVEL, TILE_H, TILE_W, depthOf, fillTile, panel, project, unproject } from './iso';
import { paintItem } from './isoArt';
import { UNIFORMS, paintCarried, paintLorry, paintPerson } from './people';

/**
 * The window into a business.
 *
 * A camera over a room, a painter's-algorithm scene, and a pointer that knows
 * what it is over. Everything it draws comes from the game: the walls and the
 * objects are the layout the player built, the people are the agents the floor
 * simulation is moving around, and how full a shelf looks is how much stock is
 * actually in the building.
 *
 * It owns no game state of its own. Closing the screen throws the canvas away
 * and nothing is lost, because there was nothing here that was not derived.
 */

export type Pick =
  | { kind: 'item'; id: string }
  | { kind: 'agent'; id: string }
  | { kind: 'floor'; x: number; y: number };

export class FloorCanvas {
  /** The one on screen, for the test harness to drive. */
  static current: FloorCanvas | null = null;

  readonly canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private host: HTMLElement;
  private world: FloorWorld | null = null;
  private getState: () => GameState;
  private businessId: string;

  private zoom = 1;
  private panX = 0;
  private panY = 0;
  /** Where the camera is gliding to, when it was told to look at something. */
  private glide: { x: number; y: number } | null = null;

  private frame: number | null = null;
  private last = 0;
  private clock = 0;
  private running = false;
  private observer: ResizeObserver | null = null;
  private dragging: { x: number; y: number; panX: number; panY: number; moved: boolean } | null = null;
  private pinch: number | null = null;
  /**
   * Whether the camera has been framed against a canvas that has a real size.
   *
   * A canvas that has not been laid out yet reports the HTML default of
   * 300×150, and framing a room against that puts it in a corner at minimum
   * zoom — which is exactly what it did the first time. So the fit is retried
   * until the element has actually been measured.
   */
  private fitted = false;

  /** Highlighted: what the pointer is over, and what the player has chosen. */
  hovered: Pick | null = null;
  selected: Pick | null = null;

  onPick: (pick: Pick | null) => void = () => {};
  /**
   * What the player is about to put down, if they are building.
   *
   * The whole of build mode as far as the canvas is concerned: a definition and
   * a rotation. Whether it may go where the pointer is, and what it costs, are
   * answered by the same `canPlace` the designer uses — there is one set of
   * placement rules and this asks it rather than reimplementing it.
   */
  placing: { defId: string; rot: 0 | 90 | 180 | 270 } | null = null;
  onPlace: (defId: string, x: number, y: number, rot: 0 | 90 | 180 | 270) => void = () => {};
  /** Where the pointer last was, in tiles, for the ghost. */
  private ghost: { x: number; y: number } | null = null;
  /**
   * How fast floor time runs against real time.
   *
   * Thirty seconds of shop for every second of watching: a customer who is in
   * the place for eight minutes is on screen for about fifteen, which is long
   * enough to follow and short enough that a shop with any trade in it is never
   * empty. It changes nothing about the game's own clock — the day outside is
   * still moving at whatever speed the player set in the header.
   */
  speed = 30;

  constructor(host: HTMLElement, getState: () => GameState, businessId: string) {
    this.host = host;
    this.getState = getState;
    this.businessId = businessId;
    this.canvas = document.createElement('canvas');
    this.canvas.className = 'floor-canvas';
    host.appendChild(this.canvas);
    const context = this.canvas.getContext('2d');
    if (!context) throw new Error('This browser cannot draw a canvas.');
    this.ctx = context;
    this.attach();
    FloorCanvas.current = this;
  }

  setWorld(world: FloorWorld | null): void {
    this.world = world;
    // Deliberately not framed here: a canvas that has not been laid out yet
    // reports the HTML default of 300×150, which is big enough to look like a
    // real measurement and small enough to put the room in a corner. The frame
    // happens in `resize`, once the element has a size the browser gave it.
    this.fitted = false;
  }

  getWorld(): FloorWorld | null {
    return this.world;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    this.tick();
  }

  stop(): void {
    this.running = false;
    if (this.frame !== null) cancelAnimationFrame(this.frame);
    this.frame = null;
  }

  destroy(): void {
    this.stop();
    this.observer?.disconnect();
    this.canvas.remove();
    if (FloorCanvas.current === this) FloorCanvas.current = null;
  }

  // ------------------------------------------------------------- the camera

  zoomBy(factor: number): void {
    this.zoom = clamp(this.zoom * factor, 0.45, 2.6);
    this.paint();
  }

  zoomNow(): number {
    return this.zoom;
  }

  /**
   * Shift the view without changing the zoom.
   *
   * Used when a panel opens over the room: the build tray takes the bottom
   * third of the stage, and the bottom third of the stage is where the door and
   * the queue are. Lifting the camera keeps what the player came to look at
   * above the thing they are using to change it.
   */
  panBy(dx: number, dy: number): void {
    this.panX += dx;
    this.panY += dy;
    this.glide = null;
    this.paint();
  }

  /** Put something in the middle of the screen, smoothly. */
  lookAt(tx: number, ty: number): void {
    const p = project(tx, ty, 0);
    this.glide = {
      x: this.canvas.clientWidth / 2 - p.x * this.zoom,
      y: this.canvas.clientHeight / 2 - p.y * this.zoom,
    };
  }

  focusAgent(agentId: string): void {
    const agent = this.world?.agents.find((a) => a.id === agentId);
    if (!agent) return;
    this.selected = { kind: 'agent', id: agentId };
    this.lookAt(agent.x, agent.y);
  }

  focusItem(itemId: string): void {
    const layout = this.layout();
    const placed = layout?.items.find((it) => it.id === itemId);
    if (!placed) return;
    const def = item(placed.defId);
    const size = def ? footprint(def, placed.rot) : { w: 1, h: 1 };
    this.selected = { kind: 'item', id: itemId };
    this.lookAt(placed.x + size.w / 2, placed.y + size.h / 2);
  }

  /** Frame the whole floor plate. */
  fit(): void {
    const world = this.world;
    if (!world) return;
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;
    if (width < 40 || height < 40) return;
    const spanX = (world.w + world.h) * TILE_W;
    const spanY = (world.w + world.h) * TILE_H + LEVEL * 4;
    this.zoom = clamp(Math.min((width - 48) / spanX, (height - 48) / spanY), 0.45, 2.2);
    const middle = project(world.w / 2, world.h / 2, 0);
    this.panX = width / 2 - middle.x * this.zoom;
    this.panY = height / 2 - middle.y * this.zoom;
    this.glide = null;
    this.fitted = true;
    this.paint();
  }

  resize(): void {
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    const width = this.host.clientWidth;
    const height = this.host.clientHeight;
    if (width === 0 || height === 0) return;
    this.canvas.width = Math.round(width * ratio);
    this.canvas.height = Math.round(height * ratio);
    this.canvas.style.width = `${width}px`;
    this.canvas.style.height = `${height}px`;
    this.ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    if (!this.fitted) this.fit();
    else this.paint();
  }

  // ---------------------------------------------------------------- the loop

  private tick(): void {
    if (!this.running) return;
    this.frame = requestAnimationFrame(() => {
      const now = performance.now();
      // Capped, so a tab that was in the background does not fast-forward the
      // floor through an hour of arrivals in one frame.
      const delta = Math.min(0.1, (now - this.last) / 1000);
      this.last = now;
      this.clock += delta;

      if (this.world) {
        const state = this.getState();
        const business = state.businesses.find((b) => b.id === this.businessId);
        if (business) stepFloor(state, this.world, delta * this.speed);
      }
      if (this.glide) {
        // Ease towards the target rather than snapping, so the player keeps
        // their bearings when the camera is told to go somewhere.
        this.panX += (this.glide.x - this.panX) * 0.14;
        this.panY += (this.glide.y - this.panY) * 0.14;
        if (Math.hypot(this.glide.x - this.panX, this.glide.y - this.panY) < 0.6) this.glide = null;
      }
      this.paint();
      this.tick();
    });
  }

  private layout(): Layout | null {
    return this.world ? layoutOf(this.getState(), this.world.buildingId) : null;
  }

  private business(): Business | null {
    return this.getState().businesses.find((b) => b.id === this.businessId) ?? null;
  }

  // -------------------------------------------------------------- the scene

  paint(): void {
    const ctx = this.ctx;
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;
    ctx.clearRect(0, 0, width, height);

    const world = this.world;
    const layout = this.layout();
    const business = this.business();
    if (!world || !layout || !business) return;

    // The room sits in a pool of light on a dark ground, which is what makes
    // it read as an interior rather than a diagram.
    const sky = ctx.createLinearGradient(0, 0, 0, height);
    sky.addColorStop(0, '#0a1020');
    sky.addColorStop(1, '#070b16');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.translate(this.panX, this.panY);
    ctx.scale(this.zoom, this.zoom);

    this.paintFloor(world, business);
    this.paintWalls(world, layout);
    this.paintContents(world, layout, business);
    this.paintGhost(world, layout);

    ctx.restore();
  }

  /** The floor itself: the material this kind of business would actually have. */
  private paintFloor(world: FloorWorld, business: Business): void {
    const ctx = this.ctx;
    const look = FLOORS[world.trade] ?? FLOORS.office;

    // A slab under everything, so the room has an edge.
    fillTile(ctx, -0.25, -0.25, world.w + 0.5, world.h + 0.5, shade(look.base, -0.3));
    for (let y = 0; y < world.h; y += 1) {
      for (let x = 0; x < world.w; x += 1) {
        const tint = (x + y) % 2 === 0 ? 0 : -0.035;
        fillTile(ctx, x, y, 1, 1, shade(look.base, tint));
      }
    }
    // Grout lines, faint, to give the floor a scale without drawing a grid.
    ctx.strokeStyle = alpha(look.line, 0.14);
    ctx.lineWidth = 1;
    for (let x = 0; x <= world.w; x += 1) {
      const a = project(x, 0);
      const b = project(x, world.h);
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }
    for (let y = 0; y <= world.h; y += 1) {
      const a = project(0, y);
      const b = project(world.w, y);
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }

    // The way in, marked on the floor where people actually come through.
    fillTile(ctx, world.door.x - 0.5, world.door.y - 0.4, 1, 0.9, alpha('#5b9bff', 0.14));
    void business;
  }

  /**
   * The walls.
   *
   * Only the two at the back are drawn to full height; the two nearest the
   * viewer would stand between them and the room, so they are left as a low
   * kerb. That is the ordinary way an isometric interior is cut away, and it is
   * the reason you can see inside at all.
   */
  private paintWalls(world: FloorWorld, layout: Layout): void {
    const ctx = this.ctx;
    const WALL = '#26334e';
    const BACK = 3.2;
    const KERB = 0.5;

    // The shell.
    //
    // The building has walls whether or not the player has drawn any: what the
    // designer stores are the partitions they added inside it. So the outside
    // is drawn from the plate, with the two far sides full height and the two
    // near ones cut down to a kerb — the ordinary way an isometric room is
    // opened up, and the reason you can see in at all.
    for (let x = 0; x < world.w; x += 1) {
      const doorway = Math.abs(x - world.door.x) < 0.6;
      panel(ctx, x, 0, 1, false, 0, BACK, shade(WALL, 0.02));
      panel(ctx, x, 0, 1, false, 0, 0.16, shade(WALL, -0.24));
      panel(ctx, x, 0, 1, false, 3.02, BACK, shade(WALL, 0.16));
      if (!doorway) panel(ctx, x, world.h, 1, false, 0, KERB, shade(WALL, -0.12));
    }
    for (let y = 0; y < world.h; y += 1) {
      panel(ctx, 0, y, 1, true, 0, BACK, shade(WALL, -0.08));
      panel(ctx, 0, y, 1, true, 0, 0.16, shade(WALL, -0.3));
      panel(ctx, 0, y, 1, true, 3.02, BACK, shade(WALL, 0.08));
      panel(ctx, world.w, y, 1, true, 0, KERB, shade(WALL, -0.18));
    }

    // Windows along the front, which is what makes it a shopfront rather than
    // a bunker, and the doorway itself.
    for (let x = 0; x < world.w; x += 1) {
      if (Math.abs(x - world.door.x) < 0.6) continue;
      if (x % 3 === 1) panel(ctx, x, world.h, 1, false, 0.5, 1.0, alpha('#7fc3e8', 0.16));
    }
    const dx = Math.round(world.door.x);
    panel(ctx, dx, world.h, 1, false, 0, 0.06, alpha('#5b9bff', 0.5));

    // Then the partitions the player actually drew.
    for (const wall of layout.walls) {
      if (wall.floor !== world.floor) continue;
      if (wall.kind === 'door') continue;
      const colour = wall.kind === 'window' ? alpha('#7fc3e8', 0.34) : shade(WALL, 0.06);
      panel(ctx, wall.x, wall.y, 1, wall.dir === 'v', 0, wall.kind === 'window' ? 2.4 : 2.7, colour);
      panel(ctx, wall.x, wall.y, 1, wall.dir === 'v', 0, 0.14, shade(WALL, -0.26));
    }
  }

  /**
   * Everything that stands on the floor, back to front.
   *
   * One list of objects and people sorted together, because a customer standing
   * in front of a shelf has to be drawn in front of it and the same customer
   * behind it has to be hidden by it. Sorting them separately is the thing that
   * makes an isometric scene look broken.
   */
  private paintContents(world: FloorWorld, layout: Layout, business: Business): void {
    const ctx = this.ctx;
    const state = this.getState();
    // How full the shelves look is how much stock is actually in the building:
    // a shop that has run its stock down has visibly emptier shelves, which is
    // the point at which the player stops needing to read the inventory screen
    // to know something is wrong.
    const used = storageUsed(business);
    const capacity = Math.max(1, used + storageFree(state, business));
    const stocked = clamp(used / capacity, 0, 1);

    interface Drawable { depth: number; paint: () => void }
    const scene: Drawable[] = [];

    for (const placed of layout.items) {
      if (placed.floor !== world.floor) continue;
      const def = item(placed.defId);
      if (!def) continue;
      const size = footprint(def, placed.rot);
      const staffHere = world.agents.find((a) => a.kind === 'staff' && a.targetId === placed.id);
      const manned = Boolean(staffHere && staffHere.path.length === 0);
      const busy = Boolean(
        staffHere && (staffHere.state === 'serving' || staffHere.state === 'working' || staffHere.state === 'carrying'),
      );
      const focus =
        this.selected?.kind === 'item' && this.selected.id === placed.id
          ? true
          : this.hovered?.kind === 'item' && this.hovered.id === placed.id;

      const paint = (): void => {
        if (focus) {
          ctx.save();
          ctx.shadowColor = '#5b9bff';
          ctx.shadowBlur = 16;
        }
        paintItem({
          ctx,
          x: placed.x,
          y: placed.y,
          w: size.w,
          h: size.h,
          def,
          placed,
          condition: clamp(conditionOf(placed) / 100, 0, 1),
          manned,
          busy,
          stocked: dependenciesMet(layout, placed) ? stocked : stocked * 0.4,
          time: this.clock,
          focus,
        });
        if (focus) ctx.restore();
      };
      // Flat things are part of the floor and never occlude anybody.
      scene.push({ depth: def.flat ? -1000 + placed.y : depthOf(placed.x, placed.y, size.w, size.h), paint });
    }

    for (const agent of world.agents) {
      const focus = this.selected?.kind === 'agent' && this.selected.id === agent.id;
      const uniform = agent.kind === 'staff' ? uniformFor(state, agent) : undefined;
      scene.push({
        depth: depthOf(agent.x, agent.y, 0.4, 0.4) + 0.05,
        paint: () => {
          paintPerson({ ctx, agent, uniform, time: this.clock, focus });
          paintCarried(ctx, agent);
        },
      });
    }

    for (const lorry of world.deliveries) {
      scene.push({
        depth: depthOf(lorry.x - 1, lorry.y - 1, 2.2, 2.2),
        paint: () => paintLorry(ctx, lorry.x, lorry.y, lorry.facing, lorry.left),
      });
    }

    scene.sort((a, b) => a.depth - b.depth);
    for (const entry of scene) entry.paint();
  }

  /**
   * What is about to be put down, and whether it can be.
   *
   * Green where it will go, red where it will not — and the reason is the
   * placement check itself rather than a guess, so the ghost never promises
   * something the click then refuses.
   */
  private paintGhost(world: FloorWorld, layout: Layout): void {
    const ctx = this.ctx;
    if (!this.placing || !this.ghost) return;
    const def = item(this.placing.defId);
    if (!def) return;
    const size = footprint(def, this.placing.rot);
    const x = clamp(this.ghost.x, 0, world.w - size.w);
    const y = clamp(this.ghost.y, 0, world.h - size.h);

    const check = canPlace(layout, def.id, world.floor, x, y, this.placing.rot);
    const affordable = playerCompany(this.getState()).cash >= def.cost;
    const ok = check.ok && affordable;

    fillTile(ctx, x, y, size.w, size.h, ok ? 'rgba(47,191,126,0.28)' : 'rgba(239,70,87,0.3)');
    ctx.save();
    ctx.globalAlpha = 0.65;
    paintItem({
      ctx,
      x, y, w: size.w, h: size.h,
      def,
      placed: { id: 'ghost', defId: def.id, floor: world.floor, x, y, rot: this.placing.rot },
      condition: 1,
      manned: false,
      busy: false,
      stocked: 0.7,
      time: this.clock,
      focus: false,
    });
    ctx.restore();
  }

  // ------------------------------------------------------------- the pointer

  /** Which tile a client point is over. */
  private tileAt(clientX: number, clientY: number): { x: number; y: number } {
    const rect = this.canvas.getBoundingClientRect();
    const x = (clientX - rect.left - this.panX) / this.zoom;
    const y = (clientY - rect.top - this.panY) / this.zoom;
    return unproject(x, y);
  }

  /**
   * What is under the pointer.
   *
   * People first, because they are small and stand in front of things, then
   * objects from the front of the room backwards — which is the reverse of the
   * drawing order, and therefore picks whatever the player can actually see.
   */
  pickAt(clientX: number, clientY: number): Pick | null {
    const world = this.world;
    const layout = this.layout();
    if (!world || !layout) return null;
    const tile = this.tileAt(clientX, clientY);

    let closest: { id: string; distance: number } | null = null;
    for (const agent of world.agents) {
      const distance = Math.hypot(agent.x - tile.x, agent.y - tile.y);
      if (distance < 0.55 && (!closest || distance < closest.distance)) {
        closest = { id: agent.id, distance };
      }
    }
    if (closest) return { kind: 'agent', id: closest.id };

    const tx = Math.floor(tile.x);
    const ty = Math.floor(tile.y);
    for (let i = layout.items.length - 1; i >= 0; i -= 1) {
      const placed = layout.items[i];
      if (placed.floor !== world.floor) continue;
      const def = item(placed.defId);
      if (!def) continue;
      const size = footprint(def, placed.rot);
      if (tx >= placed.x && tx < placed.x + size.w && ty >= placed.y && ty < placed.y + size.h) {
        return { kind: 'item', id: placed.id };
      }
    }
    if (tx < 0 || ty < 0 || tx >= world.w || ty >= world.h) return null;
    return { kind: 'floor', x: tx, y: ty };
  }

  private attach(): void {
    const canvas = this.canvas;
    canvas.style.touchAction = 'none';

    canvas.addEventListener('pointerdown', (event) => {
      // Never let a click in here move the page: this canvas lives in a
      // scrolling column and a focus change was enough to jump it.
      event.preventDefault();
      canvas.setPointerCapture(event.pointerId);
      this.dragging = {
        x: event.clientX,
        y: event.clientY,
        panX: this.panX,
        panY: this.panY,
        moved: false,
      };
    });

    canvas.addEventListener('pointermove', (event) => {
      if (this.dragging) {
        const dx = event.clientX - this.dragging.x;
        const dy = event.clientY - this.dragging.y;
        if (Math.hypot(dx, dy) > 4) this.dragging.moved = true;
        if (this.dragging.moved) {
          this.panX = this.dragging.panX + dx;
          this.panY = this.dragging.panY + dy;
          this.glide = null;
        }
        return;
      }
      if (this.placing) {
        const tile = this.tileAt(event.clientX, event.clientY);
        const next = { x: Math.floor(tile.x), y: Math.floor(tile.y) };
        const moved = !this.ghost || this.ghost.x !== next.x || this.ghost.y !== next.y;
        this.ghost = next;
        canvas.style.cursor = 'crosshair';
        if (moved) this.paint();
        return;
      }
      const pick = this.pickAt(event.clientX, event.clientY);
      const changed = JSON.stringify(pick) !== JSON.stringify(this.hovered);
      this.hovered = pick;
      canvas.style.cursor = pick && pick.kind !== 'floor' ? 'pointer' : 'grab';
      if (changed) this.paint();
    });

    const release = (event: PointerEvent): void => {
      if (this.dragging && !this.dragging.moved && this.placing) {
        // Building: the tap puts the thing down rather than selecting whatever
        // happens to be under it.
        const world = this.world;
        const def = item(this.placing.defId);
        if (world && def) {
          const size = footprint(def, this.placing.rot);
          const tile = this.tileAt(event.clientX, event.clientY);
          const x = clamp(Math.floor(tile.x), 0, world.w - size.w);
          const y = clamp(Math.floor(tile.y), 0, world.h - size.h);
          this.onPlace(this.placing.defId, x, y, this.placing.rot);
        }
        this.dragging = null;
        canvas.releasePointerCapture?.(event.pointerId);
        return;
      }
      if (this.dragging && !this.dragging.moved) {
        const pick = this.pickAt(event.clientX, event.clientY);
        this.selected = pick && pick.kind !== 'floor' ? pick : null;
        this.onPick(this.selected);
      }
      this.dragging = null;
      canvas.releasePointerCapture?.(event.pointerId);
    };
    canvas.addEventListener('pointerup', release);
    canvas.addEventListener('pointercancel', () => { this.dragging = null; });

    canvas.addEventListener(
      'wheel',
      (event) => {
        event.preventDefault();
        this.zoomBy(event.deltaY < 0 ? 1.12 : 1 / 1.12);
      },
      { passive: false },
    );

    // Pinch, for a phone.
    canvas.addEventListener('touchmove', (event) => {
      if (event.touches.length !== 2) return;
      event.preventDefault();
      const [a, b] = [event.touches[0], event.touches[1]];
      const span = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
      if (this.pinch !== null) this.zoomBy(span / this.pinch);
      this.pinch = span;
    }, { passive: false });
    canvas.addEventListener('touchend', () => { this.pinch = null; });

    if (typeof ResizeObserver !== 'undefined') {
      this.observer = new ResizeObserver(() => this.resize());
      this.observer.observe(this.host);
    }
  }
}

/** What each kind of business has underfoot. */
const FLOORS: Record<string, { base: string; line: string }> = {
  shop: { base: '#cfd4dd', line: '#8f97a6' },
  kitchen: { base: '#b9a48c', line: '#7d6a55' },
  workshop: { base: '#8f949c', line: '#5e636b' },
  office: { base: '#9aa3b4', line: '#69718a' },
  depot: { base: '#8a8f97', line: '#5c6169' },
  software: { base: '#98a2b8', line: '#667089' },
};

function uniformFor(state: GameState, agent: Agent): string {
  const person = state.employees.find((e) => e.id === agent.employeeId);
  return (person && UNIFORMS[person.role]) || UNIFORMS.sales;
}
