import type { Ctx, View } from '../app';
import type { Building } from '../../sim/types';
import type { Layout, PlacedItem, Room, Rotation } from '../../sim/layout';
import {
  SQM_PER_TILE,
  addFloor,
  assign,
  autoAssign,
  canAssign,
  conditionOf,
  needsRepair,
  repair,
  repairCost,
  statusOf,
  unassign,
  upgrade,
  upgradeCost,
  clearFloor,
  duplicate,
  floorCost,
  footprint,
  layoutFor,
  move,
  place,
  remove,
  rotate,
  setEdge,
  clearEdge,
  totals,
  type SeedItem,
} from '../../sim/layout';
import type { ItemDef } from '../../data/buildingItems';
import {
  DOOR_COST,
  ITEMS,
  ITEM_CATEGORIES,
  WALL_COST,
  WINDOW_COST,
  item,
  itemOrThrow,
} from '../../data/buildingItems';
import { DesignerCanvas, type Tool } from '../designerCanvas';
import { buildingById, employeesOf, playerBusinesses, playerCompany } from '../../sim/state';
import { comfortOf, shortages } from '../../sim/premises';
import { TRADE_NAMES, needsOf, openingKit, readinessOf, tradeOf } from '../../sim/needs';
import { desksTotal } from '../../sim/facilities';
import { count, money } from '../../sim/format';
import { titleOf } from '../../sim/skills';
import { icon } from '../icons';
import {
  bar,
  button,
  clear,
  confirmDialog,
  empty,
  h,
  kpi,
  meter,
  section,
  select,
  stat,
  table,
  tag,
  toast,
} from '../dom';

/**
 * The Building Designer.
 *
 * Three columns, which is the shape this kind of editor has had since the first
 * one: what you can build on the left, what you are building in the middle,
 * what is selected on the right. The middle is a canvas, so nothing in the
 * document moves when a desk does — which is also the answer to the scroll
 * problem, rather than a `scrollTo` put on top of it.
 *
 * Undo is a stack of whole layouts. A floor plan is small — a few hundred
 * numbers — and copying one is cheaper and very much more reliable than trying
 * to invert every action, which is the approach that quietly breaks the first
 * time somebody deletes a wall that two rooms depended on. The money moves with
 * the action and is not undone: buying a desk and then pressing undo leaves the
 * desk bought, because the alternative is an editor you can print money with.
 */

const HISTORY = 40;

export function designerView(ctx: Ctx): View {
  const el = h('div', { class: 'view designer' });

  const buildings = designableBuildings(ctx);
  const wanted = ctx.params.building;
  let current: Building | null =
    buildings.find((b) => b.id === wanted) ?? buildings[0] ?? null;

  if (!current) {
    el.appendChild(
      h('div', { class: 'view-head' }, h('h1', { text: 'Building designer' }),
        h('p', { text: 'Fit out the places your company works in.' })),
    );
    el.appendChild(
      section(
        'Nowhere to design yet',
        empty(
          'You need premises of your own before there is anything to lay out. Take a lease on a unit and it will appear here as an empty shell.',
          { title: 'No premises', icon: 'property', action: button('Find a unit', () => ctx.go('property'), 'btn primary') },
        ),
      ),
    );
    return { el, update: () => undefined };
  }

  /**
   * How many places to work this building is already understood to have.
   *
   * Asked before the layout exists, so it is the figure the game was using
   * beforehand — the shop's estimate, or the head office's floor. Drawing
   * those in is what makes opening this screen change nothing.
   */
  const alreadyHas = (building: Building): SeedItem[] => {
    if (ctx.state.headOffice?.buildingId === building.id) {
      return [{ defId: 'desk', count: desksTotal(ctx.state), equip: 'computer' }];
    }
    const business = playerBusinesses(ctx.state).find((b) => b.buildingId === building.id);
    return business ? openingKit(ctx.state, business) : [];
  };

  let layout = layoutFor(ctx.state, current.id, alreadyHas(current))!;
  const canvas = new DesignerCanvas(layout);

  // ------------------------------------------------------------- history
  const past: string[] = [];
  const future: string[] = [];
  const snapshot = (): string => JSON.stringify(layout);
  const restore = (frozen: string): void => {
    const parsed = JSON.parse(frozen) as Layout;
    layout.items = parsed.items;
    layout.walls = parsed.walls;
    layout.floors = parsed.floors;
    canvas.setLayout(layout);
  };
  let pending = snapshot();
  const remember = (): void => {
    past.push(pending);
    if (past.length > HISTORY) past.shift();
    future.length = 0;
    pending = snapshot();
  };

  // ------------------------------------------------------------- the shell
  let mode: 'build' | 'view' = 'build';
  let tool: Tool = { kind: 'select' };
  let search = '';
  let category = ITEM_CATEGORIES[0].id;
  let selected: PlacedItem | null = null;
  let selectedRoom: Room | null = null;
  let openNeed: string | null = null;
  let workplaceFilter: 'all' | 'free' | 'taken' | 'worn' | 'partial' = 'all';

  const left = h('aside', { class: 'plan-left' });
  const right = h('aside', { class: 'plan-right' });
  const stage = h('div', { class: 'plan-stage' }, canvas.canvas);
  const head = h('div', { class: 'plan-head' });
  const foot = h('div', { class: 'plan-foot' });

  const refreshAll = (): void => {
    renderHead();
    renderLeft();
    renderRight();
    renderFoot();
  };

  // ------------------------------------------------------------- the canvas
  canvas.onSelect = (placed) => {
    selected = placed;
    selectedRoom = null;
    renderRight();
  };
  canvas.onPlace = (x, y) => {
    if (tool.kind !== 'place') return;
    remember();
    const result = place(ctx.state, layout, tool.defId, canvas.getFloor(), x, y, tool.rot);
    if (!result.ok) {
      past.pop();
      toast(result.message, 'bad');
      return;
    }
    canvas.recomputeRooms();
    canvas.draw();
    refreshAll();
  };
  canvas.onEdge = (edge) => {
    if (tool.kind !== 'edge') return;
    remember();
    const result = setEdge(ctx.state, layout, canvas.getFloor(), edge.x, edge.y, edge.dir, tool.edge);
    if (!result.ok) {
      past.pop();
      toast(result.message, 'bad');
      return;
    }
    canvas.recomputeRooms();
    canvas.draw();
    refreshAll();
  };
  canvas.onEraseEdge = (edge) => {
    remember();
    const result = clearEdge(ctx.state, layout, canvas.getFloor(), edge.x, edge.y, edge.dir);
    if (!result.ok) {
      past.pop();
      return;
    }
    canvas.recomputeRooms();
    canvas.draw();
    refreshAll();
  };
  canvas.onMoved = (id, x, y) => move(layout, id, x, y).ok;
  canvas.onChange = (what) => {
    const [kind, id] = what.split(':');
    if (kind === 'move') {
      remember();
      refreshAll();
      return;
    }
    if (kind === 'erase') {
      remember();
      remove(ctx.state, layout, id);
      canvas.recomputeRooms();
      canvas.draw();
      selected = null;
      refreshAll();
    }
  };

  // ----------------------------------------------------------------- head
  function renderHead(): void {
    clear(head);
    const chooser = h('select', { class: 'select plan-building' }) as HTMLSelectElement;
    for (const building of buildings) {
      const option = h('option', { text: `${building.address} — ${labelFor(ctx, building)}` }) as HTMLOptionElement;
      option.value = building.id;
      if (building.id === current?.id) option.selected = true;
      chooser.appendChild(option);
    }
    chooser.addEventListener('change', () => {
      const next = buildings.find((b) => b.id === chooser.value);
      if (!next) return;
      current = next;
      layout = layoutFor(ctx.state, next.id, alreadyHas(next))!;
      past.length = 0;
      future.length = 0;
      pending = snapshot();
      canvas.setLayout(layout);
      canvas.setFloor(0);
      canvas.fit();
      selected = null;
      refreshAll();
    });

    const modes = h('div', { class: 'seg' });
    for (const id of ['build', 'view'] as const) {
      modes.appendChild(
        h('button', {
          class: `seg-btn${mode === id ? ' active' : ''}`,
          text: id === 'build' ? 'Build mode' : 'View mode',
          on: {
            click: () => {
              mode = id;
              if (mode === 'view') {
                tool = { kind: 'select' };
                canvas.setTool(tool);
                canvas.setGrid(false);
                selected = null;
              } else {
                canvas.setGrid(true);
              }
              el.classList.toggle('viewing', mode === 'view');
              refreshAll();
            },
          },
        }),
      );
    }

    const floors = h('select', { class: 'select plan-floor' }) as HTMLSelectElement;
    for (let f = 0; f < layout.floors; f += 1) {
      const option = h('option', { text: `Floor ${f + 1}` }) as HTMLOptionElement;
      option.value = String(f);
      if (f === canvas.getFloor()) option.selected = true;
      floors.appendChild(option);
    }
    floors.addEventListener('change', () => {
      canvas.setFloor(Number(floors.value));
      selected = null;
      refreshAll();
    });

    const building = current!;
    const more = layout.floors < building.floors
      ? button(`Open floor ${layout.floors + 1} — ${money(floorCost(layout))}`, async () => {
          const ok = await confirmDialog(
            `Fit out floor ${layout.floors + 1}?`,
            `${money(floorCost(layout))} to make the storey above usable. It comes as an empty shell, exactly like this one did.`,
            'Fit it out',
          );
          if (!ok) return;
          remember();
          const result = addFloor(ctx.state, layout);
          if (!result.ok) past.pop();
          toast(result.message, result.ok ? 'good' : 'bad');
          if (result.ok) {
            canvas.setFloor(layout.floors - 1);
            canvas.fit();
          }
          refreshAll();
        }, 'btn small')
      : null;

    head.appendChild(
      h('div', { class: 'plan-head-left' },
        h('div', { class: 'plan-title' },
          h('h1', { text: 'Building designer' }),
          h('p', { text: 'Lay the place out. What you build is what the company can do.' })),
      ),
    );
    head.appendChild(h('div', { class: 'plan-head-tools' }, chooser, modes, floors, more));

    const history = h('div', { class: 'plan-head-tools' });
    history.appendChild(
      button('Undo', () => {
        const frozen = past.pop();
        if (!frozen) { toast('Nothing to undo.'); return; }
        future.push(snapshot());
        restore(frozen);
        pending = snapshot();
        selected = null;
        refreshAll();
      }, past.length > 0 ? 'btn small' : 'btn small disabled'),
    );
    history.appendChild(
      button('Redo', () => {
        const frozen = future.pop();
        if (!frozen) { toast('Nothing to redo.'); return; }
        past.push(snapshot());
        restore(frozen);
        pending = snapshot();
        selected = null;
        refreshAll();
      }, future.length > 0 ? 'btn small' : 'btn small disabled'),
    );
    history.appendChild(button('Fit to screen', () => canvas.fit(), 'btn small'));
    history.appendChild(
      button('Leave the designer', () => ctx.go(current?.id === ctx.state.headOffice?.buildingId ? 'headOffice' : 'businesses'), 'btn small primary'),
    );
    head.appendChild(history);
  }

  // ----------------------------------------------------------------- left
  function renderLeft(): void {
    clear(left);
    if (mode === 'view') {
      left.appendChild(
        section('Looking, not building',
          h('p', { class: 'tiny muted', text: 'Switch back to build mode to change anything. This is the place as it stands.' })),
      );
      renderRooms(left);
      return;
    }

    // The structure tools come first: walls are what make rooms, and rooms are
    // what make the rest of it mean anything.
    const structure = h('div', { class: 'tool-row' });
    const tools: { id: Tool; label: string; cost?: number }[] = [
      { id: { kind: 'select' }, label: 'Select' },
      { id: { kind: 'edge', edge: 'wall' }, label: 'Wall', cost: WALL_COST },
      { id: { kind: 'edge', edge: 'door' }, label: 'Door', cost: DOOR_COST },
      { id: { kind: 'edge', edge: 'window' }, label: 'Window', cost: WINDOW_COST },
      { id: { kind: 'erase' }, label: 'Remove' },
    ];
    for (const entry of tools) {
      const active = tool.kind === entry.id.kind
        && (entry.id.kind !== 'edge' || (tool.kind === 'edge' && tool.edge === entry.id.edge));
      structure.appendChild(
        h('button', {
          class: `tool-btn${active ? ' active' : ''}`,
          on: {
            click: () => {
              tool = entry.id;
              canvas.setTool(tool);
              renderLeft();
            },
          },
        },
          h('strong', { text: entry.label }),
          entry.cost ? h('span', { class: 'tiny muted', text: money(entry.cost) }) : null),
      );
    }
    left.appendChild(section('Structure', structure,
      h('p', { class: 'tiny muted', text: 'Walls run between tiles. Whatever they enclose becomes a room, and what you put inside decides what kind.' })));

    // The catalogue.
    const box = h('input', { class: 'input', type: 'search', placeholder: 'Search everything' }) as HTMLInputElement;
    box.value = search;
    box.addEventListener('input', () => {
      search = box.value;
      renderCatalogue();
    });

    const tabs = h('div', { class: 'pill-row' });
    for (const cat of ITEM_CATEGORIES) {
      tabs.appendChild(
        h('button', {
          class: `chip${category === cat.id ? ' active' : ''}`,
          on: { click: () => { category = cat.id; search = ''; box.value = ''; renderCatalogue(); } },
        }, cat.name),
      );
    }

    const list = h('div', { class: 'item-grid' });
    const renderCatalogue = (): void => {
      clear(list);
      const needle = search.trim().toLowerCase();
      const matching = ITEMS.filter((def) => {
        if (needle) return def.name.toLowerCase().includes(needle) || def.group.toLowerCase().includes(needle);
        return def.category === category;
      });
      if (matching.length === 0) {
        list.appendChild(empty('Nothing matches that.'));
        return;
      }
      for (const def of matching) {
        const picked = tool.kind === 'place' && tool.defId === def.id;
        list.appendChild(
          h('button', {
            class: `item-card${picked ? ' active' : ''}`,
            title: def.detail,
            on: {
              click: () => {
                tool = { kind: 'place', defId: def.id, rot: picked && tool.kind === 'place' ? nextRot(tool.rot) : 0 };
                canvas.setTool(tool);
                renderCatalogue();
              },
            },
          },
            h('span', { class: 'item-swatch', data: { look: def.look } }),
            h('strong', { class: 'item-name', text: def.name }),
            // Clicking a chosen thing again turns it, which is the quickest way
            // to lay a row of desks along a wall — so the card says so rather
            // than leaving it to be discovered.
            h('span', {
              class: 'tiny muted',
              text: picked && tool.kind === 'place' && tool.rot !== 0
                ? `turned ${tool.rot}° · click to turn`
                : picked
                  ? 'click again to turn'
                  : `${def.w}×${def.h} · ${money(def.cost)}`,
            })),
        );
      }
      for (const button2 of Array.from(tabs.children)) {
        (button2 as HTMLElement).classList.toggle('active', (button2 as HTMLElement).textContent === ITEM_CATEGORIES.find((c) => c.id === category)?.name);
      }
    };
    renderCatalogue();

    left.appendChild(section('What to put in it', box, tabs, list));
  }

  // ---------------------------------------------------------------- right
  function renderRight(): void {
    clear(right);
    const sums = totals(layout);

    if (selected) {
      const def = itemOrThrow(selected.defId);
      const box = footprint(def, selected.rot);
      const panel = section('Selected item');
      panel.appendChild(
        h('div', { class: 'selected-head' },
          h('span', { class: 'item-swatch big', data: { look: def.look } }),
          h('div', {},
            h('strong', { text: def.name }),
            h('div', { class: 'tiny muted', text: def.detail }))),
      );
      // Stacked rather than in two columns: this column is 300px wide and a
      // label-and-value pair needs the whole of it to stay on one line.
      panel.appendChild(
        h('div', { class: 'spec' },
          stat('Cost', money(def.cost)),
          stat('Size', `${box.w} × ${box.h} tiles`),
          stat('Rotation', `${selected.rot}°`),
          stat('Position', `${selected.x}, ${selected.y} · floor ${selected.floor + 1}`)),
      );
      panel.appendChild(h('div', { class: 'tiny muted', text: givesLine(def) }));

      // What state it is actually in, and who is at it. Everything below is a
      // real action on real state — there is no row here that only displays.
      const condition = conditionOf(selected);
      panel.appendChild(
        meter('Condition', condition / 100, `${Math.round(condition)}%`,
          condition > 80 ? 'good' : condition > 55 ? 'warn' : 'bad'),
      );
      const status = statusOf(layout, selected);
      panel.appendChild(
        h('div', { class: 'row-between', style: 'margin:8px 0' },
          h('span', { class: 'tiny muted', text: 'Status' }),
          tag(STATUS_WORDS[status], STATUS_TONES[status])),
      );
      if (status === 'partial') {
        panel.appendChild(
          h('p', { class: 'warn', text: `It needs ${(def.dependsOn ?? []).map(dependencyName).join(' and ')} in the same room, and there is none. It is doing a fraction of its job.` }),
        );
      }
      if (def.upkeep > 0) {
        panel.appendChild(h('div', { class: 'tiny muted', text: `${money(def.upkeep)} a month to keep.` }));
      }

      // Who works here.
      if ((def.gives.desk ?? 0) > 0) {
        const sitting = ctx.state.employees.find((person) => person.id === selected?.employeeId);
        const seat = h('div', { class: 'assign-box' });
        seat.appendChild(h('div', { class: 'tiny muted', text: 'Who works here' }));
        if (sitting) {
          seat.appendChild(
            h('div', { class: 'row-between' },
              h('strong', { text: sitting.name }),
              button('Take them off', () => {
                const result = unassign(ctx.state, layout, selected!.id);
                toast(result.message, result.ok ? 'info' : 'bad');
                refreshAll();
              }, 'btn small')),
          );
          seat.appendChild(h('div', { class: 'tiny muted', text: `${titleOf(sitting)} · ${sitting.role}` }));
        } else {
          const takers = candidatesFor(ctx, layout, selected.id);
          if (takers.length === 0) {
            seat.appendChild(
              h('div', {
                class: 'tiny warn',
                text: def.roles && def.roles.length > 0
                  ? `Nobody here is a ${def.roles.join(' or ')}. Hire one, or put something else in this spot.`
                  : 'Everybody in this building already has somewhere to work.',
              }),
            );
          } else {
            const who = select(
              takers.map((person) => ({ value: person.id, label: `${person.name} — ${person.role}` })),
              takers[0].id,
              () => undefined,
            );
            seat.appendChild(who);
            seat.appendChild(
              h('div', { class: 'btn-row' },
                button('Put them here', () => {
                  const result = assign(ctx.state, layout, selected!.id, who.value);
                  toast(result.message, result.ok ? 'good' : 'bad');
                  refreshAll();
                }, 'btn small primary')),
            );
          }
        }
        panel.appendChild(seat);
      }

      const actions = h('div', { class: 'btn-row' });
      if (condition < 99.5) {
        actions.appendChild(button(`Repair — ${money(repairCost(selected))}`, () => {
          const result = repair(ctx.state, layout, selected!.id);
          toast(result.message, result.ok ? 'good' : 'bad');
          canvas.draw();
          refreshAll();
        }, 'btn small'));
      }
      if (def.upgradesTo) {
        const next = item(def.upgradesTo);
        actions.appendChild(button(`Replace with ${next?.name.toLowerCase() ?? 'better'} — ${money(upgradeCost(selected))}`, async () => {
          const ok = await confirmDialog(
            `Replace the ${def.name.toLowerCase()}?`,
            `${money(upgradeCost(selected!))} to fit a ${next?.name.toLowerCase() ?? 'better one'}, less what the old one is worth. ${next?.detail ?? ''} It costs ${money(next?.upkeep ?? 0)} a month to keep instead of ${money(def.upkeep)}.`,
            'Replace it',
          );
          if (!ok) return;
          remember();
          const result = upgrade(ctx.state, layout, selected!.id);
          if (!result.ok) past.pop();
          toast(result.message, result.ok ? 'good' : 'bad');
          canvas.recomputeRooms();
          canvas.draw();
          refreshAll();
        }, 'btn small'));
      }
      actions.appendChild(button('Rotate', () => {
        remember();
        const result = rotate(layout, selected!.id, 90);
        if (!result.ok) { past.pop(); toast(result.message, 'bad'); return; }
        canvas.recomputeRooms();
        canvas.draw();
        refreshAll();
      }, 'btn small'));
      actions.appendChild(button('Duplicate', () => {
        remember();
        const result = duplicate(ctx.state, layout, selected!.id);
        if (!result.ok) { past.pop(); toast(result.message, 'bad'); return; }
        selected = result.placed ?? null;
        canvas.select(selected?.id ?? null);
        canvas.recomputeRooms();
        canvas.draw();
        refreshAll();
      }, 'btn small'));
      actions.appendChild(button('Remove', () => {
        remember();
        const result = remove(ctx.state, layout, selected!.id);
        toast(result.message, result.ok ? 'info' : 'bad');
        selected = null;
        canvas.select(null);
        canvas.recomputeRooms();
        canvas.draw();
        refreshAll();
      }, 'btn small danger'));
      panel.appendChild(actions);
      right.appendChild(panel);

      const room = canvas.roomAt(selected.x, selected.y);
      if (room) right.appendChild(roomPanel(room));
    } else if (selectedRoom) {
      right.appendChild(roomPanel(selectedRoom));
    }

    // The building, always.
    const building = current!;
    const here = playerBusinesses(ctx.state).find((b) => b.buildingId === building.id);
    const people = here ? employeesOf(ctx.state, here.id).length
      : ctx.state.headOffice?.buildingId === building.id ? ctx.state.headOffice.employeeIds.length : 0;
    const info = section('This building');
    info.appendChild(
      h('div', { class: 'spec' },
        stat('Address', building.address),
        stat('Floor plate', `${layout.w} × ${layout.h} tiles`),
        stat('Total area', `${Math.round(sums.area * SQM_PER_TILE)} m²`),
        stat('Floor in use', `${Math.round((sums.used / Math.max(1, sums.area)) * 100)}%`),
        stat('Storeys fitted out', `${layout.floors} of ${building.floors}`),
        stat('Rent', `${money(building.rent)}/mo`)),
    );
    // One card per row. The headline figure of the whole screen is how many
    // people can work here, so it gets the width to be read at a glance.
    info.appendChild(
      kpi({
        label: 'Workstations', value: String(sums.workstations), icon: 'hq',
        tone: people > sums.workstations ? 'bad' : 'good',
        sub: people > sums.workstations
          ? `${people} people here — ${people - sums.workstations} with nowhere to work`
          : `${people} of them taken, ${Math.max(0, sums.workstations - people)} free`,
        subTone: people > sums.workstations ? 'bad' : undefined,
      }),
    );
    if (sums.bareDesks > 0) {
      info.appendChild(
        h('p', { class: 'warn', text: `${sums.bareDesks} desk${sums.bareDesks === 1 ? ' has' : 's have'} nothing on ${sums.bareDesks === 1 ? 'it' : 'them'}. A desk is not a job until there is a computer on it.` }),
      );
    }
    const comfort = comfortOf(ctx.state, building.id, people);
    info.appendChild(meter('Good to work in', comfort, `${Math.round(comfort * 100)}%`,
      comfort > 0.6 ? 'good' : comfort > 0.4 ? 'warn' : 'bad'));
    if (sums.sanitary < people) {
      info.appendChild(h('p', { class: 'warn', text: 'There is no lavatory for the number of people here, and everybody notices.' }));
    }
    info.appendChild(
      h('div', { class: 'btn-row' },
        button('Clear this floor', async () => {
          const ok = await confirmDialog(
            'Clear the whole floor?',
            'Everything on this storey goes, and you get half of what it cost back. The walls come down too.',
            'Clear it',
          );
          if (!ok) return;
          remember();
          const result = clearFloor(ctx.state, layout, canvas.getFloor());
          if (!result.ok) past.pop();
          toast(result.message, result.ok ? 'info' : 'bad');
          canvas.recomputeRooms();
          canvas.draw();
          selected = null;
          refreshAll();
        }, 'btn small')),
    );
    right.appendChild(info);
    renderNeeds(right);
    renderWorkplaces(right);
    if (!selected && !selectedRoom) renderRooms(right);
  }

  function roomPanel(room: Room): HTMLElement {
    const panel = section('Room');
    panel.appendChild(
      h('div', { class: 'selected-head' },
        h('div', {},
          h('strong', { text: room.name }),
          h('div', { class: 'tiny muted', text: `${room.bounds.w} × ${room.bounds.h}, ${room.area} tiles · ${Math.round(room.area * SQM_PER_TILE)} m²` }))),
    );
    panel.appendChild(
      h('div', { class: 'grid cols-2' },
        stat('Things in it', String(room.items.length)),
        stat('Workstations', String(Math.min(room.gives.desk, room.gives.equips)))),
    );
    if (!room.complete) {
      panel.appendChild(h('p', { class: 'warn', text: `Not finished: ${room.missing}.` }));
    } else if (room.kind !== 'empty') {
      panel.appendChild(h('div', { class: 'function-says', text: roomDoes(room) }));
    }
    return panel;
  }

  function renderRooms(host: HTMLElement): void {
    const list = canvas.roomsNow().filter((room) => room.kind !== 'empty' || room.items.length > 0);
    const panel = section('Rooms on this floor');
    if (list.length === 0) {
      panel.appendChild(empty('No walls yet, so this floor is one open space. That is a perfectly good office — build walls when you want rooms.'));
    } else {
      for (const room of list) {
        panel.appendChild(
          h('button', {
            class: 'clickable-row',
            on: { click: () => { selectedRoom = room; selected = null; canvas.select(null); renderRight(); } },
          },
            h('div', { class: 'row-between' },
              h('strong', { text: room.name }),
              room.complete ? tag(`${room.area} tiles`, 'muted', true) : tag('incomplete', 'warn')),
            h('div', { class: 'tiny muted', text: room.complete ? roomDoes(room) : room.missing })),
        );
      }
    }
    host.appendChild(panel);
  }


  /**
   * What this business needs, and what going without is doing to it.
   *
   * Every row is read from the simulation at the moment it is drawn, so a need
   * turns green the instant the thing that was missing is bought — there is no
   * second copy of any of these figures to fall out of step.
   */
  function renderNeeds(host: HTMLElement): void {
    const business = playerBusinesses(ctx.state).find((b) => b.buildingId === current?.id);
    if (!business) return;
    const rows = needsOf(ctx.state, business);
    if (rows.length === 0) return;
    const ready = readinessOf(ctx.state, business);

    const panel = section(`What ${business.name} needs`);
    panel.appendChild(
      kpi({
        label: 'Ready to trade', value: `${ready.overall}%`, icon: 'progress',
        tone: ready.overall >= 85 ? 'good' : ready.overall >= 65 ? 'warn' : 'bad',
        sub: ready.bottleneck
          ? `Held back by ${ready.bottleneck.name.toLowerCase()}`
          : `Everything a ${TRADE_NAMES[tradeOf(business)].toLowerCase()} needs is here`,
        subTone: ready.bottleneck ? 'warn' : 'good',
      }),
    );

    for (const row of rows) {
      const card = h('button', {
        class: `need-row ${row.status}`,
        on: {
          click: () => {
            openNeed = openNeed === row.kind ? null : row.kind;
            renderRight();
          },
        },
      });
      card.appendChild(
        h('div', { class: 'row-between' },
          h('strong', { text: row.name }),
          tag(NEED_WORDS[row.status], NEED_TONES[row.status])),
      );
      card.appendChild(
        h('div', { class: 'need-figures' },
          h('span', { text: `${figure(row.current, row.unit)} of ${figure(row.required, row.unit)}` }),
          row.shortfall ? h('span', { class: 'need-short', text: row.shortfall }) : null),
      );
      card.appendChild(bar(row.required > 0 ? row.current / row.required : 1, row.status === 'healthy' || row.status === 'spare' ? 'good' : row.status === 'warning' ? 'warn' : 'bad'));

      if (openNeed === row.kind) {
        card.appendChild(h('div', { class: 'need-why', text: row.matters }));
        if (row.fix && row.cost > 0) {
          const fixDef = item(row.fix);
          card.appendChild(
            h('div', { class: 'tiny muted', text: `About ${money(row.cost)} to put right — ${fixDef?.name.toLowerCase() ?? row.fix}.` }),
          );
          const act = h('div', { class: 'btn-row' });
          act.appendChild(
            button(`Place a ${fixDef?.name.toLowerCase() ?? 'fix'}`, () => {
              // Straight into build mode with the right thing in hand, rather
              // than telling the player to go and find it.
              mode = 'build';
              category = fixDef?.category ?? category;
              search = '';
              tool = { kind: 'place', defId: row.fix!, rot: 0 };
              canvas.setGrid(true);
              canvas.setTool(tool);
              el.classList.remove('viewing');
              toast(`Click the plan to place a ${fixDef?.name.toLowerCase() ?? 'it'}.`);
              refreshAll();
            }, 'btn small primary'),
          );
          card.appendChild(act);
        } else if (row.kind === 'staff') {
          card.appendChild(
            h('div', { class: 'btn-row' },
              button('Take somebody on', () => ctx.go('employees', { business: business.id }), 'btn small primary')),
          );
        } else if (row.kind === 'condition') {
          const worst = needsRepair(layout, 70)[0];
          if (worst) {
            card.appendChild(
              h('div', { class: 'btn-row' },
                button(`Repair the worst — ${money(repairCost(worst))}`, () => {
                  const result = repair(ctx.state, layout, worst.id);
                  toast(result.message, result.ok ? 'good' : 'bad');
                  canvas.draw();
                  refreshAll();
                }, 'btn small primary')),
            );
          }
        }
      }
      panel.appendChild(card);
    }
    host.appendChild(panel);
  }

  /**
   * Every place somebody works in this building, and who is at it.
   *
   * The same list the simulation reads, filtered the way a person actually
   * asks the question: what is empty, what is broken, what is half-equipped.
   */
  function renderWorkplaces(host: HTMLElement): void {
    const spots = layout.items
      .filter((placed) => (item(placed.defId)?.gives.desk ?? 0) > 0)
      .filter((placed) => {
        if (workplaceFilter === 'all') return true;
        const status = statusOf(layout, placed);
        if (workplaceFilter === 'free') return !placed.employeeId;
        if (workplaceFilter === 'taken') return Boolean(placed.employeeId);
        if (workplaceFilter === 'worn') return status === 'worn';
        return status === 'partial';
      });

    const panel = section('Places to work');
    const filters = h('div', { class: 'pill-row' });
    for (const [id, label] of [
      ['all', 'All'], ['free', 'Empty'], ['taken', 'Taken'],
      ['worn', 'Worn out'], ['partial', 'Missing kit'],
    ] as const) {
      filters.appendChild(
        h('button', {
          class: `chip${workplaceFilter === id ? ' active' : ''}`,
          on: { click: () => { workplaceFilter = id; renderRight(); } },
        }, label),
      );
    }
    panel.appendChild(filters);

    const unseated = ctx.state.employees.filter(
      (person) => person.companyId === ctx.state.playerCompanyId && !person.workplaceId
        && candidatesFor(ctx, layout, spots[0]?.id ?? '').some((c) => c.id === person.id),
    ).length;
    panel.appendChild(
      h('div', { class: 'btn-row' },
        button('Sit everybody down', () => {
          remember();
          const result = autoAssign(ctx.state, layout);
          toast(result.left > 0
            ? `${result.seated} seated. ${result.left} still have nowhere — build more.`
            : `${result.seated} seated, everybody has somewhere.`, result.left > 0 ? 'info' : 'good');
          canvas.draw();
          refreshAll();
        }, 'btn small'),
        unseated > 0 ? h('span', { class: 'tiny warn', text: `${unseated} with nowhere to work` }) : null),
    );

    if (spots.length === 0) {
      panel.appendChild(empty('Nothing here is somewhere a person works yet. A desk, a till, a range or a bench — whatever this trade runs on.'));
      host.appendChild(panel);
      return;
    }

    panel.appendChild(
      table(
        ['Workplace', 'Who', 'Condition', 'State'],
        spots.map((placed) => {
          const def = item(placed.defId);
          const person = ctx.state.employees.find((e) => e.id === placed.employeeId);
          const status = statusOf(layout, placed);
          const condition = Math.round(conditionOf(placed));
          return [
            def?.name ?? placed.defId,
            person ? person.name : h('span', { class: 'tiny muted', text: 'empty' }),
            h('span', { class: condition < 60 ? 'bad' : condition < 80 ? 'warn' : '', text: `${condition}%` }),
            tag(STATUS_WORDS[status], STATUS_TONES[status]),
          ];
        }),
        {
          onRowClick: (index) => {
            const placed = spots[index];
            selected = placed;
            selectedRoom = null;
            canvas.select(placed.id);
            renderRight();
          },
        },
      ),
    );
    host.appendChild(panel);
  }

  // ----------------------------------------------------------------- foot
  function renderFoot(): void {
    clear(foot);
    const company = playerCompany(ctx.state);
    const short = shortages(ctx.state);
    const open = playerBusinesses(ctx.state).filter((b) => b.status === 'open').length;
    foot.appendChild(
      h('div', { class: 'plan-foot-row' },
        footStat('cash', 'Cash', money(company.cash)),
        footStat('people', 'Employees', count(ctx.state.employees.filter((e) => e.companyId === company.id).length)),
        footStat('property', 'Buildings', count(buildings.length)),
        footStat('shop', 'Locations open', count(open)),
        short.length > 0
          ? footStat('warning', 'Short of desks', `${short.reduce((total, row) => total + row.shortage.short, 0)} people`, 'bad')
          : footStat('good', 'Everybody has a desk', 'yes', 'good')),
    );
  }

  function footStat(name: string, label: string, value: string, tone?: 'good' | 'bad'): HTMLElement {
    const wrap = h('div', { class: `plan-foot-stat${tone ? ` ${tone}` : ''}` });
    wrap.appendChild(icon(name, 15));
    wrap.appendChild(h('span', { class: 'tiny muted', text: label }));
    wrap.appendChild(h('strong', { text: value }));
    return wrap;
  }

  el.appendChild(head);
  el.appendChild(h('div', { class: 'plan-body' }, left, stage, right));
  el.appendChild(foot);
  refreshAll();

  requestAnimationFrame(() => {
    canvas.resize();
    canvas.fit();
  });

  return {
    el,
    update: () => {
      renderFoot();
    },
    destroy: () => canvas.destroy(),
  };
}



const NEED_WORDS: Record<string, string> = {
  critical: 'critical',
  warning: 'short',
  healthy: 'fine',
  spare: 'more than enough',
};

const NEED_TONES: Record<string, 'good' | 'warn' | 'bad' | 'muted'> = {
  critical: 'bad',
  warning: 'warn',
  healthy: 'good',
  spare: 'muted',
};

/** A need's figure, in whatever it is counted in. */
function figure(value: number, unit: string): string {
  if (unit === 'perHour') return `${Math.round(value)}/hr`;
  if (unit === 'units') return count(Math.round(value));
  if (unit === 'tiles') return `${Math.round(value)} tiles`;
  if (unit === 'percent') return `${Math.round(value)}%`;
  return String(Math.round(value));
}

const STATUS_WORDS: Record<string, string> = {
  operational: 'working',
  partial: 'missing what it needs',
  worn: 'worn out',
  unassigned: 'nobody at it',
};

const STATUS_TONES: Record<string, 'good' | 'warn' | 'bad' | 'muted'> = {
  operational: 'good',
  partial: 'bad',
  worn: 'warn',
  unassigned: 'muted',
};

/** A dependency, in words rather than as the key it is stored under. */
function dependencyName(key: string): string {
  const words: Record<string, string> = {
    equips: 'something to work with',
    desk: 'a desk',
    server: 'server capacity',
    cold: 'refrigeration',
    storage: 'somewhere to put things',
  };
  return words[key] ?? key;
}

/** Everybody in this building who could take a given place of work. */
function candidatesFor(ctx: Ctx, layout: Layout, itemId: string) {
  return ctx.state.employees.filter(
    (person) => person.companyId === ctx.state.playerCompanyId && canAssign(ctx.state, layout, itemId, person.id).ok,
  );
}

// ------------------------------------------------------------------ helpers

function nextRot(rot: Rotation): Rotation {
  return (((rot + 90) % 360) as Rotation);
}

/** Buildings the company holds that are worth laying out. */
function designableBuildings(ctx: Ctx): Building[] {
  return ctx.state.buildings.filter((building) => building.occupantCompanyId === ctx.state.playerCompanyId);
}

function labelFor(ctx: Ctx, building: Building): string {
  if (ctx.state.headOffice?.buildingId === building.id) return 'head office';
  const business = ctx.state.businesses.find((b) => b.buildingId === building.id);
  if (business) return business.name;
  const warehouse = ctx.state.warehouses.find((w) => w.buildingId === building.id);
  if (warehouse) return warehouse.name;
  return 'empty';
}

/** What an item is for, said once, in the same words the simulation uses. */
function givesLine(def: ItemDef): string {
  const parts: string[] = [];
  const g = def.gives;
  if (g.desk) parts.push(`${g.desk} place${g.desk === 1 ? '' : 's'} to work`);
  if (g.equips) parts.push('makes a desk into a job');
  if (g.meeting) parts.push(`seats ${g.meeting} round a table`);
  if (g.training) parts.push('somewhere to teach people');
  if (g.rest) parts.push('somewhere that is not a desk');
  if (g.storage) parts.push(`${g.storage} units of storage`);
  if (g.sanitary) parts.push(`plumbing for ${g.sanitary} people`);
  if (g.reception) parts.push('somewhere to be met');
  if (g.management) parts.push('somewhere the company is run from');
  if (g.production) parts.push('somewhere things get made');
  if (g.comfort) parts.push('makes the place better to be in');
  return parts.join(' · ');
}

function roomDoes(room: Room): string {
  switch (room.kind) {
    case 'work': return `${Math.min(room.gives.desk, room.gives.equips)} people can work in here.`;
    case 'meeting': return 'Somewhere to have a conversation that is not across the floor.';
    case 'training': return 'Courses run faster and cost less, everywhere in the company.';
    case 'break': return 'Somewhere to stop for ten minutes, which is worth real morale.';
    case 'storage': return `${room.gives.storage} units of stock can live in here.`;
    case 'reception': return 'Somebody is met when they walk in rather than left standing.';
    case 'sanitary': return `Plumbing for ${room.gives.sanitary} people.`;
    case 'management': return 'Where the company is actually run from.';
    case 'production': return 'Where things get made.';
    default: return 'Nothing in it yet.';
  }
}

/** Exposed so the browser tests can drive the editor without a mouse. */
export function designerHandle(): DesignerCanvas | null {
  return DesignerCanvas.current;
}

// Re-exported so the item catalogue is reachable from one import in tests.
export { ITEMS, item, buildingById };
