/**
 * The workforce planner.
 *
 * One screen for the question "is anybody going to be in on Friday evening",
 * asked across every business at once and then answered for one of them in
 * detail. The top half is the company: coverage, what the rota costs, who is
 * on the payroll and not on any rota. The bottom half is a week you can edit
 * an hour at a time.
 *
 * The generator has a button here, but the button is not the point — the
 * report under it is. A rota that appears with no explanation is a rota the
 * player has to audit by hand before they trust it, which is the work the
 * button was meant to save.
 */

// Kept across rebuilds — the view is thrown away and remade several times a
// second, and settings the player chose and a report they are still reading
// have no business disappearing with it.
let settings: SchedulerSettings = defaultSettings();
let lastReport: { businessId: string; report: ScheduleReport } | null = null;
let openDay: DayIndex = 0;
let picked: string | null = null;

const SETTING_LABELS: { key: keyof SchedulerSettings; label: string; detail: string }[] = [
  { key: 'respectContracts', label: 'Keep to contracted hours', detail: 'Never roster anybody past the hours their contract says.' },
  { key: 'respectPreferences', label: 'Respect days off', detail: 'Avoid the days people asked to keep, where there is any alternative.' },
  { key: 'watchCost', label: 'Watch the wage bill', detail: 'Prefer the cheaper person when either would do.' },
  { key: 'preferSkilled', label: 'Best people on the busiest hours', detail: 'Costs more, and the busy hours go better.' },
  { key: 'neverAlone', label: 'Nobody works alone', detail: 'Leave an hour short rather than put one person on by themselves.' },
];

export function workforceView(ctx: Ctx): View {
  const el = h('div', { class: 'view' });

  const render = (): void => {
    el.replaceChildren();
    const state = ctx.state;
    const businesses = playerBusinesses(state).filter((b) => b.status === 'open');

    el.appendChild(
      h(
        'div',
        { class: 'view-head' },
        h('h1', { text: 'Workforce' }),
        h('p', { text: 'Who is in, when, and what that costs — across every business you run.' }),
      ),
    );

    if (businesses.length === 0) {
      el.appendChild(
        empty('There is nothing to staff yet.', {
          title: 'No businesses open',
          action: button('Open one', () => ctx.go('businesses'), 'btn primary'),
        }),
      );
      return;
    }

    const selected =
      businesses.find((b) => b.id === (ctx.params.business ?? picked)) ?? businesses[0];
    picked = selected.id;

    el.appendChild(headline(state, businesses));
    el.appendChild(settingsPanel(ctx, businesses, render));
    if (lastReport) {
      const business = businesses.find((b) => b.id === lastReport?.businessId);
      if (business) el.appendChild(reportPanel(business, lastReport.report));
    }
    el.appendChild(coveragePanel(ctx, render));
    el.appendChild(editorPanel(ctx, businesses, selected, render));
    el.appendChild(problemsPanel(ctx, businesses));
  };

  render();
  return { el, update: undefined };
}

// ----------------------------------------------------------- the company

function headline(state: Ctx['state'], businesses: Business[]): HTMLElement {
  const rows = plannerRows(state);
  const company = companyCoverage(state);
  const cost = rows.reduce((total, row) => total + row.cost, 0);
  const hours = rows.reduce((total, row) => total + row.rostered, 0);
  const unrostered = businesses.filter((b) => !hasRota(state, b.id)).length;
  const idle = state.employees.filter(
    (person) =>
      person.companyId === state.playerCompanyId &&
      businesses.some((b) => b.id === person.businessId) &&
      weeklyHours(state, person.id) === 0 &&
      hasRota(state, person.businessId ?? ''),
  ).length;

  return h(
    'div',
    { class: 'grid cols-4' },
    kpi({
      label: 'Hours covered',
      value: company.businesses === 0 ? '—' : `${Math.round(company.overall * 100)}%`,
      sub: company.businesses === 0 ? 'No rota written yet' : `across ${company.businesses} business${company.businesses === 1 ? '' : 'es'}`,
      icon: 'clock',
      tone: 'accent',
      valueTone: company.businesses === 0 ? undefined : company.overall >= 0.9 ? 'good' : company.overall < 0.7 ? 'bad' : undefined,
    }),
    kpi({
      label: 'Rostered a week',
      value: `${hours} h`,
      sub: `${money(cost)} of wages`,
      icon: 'people',
      tone: 'info',
    }),
    kpi({
      label: 'Without a rota',
      value: `${unrostered}`,
      sub: unrostered === 0 ? 'Every business has one' : 'Everybody turns up, all day',
      icon: 'warning',
      tone: unrostered === 0 ? 'good' : 'warn',
    }),
    kpi({
      label: 'On nobody’s rota',
      value: `${idle}`,
      sub: idle === 0 ? 'Everybody has hours' : 'Paid, and not scheduled',
      icon: 'alert',
      tone: idle === 0 ? 'good' : 'bad',
      valueTone: idle === 0 ? 'good' : 'bad',
    }),
  );
}

// -------------------------------------------------------------- settings

function settingsPanel(ctx: Ctx, businesses: Business[], render: () => void): HTMLElement {
  const boxes = h('div', { class: 'grid cols-3' });
  for (const option of SETTING_LABELS) {
    const input = h('input', {
      type: 'checkbox',
      checked: settings[option.key],
      on: {
        change: () => {
          settings = { ...settings, [option.key]: input.checked };
        },
      },
    });
    boxes.appendChild(
      h(
        'label',
        { class: 'check-card' },
        input,
        h(
          'span',
          {},
          h('strong', { text: option.label }),
          h('span', { class: 'sub', text: option.detail }),
        ),
      ),
    );
  }

  return section(
    'How the schedule should be written',
    h('p', { class: 'sub', text: 'These are rules the generator keeps to. Turn one off and it will trade it away to cover an hour.' }),
    boxes,
    h(
      'div',
      { class: 'row' },
      button(
        'Write the week, everywhere',
        () => {
          let covered = 0;
          let worst: { business: Business; report: ScheduleReport } | null = null;
          for (const business of businesses) {
            const report = generateRota(ctx.state, business, settings);
            covered += report.coverage;
            if (!worst || report.coverage < worst.report.coverage) worst = { business, report };
          }
          if (worst) lastReport = { businessId: worst.business.id, report: worst.report };
          const average = Math.round((covered / businesses.length) * 100);
          toast(`${businesses.length} rotas written — ${average}% of wanted hours covered.`, average >= 85 ? 'good' : 'info');
          render();
        },
        'btn primary',
      ),
      button('Tear them all up', () => {
        for (const business of businesses) clearRota(ctx.state, business.id);
        lastReport = null;
        toast('Every rota cleared. Everybody is in all day again.', 'info');
        render();
      }),
    ),
  );
}

// ---------------------------------------------------------- the report

/**
 * What the generator did, and what it could not.
 *
 * The problems come first. A player who reads one line of this should read the
 * line that costs them money.
 */
function reportPanel(business: Business, report: ScheduleReport): HTMLElement {
  const lines = h('div', {});
  const line = (severity: 'warning' | 'opportunity', headline: string): HTMLElement =>
    h(
      'div',
      { class: `advice-row ${severity}` },
      severityTile(severity),
      h('div', {}, h('div', { class: 'advice-headline', text: headline })),
    );

  for (const problem of report.problems) lines.appendChild(line('warning', problem));
  for (const good of report.good) lines.appendChild(line('opportunity', good));

  return h(
    'section',
    { class: `panel${report.problems.length > 0 ? ' panel-danger' : ''}` },
    h(
      'div',
      { class: 'row-between' },
      h('h3', { class: 'panel-title', text: `Schedule written — ${business.name}` }),
      tag(`${Math.round(report.coverage * 100)}% covered`, report.coverage >= 0.9 ? 'good' : report.coverage < 0.7 ? 'bad' : 'warn'),
    ),
    lines,
    report.advice
      ? h('p', { class: 'advice-action', text: report.advice })
      : h('p', { class: 'sub', text: 'Nothing left over. The week is covered.' }),
  );
}

// ------------------------------------------------------- every business

function coveragePanel(ctx: Ctx, render: () => void): HTMLElement {
  const rows = plannerRows(ctx.state);
  return section(
    'Every business',
    table(
      ['Business', 'People', 'Covered', 'Hours', 'Wages a week', ''],
      rows.map((row) => [
        h(
          'div',
          {},
          h('strong', { text: row.business.name }),
          h('span', { class: 'sub', text: row.hasRota ? 'On a rota' : 'No rota — everybody in, all day' }),
        ),
        `${row.people}`,
        h(
          'div',
          {},
          h('span', {
            class: row.coverage >= 0.9 ? 'good' : row.coverage < 0.7 ? 'bad' : '',
            text: row.hasRota ? `${Math.round(row.coverage * 100)}%` : '—',
          }),
          bar(row.hasRota ? row.coverage : 0, row.coverage >= 0.9 ? 'good' : row.coverage < 0.7 ? 'bad' : ''),
        ),
        `${row.rostered} h`,
        money(row.cost),
        h(
          'div',
          { class: 'row' },
          button('Open', () => {
            picked = row.business.id;
            render();
          }),
          button(
            row.hasRota ? 'Rewrite' : 'Write it',
            () => {
              const report = generateRota(ctx.state, row.business, settings);
              lastReport = { businessId: row.business.id, report };
              picked = row.business.id;
              toast(
                report.problems.length === 0
                  ? `${row.business.name}: the week is covered.`
                  : `${row.business.name}: ${report.problems.length} thing${report.problems.length === 1 ? '' : 's'} it could not solve.`,
                report.problems.length === 0 ? 'good' : 'info',
              );
              render();
            },
            'btn primary',
          ),
        ),
      ]),
    ),
  );
}

// ----------------------------------------------------------- the editor

/**
 * One week, one business, an hour at a time.
 *
 * Rows are people, columns are the hours the place is open. A cell says one of
 * four things: they are on, they are free, they are somewhere else, or they
 * cannot work it at all — and clicking it is the whole edit. The row above the
 * grid is what the business wanted against what it got, so the gap the
 * generator reported has a place on the screen you can point at.
 */
function editorPanel(ctx: Ctx, businesses: Business[], business: Business, render: () => void): HTMLElement {
  const state = ctx.state;
  const staff = employeesOf(state, business.id);
  const opens = business.openFrom;
  const closes = business.openTo > business.openFrom ? business.openTo : 24;
  const hours: number[] = [];
  for (let hour = opens; hour < closes; hour += 1) hours.push(hour);

  const head = h(
    'div',
    { class: 'row rota-bar' },
    pills(
      businesses.map((b) => ({ value: b.id, label: nameFor(state, businesses, b) })),
      business.id,
      (value) => {
        picked = value;
        render();
      },
    ),
  );

  const days = pills(
    DAYS.map((name, index) => ({
      value: String(index),
      label: name.slice(0, 3),
      count: shiftsFor(state, business.id, index as DayIndex).length,
    })),
    String(openDay),
    (value) => {
      openDay = Number(value) as DayIndex;
      render();
    },
  );

  if (staff.length === 0) {
    return section(
      `The week at ${business.name}`,
      head,
      empty(`Nobody works at ${business.name} yet.`, {
        action: button('Hire somebody', () => ctx.go('employees'), 'btn primary'),
      }),
    );
  }

  const grid = h('div', { class: 'rota-grid', style: `--rota-hours:${hours.length}` });

  // The hour headings.
  grid.appendChild(h('div', { class: 'rota-name rota-head', text: DAYS[openDay] }));
  for (const hour of hours) {
    grid.appendChild(h('div', { class: 'rota-head rota-hour', text: String(hour).padStart(2, '0') }));
  }

  // Wanted against on, for every hour of the chosen day.
  grid.appendChild(h('div', { class: 'rota-name rota-total', text: 'On / wanted' }));
  for (const hour of hours) {
    const want = wantedAt(state, business, openDay, hour);
    const on = shiftsFor(state, business.id, openDay).filter(
      (shift) => hour >= shift.from && hour < shift.to,
    ).length;
    const short = on < want;
    grid.appendChild(
      h('div', {
        class: `rota-total rota-cover${short ? ' short' : ''}${on > want ? ' over' : ''}`,
        text: `${on}/${want}`,
        title: short ? `${want - on} short at ${hour}:00` : `${on} on at ${hour}:00`,
      }),
    );
  }

  // And a row per person.
  for (const person of staff) {
    grid.appendChild(personLabel(state, person));
    for (const hour of hours) {
      grid.appendChild(cellFor(ctx, business, person, hour, render));
    }
  }

  const rota = shiftsFor(state, business.id);
  const coverage = coverageOf(state, business);

  return section(
    `The week at ${business.name}`,
    head,
    h(
      'div',
      { class: 'row rota-bar' },
      days,
      h(
        'div',
        { class: 'row' },
        button(
          'Write this one',
          () => {
            const report = generateRota(state, business, settings);
            lastReport = { businessId: business.id, report };
            render();
          },
          'btn primary',
        ),
        button('Clear it', () => {
          clearRota(state, business.id);
          lastReport = null;
          render();
        }),
      ),
    ),
    h('div', { class: 'rota-scroll' }, grid),
    h(
      'div',
      { class: 'row rota-key' },
      h('span', { class: 'sub', text: `${rota.length} shifts, ${coverage.rostered} hours, ${Math.round(coverage.overall * 100)}% of what the week wanted.` }),
      h('span', { class: 'rota-legend' }, h('span', { class: 'rota-chip on' }), 'on'),
      h('span', { class: 'rota-legend' }, h('span', { class: 'rota-chip' }), 'free'),
      h('span', { class: 'rota-legend' }, h('span', { class: 'rota-chip away' }), 'elsewhere'),
      h('span', { class: 'rota-legend' }, h('span', { class: 'rota-chip no' }), 'cannot'),
    ),
  );
}

/**
 * A business by name, and by where it is when the name is not enough.
 *
 * Two shops of the same trade in one city end up with the same name, and a
 * picker with two identical buttons on it is a picker you cannot use.
 */
function nameFor(state: Ctx['state'], all: Business[], business: Business): string {
  const twins = all.filter((other) => other.name === business.name).length > 1;
  if (!twins) return business.name;
  const building = state.buildings.find((b) => b.id === business.buildingId);
  return building ? `${business.name} · ${district(building.district).name}` : business.name;
}

function personLabel(state: Ctx['state'], person: Employee): HTMLElement {
  const contract = contractOf(person);
  const hours = weeklyHours(state, person.id);
  // Measured against what they want rather than what they will tolerate: a
  // part-timer who asked for twenty hours and has been given twenty-eight is
  // not a green number, even though it is inside their contract.
  const tone =
    hours > contract.max || hours < contract.min
      ? 'bad'
      : Math.abs(hours - contract.prefers) > 3
        ? 'warn'
        : 'good';
  return h(
    'div',
    { class: 'rota-name' },
    h('strong', { text: person.name }),
    h('span', {
      class: `sub ${tone}`,
      text: `${contract.name} · ${hours}h of ${contract.prefers}`,
    }),
  );
}

function cellFor(
  ctx: Ctx,
  business: Business,
  person: Employee,
  hour: number,
  render: () => void,
): HTMLElement {
  const state = ctx.state;
  const mine = (state.shifts ?? []).filter(
    (shift) => shift.employeeId === person.id && shift.day === openDay && hour >= shift.from && hour < shift.to,
  );
  const here = mine.find((shift) => shift.businessId === business.id);
  const elsewhere = mine.find((shift) => shift.businessId !== business.id);
  const able = canWork(person, openDay, hour);

  let kind = 'free';
  let label = '';
  if (here) kind = 'on';
  else if (elsewhere) kind = 'away';
  else if (!able) kind = 'no';
  else if (reluctantAbout(person, openDay)) kind = 'rather-not';

  if (here) label = '●';
  else if (elsewhere) label = '·';

  const reason = here
    ? `${person.name} is on ${String(hour).padStart(2, '0')}:00 — click to take the hour off.`
    : elsewhere
      ? `${person.name} is at another business that hour.`
      : !able
        ? `${person.name} is not available ${DAYS[openDay]} at ${String(hour).padStart(2, '0')}:00.`
        : canWorkShift(state, person.id, business.id, openDay, hour, hour + 1).reason ||
          `Put ${person.name} on at ${String(hour).padStart(2, '0')}:00.`;

  return h('button', {
    class: `rota-cell ${kind}`,
    title: reason,
    aria: { label: reason },
    text: label,
    on: {
      click: () => {
        const result = toggleHour(state, person.id, business.id, openDay, hour);
        if (!result.ok) toast(result.message, 'bad');
        else if (result.message) toast(result.message, 'info');
        render();
      },
    },
  });
}

// ---------------------------------------------------------- the problems

/**
 * Where the rota and the people disagree, and who has nowhere to stand.
 *
 * Both halves are things the player can fix, and neither is visible anywhere
 * else: a person on the payroll and not on any rota is money going out for
 * nothing, and a person with no workstation is somebody the scheduler will
 * keep declining to use.
 */
function problemsPanel(ctx: Ctx, businesses: Business[]): HTMLElement {
  const state = ctx.state;
  const problems = rotaProblems(state);

  const homeless: { person: Employee; business: Business }[] = [];
  for (const business of businesses) {
    if (!layoutOf(state, business.buildingId)) continue;
    for (const person of employeesOf(state, business.id)) {
      if (!person.workplaceId) homeless.push({ person, business });
    }
  }

  const body = h('div', {});

  if (problems.length === 0 && homeless.length === 0) {
    body.appendChild(empty('Nobody is over their hours, under their hours, or without a desk.', { title: 'Nothing to sort out' }));
  }

  if (problems.length > 0) {
    body.appendChild(
      table(
        ['Who', 'What', 'Where it hurts'],
        problems.map((problem) => [
          problem.name,
          tag(
            problem.kind === 'overworked'
              ? 'Over hours'
              : problem.kind === 'underused'
                ? 'Short of hours'
                : problem.kind === 'unwilling'
                  ? 'Days they asked to keep'
                  : 'Not on the rota',
            problem.kind === 'overworked' || problem.kind === 'nothing' ? 'bad' : 'warn',
          ),
          problem.detail,
        ]),
      ),
    );
  }

  if (homeless.length > 0) {
    body.appendChild(
      h('p', {
        class: 'advice-detail',
        text: `${homeless.length} ${homeless.length === 1 ? 'person has' : 'people have'} nowhere to work: ${homeless
          .slice(0, 4)
          .map((row) => `${row.person.name} at ${row.business.name}`)
          .join(', ')}${homeless.length > 4 ? ', and others' : ''}. Build them somewhere and the scheduler will start using them properly.`,
      }),
    );
    body.appendChild(
      h('div', { class: 'row' }, button('Lay out a building', () => ctx.go('designer'), 'btn primary')),
    );
  }

  return section(
    `What the rota cannot fix by itself${problems.length + homeless.length > 0 ? ` — ${problems.length + homeless.length}` : ''}`,
    body,
  );
}

/** Exposed so the nav can say how many things want attention without opening. */
export function workforceBadge(state: Ctx['state']): number {
  return rotaProblems(state).length;
}
