import type { GameState } from './state';
import { buildingById, employeesOf, playerBusinesses } from './state';
import type { Business } from './types';
import { businessTypeOrThrow } from '../data/businessTypes';
import { layoutOf, needsRepair, totals, upkeepOf, wearDaily } from './layout';
import { post } from './finance';
import { pushAlert } from './alerts';
import { clamp } from './util';

/**
 * What a designed building does to the company that works in it.
 *
 * This is the only file that turns a floor plan into consequences, and every
 * one of them replaces a figure the game was already using rather than adding a
 * second one alongside it. That distinction is the whole of the design:
 *
 *   Before                              After a layout exists
 *   ------------------------------      ------------------------------
 *   "roughly one head per role slot"    the number of workstations you built
 *   the head office level's desk count  the number of workstations you built
 *   the building's storage capacity     plus whatever racking you put in
 *   training runs at the room's speed   the training room you actually built
 *
 * A building with no layout returns nothing from any of this and every one of
 * those figures stays exactly as it was — which is what makes the whole feature
 * additive, and why every save made before it existed carries on unchanged.
 *
 * Nothing here is a new stat on a screen. Capacity is the thing that stops you
 * hiring; storage is the thing that stops you ordering; comfort is read by the
 * morale that was already being calculated every night.
 */

/** The totals for a building, or nothing if the player never designed it. */
export function premisesOf(state: GameState, buildingId: string | null | undefined) {
  if (!buildingId) return null;
  const layout = layoutOf(state, buildingId);
  if (!layout) return null;
  return totals(layout);
}

/** The totals for wherever a business trades. */
export function premisesFor(state: GameState, business: Business) {
  return premisesOf(state, business.buildingId);
}

// ------------------------------------------------------------- capacity

/**
 * How many people a place can hold.
 *
 * Once a building has been fitted out, this is a count of the workstations in
 * it — desks with something on them — rather than an estimate from the kind of
 * business it is. That is the mechanic in one line: to hire the sixteenth
 * person you have to have built the sixteenth desk.
 *
 * A building nobody has designed still answers the way it always did, so this
 * can be dropped into the hiring path without changing a single existing game.
 */
export function capacityOf(state: GameState, business: Business): number {
  const type = businessTypeOrThrow(business.typeId);
  const assumed = Math.max(2, type.roles.length * 3);
  const premises = premisesFor(state, business);
  if (!premises) return assumed;
  // The owner can always work somewhere, so a fitted-out building never holds
  // fewer than one — otherwise an empty shell would lock the player out of
  // their own shop with no way back.
  return Math.max(1, premises.workstations);
}

export interface Shortage {
  people: number;
  workstations: number;
  short: number;
}

/** Where there are more people than there are places for them to work. */
export function shortages(state: GameState): { business: Business; shortage: Shortage }[] {
  const out: { business: Business; shortage: Shortage }[] = [];
  for (const business of playerBusinesses(state)) {
    if (business.status !== 'open') continue;
    const premises = premisesFor(state, business);
    if (!premises) continue;
    const people = employeesOf(state, business.id).length;
    if (people <= premises.workstations) continue;
    out.push({
      business,
      shortage: { people, workstations: premises.workstations, short: people - premises.workstations },
    });
  }
  return out;
}

// --------------------------------------------------------------- the room

/**
 * How pleasant a place is to spend a day in, 0..1 where a half is unremarkable.
 *
 * Three things, all of them physical and all of them the player's doing: how
 * much room each person has, whether there is anywhere to stop for ten minutes,
 * and whether anybody thought about the place at all. A warehouse with sixty
 * people and one chair scores badly and should.
 */
export function comfortOf(state: GameState, buildingId: string | null, people: number): number {
  const premises = premisesOf(state, buildingId);
  if (!premises) return 0.5;
  const heads = Math.max(1, people);

  // Tiles of floor each person has. Cramped below four, comfortable by ten.
  const room = clamp((premises.area / heads - 4) / 6, -1, 1);
  // Somewhere that is not a desk, for the people who work here.
  const rest = clamp(premises.rest / (heads * 0.5), 0, 1);
  // And whether the place has had any thought put into it at all.
  const care = clamp(premises.comfort / (heads * 0.8), 0, 1);
  // Plumbing is not a nicety. A building of any size without it is a problem.
  const plumbed = premises.sanitary >= heads ? 0 : -0.25;

  return clamp(0.5 + room * 0.28 + rest * 0.14 + care * 0.12 + plumbed, 0, 1);
}

/**
 * What the premises do to how people feel, as morale points.
 *
 * Bounded either way and centred on nothing: a building nobody has designed
 * contributes zero, a well-arranged one is worth a handful of points, and a
 * cramped one with nowhere to sit takes the same handful away. It is added to
 * the morale calculation that already existed rather than being a second
 * morale of its own.
 */
export function premisesMorale(state: GameState, business: Business | null): number {
  if (!business) return 0;
  const premises = premisesFor(state, business);
  if (!premises) return 0;
  const people = employeesOf(state, business.id).length;
  return (comfortOf(state, business.buildingId, people) - 0.5) * 22;
}

/**
 * And what they do to how well the work goes.
 *
 * A multiplier on what the team gets through, between about 0.9 and 1.08.
 * Small on purpose — a good office does not double anybody's output, it just
 * stops a bad one getting in the way.
 */
export function premisesThroughput(state: GameState, business: Business): number {
  const premises = premisesFor(state, business);
  if (!premises) return 1;
  const people = employeesOf(state, business.id).length;
  const comfort = comfortOf(state, business.buildingId, people);
  // And somewhere to meet, which is what stops a team of fifteen having every
  // conversation across the room at everybody else.
  const meets = premises.meeting > 0 || people < 6 ? 0.01 : -0.02;
  return clamp(0.9 + comfort * 0.18 + meets, 0.86, 1.1);
}

// ------------------------------------------------------------- storage

/**
 * Racking, shelving and the back room.
 *
 * Added to what the building itself holds rather than replacing it: the back
 * room existed before anybody put a shelf in it, and shelves are what turn the
 * rest of the floor into somewhere stock can go.
 */
export function extraStorage(state: GameState, business: Business): number {
  return premisesFor(state, business)?.storage ?? 0;
}

// -------------------------------------------------------------- training

/**
 * Whether there is somewhere in the company people can actually be taught.
 *
 * The head office already had a training centre, bought as a project. A
 * training room the player has physically built does the same job, and this is
 * the one function both answers come through — so it is still one figure, with
 * two ways of earning it, rather than two systems that each think they own it.
 */
export function builtTrainingRoom(state: GameState): boolean {
  return (state.layouts ?? []).some((layout) => {
    const rooms = totals(layout).rooms;
    return rooms.some((room) => room.kind === 'training' && room.complete);
  });
}

// ----------------------------------------------------------------- alerts

/**
 * Telling the player when the building has become the problem.
 *
 * Said once a month rather than every night, and only about things they can
 * actually do something about this afternoon.
 */
/**
 * A day of wear, and the bill for keeping it all standing.
 *
 * Both are charged here rather than in the designer, because both are
 * consequences of trading rather than of building: a shop that is open wears
 * out its tills, and a shop that is shut does not.
 */
export function assetsDaily(state: GameState): void {
  for (const layout of state.layouts ?? []) {
    const business = playerBusinesses(state).find((b) => b.buildingId === layout.buildingId);
    const inUse = business ? business.status === 'open' : state.headOffice?.buildingId === layout.buildingId;
    wearDaily(layout, inUse);
    const bill = upkeepOf(layout);
    if (bill > 0 && inUse) {
      post(
        state,
        state.playerCompanyId,
        'utilities',
        `Upkeep — ${buildingById(state, layout.buildingId)?.address ?? 'premises'}`,
        -bill / 30,
        business?.id ?? null,
      );
    }
  }
}

export function premisesDaily(state: GameState): void {
  // Anything badly worn is worth saying once a month, because it is costing
  // output every day it is left.
  if (state.day % 30 === 0) {
    for (const layout of state.layouts ?? []) {
      const failing = needsRepair(layout, 45);
      if (failing.length === 0) continue;
      const business = playerBusinesses(state).find((b) => b.buildingId === layout.buildingId);
      pushAlert(
        state,
        'warning',
        `Equipment is wearing out at ${business?.name ?? 'your premises'}`,
        `${failing.length} ${failing.length === 1 ? 'thing is' : 'things are'} below half condition and doing less than ${failing.length === 1 ? 'it' : 'they'} should. Repairing is cheaper than replacing.`,
        business?.id ?? null,
        'designer',
      );
      break;
    }
  }
  if (state.day % 30 !== 0) return;
  const short = shortages(state);
  if (short.length > 0) {
    const worst = short.sort((a, b) => b.shortage.short - a.shortage.short)[0];
    pushAlert(
      state,
      'warning',
      `Not enough desks at ${worst.business.name}`,
      `${worst.shortage.people} people and ${worst.shortage.workstations} workstation${worst.shortage.workstations === 1 ? '' : 's'}. ${worst.shortage.short} of them have nowhere of their own to work, and you cannot take anybody else on there until you build somewhere for them.`,
      worst.business.id,
      'designer',
    );
    return;
  }

  // And the quieter problem: a place that is full rather than over-full.
  for (const business of playerBusinesses(state)) {
    if (business.status !== 'open') continue;
    const premises = premisesFor(state, business);
    if (!premises || premises.workstations === 0) continue;
    const people = employeesOf(state, business.id).length;
    if (people < premises.workstations || premises.workstations > 60) continue;
    const building = buildingById(state, business.buildingId);
    pushAlert(
      state,
      'info',
      `${business.name} is full`,
      `Every one of the ${premises.workstations} workstation${premises.workstations === 1 ? '' : 's'} is taken. Building more means either fitting out the space you have${building && building.floors > 1 ? ', opening the floor above,' : ''} or taking somewhere bigger.`,
      business.id,
      'designer',
    );
    return;
  }
}
