import type { Agent } from '../sim/floor';
import { alpha, shade } from './sprites';
import { LEVEL, box as isoBox, project, shadow, shadow as isoShadow } from './iso';

/**
 * The people.
 *
 * Employees and customers drawn as people rather than as dots, from the same
 * light and the same scale as everything else in the room. A person is about
 * eleven pixels wide and twenty-six tall at 1×, which is small — so the work
 * here is in the silhouette and the colour rather than in detail nobody can
 * see: you should be able to tell a cook from a cashier from a customer across
 * a busy shop floor, and tell which of them is standing still.
 *
 * Appearance is derived from the person's own `look` number, which comes from
 * their id, so the same employee is the same person every time the player opens
 * the floor — never a fresh random face on every frame.
 */

const SKIN = ['#e8c39a', '#c98f62', '#8d5a3b', '#f0d4b4', '#6f4630', '#d9a679'];
const HAIR = ['#2b2118', '#4b3220', '#7a5230', '#c39a55', '#8a8a92', '#1d1a24'];
const CIVVIES = ['#4f6480', '#7a5a7c', '#3f7a68', '#8a5a4a', '#5a5f7a', '#6f7a4a', '#7a4a52'];

/** What the staff of each kind of business wear, so a role reads at a glance. */
export const UNIFORMS: Record<string, string> = {
  cashier: '#2f7bff',
  sales: '#3f8fd0',
  server: '#2f9e73',
  cook: '#e8eaf0',
  technician: '#f59e0b',
  cleaner: '#4fb3a8',
  warehouse: '#e07a3d',
  driver: '#c4703a',
  marketer: '#8b5cf6',
  accountant: '#5a6577',
  manager: '#1f2b45',
  hr: '#a06fb8',
  analyst: '#4a7fa8',
  developer: '#38bdf8',
  designer: '#d4699a',
};

export interface PersonPaint {
  ctx: CanvasRenderingContext2D;
  agent: Agent;
  /** The shirt colour. Staff get their role's; customers get their own. */
  uniform?: string;
  /** Seconds, for the walk cycle. */
  time: number;
  /** Drawn brighter, with a ring, because the player is looking for them. */
  focus?: boolean;
}

/** How tall a person stands, in the same levels the furniture uses. */
const HEIGHT = 1.75;

export function paintPerson(p: PersonPaint): void {
  const { ctx, agent } = p;
  const look = agent.look;
  const skin = SKIN[look % SKIN.length];
  const hair = HAIR[(look >> 2) % HAIR.length];
  const shirt =
    p.uniform ?? (agent.kind === 'staff' ? UNIFORMS.sales : CIVVIES[(look >> 3) % CIVVIES.length]);
  const trousers = agent.kind === 'staff' ? '#2b3446' : shade(CIVVIES[(look >> 5) % CIVVIES.length], -0.3);

  const moving = agent.path.length > 0;
  // One walk cycle per stride, offset per person so a crowd does not march.
  const phase = moving ? p.time * 7 + look : 0;
  const bob = moving ? Math.abs(Math.sin(phase)) * 0.055 : 0;
  const swing = moving ? Math.sin(phase) * 0.055 : 0;

  const base = project(agent.x, agent.y, 0);
  shadow(ctx, agent.x - 0.18, agent.y - 0.18, 0.36, 0.36, moving ? 0.2 : 0.3);

  ctx.save();
  ctx.translate(base.x, base.y);

  if (p.focus) {
    // A ring on the floor, so "show me this person" actually shows them.
    ctx.save();
    ctx.scale(1, 0.5);
    ctx.strokeStyle = '#5b9bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 13, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  const px = (levels: number): number => -levels * LEVEL;

  // Legs, one forward and one back while walking.
  ctx.fillStyle = shade(trousers, -0.08);
  ctx.fillRect(-3.4 + swing * 20, px(0.72 + bob), 3, 12);
  ctx.fillStyle = trousers;
  ctx.fillRect(0.4 - swing * 20, px(0.72 + bob), 3, 12);

  // Torso.
  const torsoTop = px(1.32 + bob);
  ctx.fillStyle = shirt;
  ctx.fillRect(-4.2, torsoTop, 8.4, px(0.72 + bob) - torsoTop);
  // A darker side, for the light coming from the upper left.
  ctx.fillStyle = alpha('#000000', 0.16);
  ctx.fillRect(1.6, torsoTop, 2.6, px(0.72 + bob) - torsoTop);

  // Arms — one swings forward, and a carried thing hangs off the near one.
  ctx.fillStyle = shade(shirt, -0.12);
  ctx.fillRect(-6.2, torsoTop + 1, 2.2, 9 - swing * 12);
  ctx.fillRect(4, torsoTop + 1, 2.2, 9 + swing * 12);

  // Head and hair.
  const headY = px(HEIGHT + bob);
  ctx.fillStyle = skin;
  ctx.beginPath();
  ctx.arc(0, headY + 5, 4.6, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = hair;
  ctx.beginPath();
  ctx.arc(0, headY + 4.2, 4.6, Math.PI, Math.PI * 2);
  ctx.fill();
  if (look % 3 === 0) {
    // Longer hair on some of them, which is most of what makes a crowd read as
    // a crowd at this size.
    ctx.fillRect(-4.6, headY + 4, 9.2, 4.5);
  }

  ctx.restore();

  badge(p, base.x, base.y + px(HEIGHT + bob) - 6);
}

/**
 * The little mark over somebody's head.
 *
 * Only ever for something the player can act on: a queue that is not moving,
 * somebody with nowhere to work, a customer walking out unhappy. Nothing here
 * is atmosphere — if a badge is showing, something is costing money.
 */
function badge(p: PersonPaint, x: number, y: number): void {
  const { ctx, agent } = p;
  const mark = markFor(agent);
  if (!mark) return;

  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = mark.tone;
  ctx.beginPath();
  ctx.moveTo(0, 5);
  ctx.lineTo(-5, -1);
  ctx.arc(0, -5.5, 6.2, Math.PI * 0.78, Math.PI * 0.22, false);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#0b1020';
  ctx.font = '700 8px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(mark.glyph, 0, -5);
  ctx.restore();
}

function markFor(agent: Agent): { glyph: string; tone: string } | null {
  if (agent.kind === 'staff') {
    if (agent.state === 'stranded') return { glyph: '!', tone: '#ef4657' };
    if (agent.state === 'serving') return { glyph: '€', tone: '#2fbf7e' };
    return null;
  }
  if (agent.state === 'queueing') return { glyph: '…', tone: agent.patience < 25 ? '#f59e0b' : '#97a6c2' };
  if (agent.state === 'waiting') return { glyph: '…', tone: '#f59e0b' };
  if (agent.state === 'leaving' && agent.mood === 'cross') return { glyph: '✕', tone: '#ef4657' };
  if (agent.state === 'paying') return { glyph: '€', tone: '#2fbf7e' };
  return null;
}

/**
 * What is in somebody's hands.
 *
 * A basket for a customer who has picked something up, and a crate for a member
 * of staff crossing the floor with stock. Both say the same thing — this person
 * is in the middle of something — and both only appear when they actually are.
 */
export function paintCarried(ctx: CanvasRenderingContext2D, agent: Agent): void {
  const staffCarrying = agent.kind === 'staff' && agent.state === 'carrying';
  if (!agent.carrying && !staffCarrying) return;
  const base = project(agent.x, agent.y, 0);
  ctx.save();
  ctx.translate(base.x + (staffCarrying ? 0 : 6), base.y - LEVEL * (staffCarrying ? 1.05 : 0.85));

  if (staffCarrying) {
    // A crate held in front of them, in two tones so it reads as a box.
    ctx.fillStyle = '#c39a62';
    ctx.fillRect(-5, -4, 10, 7);
    ctx.fillStyle = alpha('#000000', 0.22);
    ctx.fillRect(1, -4, 4, 7);
    ctx.strokeStyle = alpha('#ffffff', 0.25);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-5, -1);
    ctx.lineTo(5, -1);
    ctx.stroke();
  } else {
    ctx.fillStyle = '#d4634b';
    ctx.fillRect(-3, -2, 6, 4.5);
    ctx.strokeStyle = alpha('#ffffff', 0.4);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, -2, 3, Math.PI, 0);
    ctx.stroke();
  }
  ctx.restore();
}

/**
 * A delivery lorry, pulled up with its shutter open.
 *
 * Drawn from the same boxes as everything else, so it belongs to the room it is
 * parked against. How full the back looks is how much of the load is still on
 * it, which is why it is worth watching rather than just being there.
 */
export function paintLorry(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  facing: number,
  left: number,
): void {
  const along = Math.abs(Math.cos(facing)) > 0.5;
  const w = along ? 3.2 : 1.7;
  const h = along ? 1.7 : 3.2;
  const bx = x - w / 2;
  const by = y - h / 2;

  isoShadow(ctx, bx, by, w, h, 0.3);
  // The body, and the cab at the front of it in a darker paint.
  isoBox(ctx, bx, by, w, h, 0.18, 2.5, '#d8dde6', 0.06);
  if (along) isoBox(ctx, bx, by, w * 0.3, h, 0.1, 1.9, '#4f6480', 0.04);
  else isoBox(ctx, bx, by, w, h * 0.3, 0.1, 1.9, '#4f6480', 0.04);

  // The open shutter at the back, with whatever is still on board behind it.
  const load = Math.max(0, Math.min(1, left));
  if (load > 0.02) {
    const inset = 0.22;
    isoBox(
      ctx,
      bx + (along ? w * 0.42 : inset),
      by + (along ? inset : h * 0.42),
      along ? w * 0.5 : w - inset * 2,
      along ? h - inset * 2 : h * 0.5,
      0.3,
      0.3 + 1.7 * load,
      '#b8874d',
      0.04,
    );
  }
  // Wheels, so it is standing on the road rather than hovering over it.
  for (const along01 of [0.22, 0.78]) {
    const wx = along ? bx + w * along01 : bx + w * 0.5;
    const wy = along ? by + h * 0.5 : by + h * along01;
    isoBox(ctx, wx - 0.12, wy - 0.12, 0.24, 0.24, 0, 0.24, '#242b3a', 0);
  }
}
